// Helper function to convert hex color codes to readable names
function hexToColorName(color: string): string {
  if (!color) return color;
  
  // If it's not a hex code, return as-is (already a name)
  if (!color.startsWith('#')) return color;
  
  // Common hex to name mappings
  const hexToName: Record<string, string> = {
    '#000000': 'Black',
    '#ffffff': 'White',
    '#808080': 'Grey',
    '#c0c0c0': 'Silver',
    '#ff0000': 'Red',
    '#00ff00': 'Lime',
    '#0000ff': 'Blue',
    '#ffff00': 'Yellow',
    '#ff00ff': 'Magenta',
    '#00ffff': 'Cyan',
    '#800000': 'Maroon',
    '#008000': 'Green',
    '#000080': 'Navy',
    '#808000': 'Olive',
    '#800080': 'Purple',
    '#008080': 'Teal',
    '#cd853f': 'Tan',
    '#ff1493': 'Pink',
    '#4169e1': 'Royal Blue',
    '#ffa500': 'Orange',
    '#a52a2a': 'Brown',
    '#f5f5dc': 'Beige',
    '#d2691e': 'Chocolate',
    '#dc143c': 'Crimson',
    '#2f4f4f': 'Dark Slate',
    '#696969': 'Dim Grey',
    '#b22222': 'Firebrick',
    '#ffd700': 'Gold',
    '#daa520': 'Goldenrod',
    '#f0e68c': 'Khaki',
    '#e6e6fa': 'Lavender',
    '#add8e6': 'Light Blue',
    '#90ee90': 'Light Green',
    '#ffb6c1': 'Light Pink',
    '#20b2aa': 'Light Sea Green',
    '#87ceeb': 'Sky Blue',
    '#708090': 'Slate Grey',
    '#fffafa': 'Snow',
    '#d2b48c': 'Tan',
    '#40e0d0': 'Turquoise',
    '#ee82ee': 'Violet',
    '#f5deb3': 'Wheat',
  };
  
  const normalizedHex = color.toLowerCase();
  if (hexToName[normalizedHex]) {
    return hexToName[normalizedHex];
  }
  
  // If no match found, return the hex code without the # symbol
  return color.replace('#', '').toUpperCase();
}

// Helper function to generate cryptographically secure random password
function generateSecurePassword(length: number = 12): string {
  const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const lowercase = 'abcdefghijklmnopqrstuvwxyz';
  const numbers = '0123456789';
  const symbols = '!@#$%^&*';
  const allChars = uppercase + lowercase + numbers + symbols;
  
  // Helper to get a random character from a string using crypto
  const getRandomChar = (chars: string): string => {
    const randomIndex = crypto.randomInt(0, chars.length);
    return chars[randomIndex];
  };
  
  // Ensure at least one character from each required set
  let password = '';
  password += getRandomChar(uppercase);
  password += getRandomChar(lowercase);
  password += getRandomChar(numbers);
  password += getRandomChar(symbols);
  
  // Fill remaining length with random characters from all sets
  for (let i = password.length; i < length; i++) {
    password += getRandomChar(allChars);
  }
  
  // Shuffle using Fisher-Yates algorithm with crypto.randomInt
  const chars = password.split('');
  for (let i = chars.length - 1; i > 0; i--) {
    const j = crypto.randomInt(0, i + 1);
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  
  return chars.join('');
}

// Carrier detection and tracking URL generation
interface CarrierInfo {
  name: string;
  trackingUrl: string | null;
}

function detectCarrier(trackingNumber: string): CarrierInfo {
  const cleaned = trackingNumber.replace(/\s/g, '').toUpperCase();
  
  // Royal Mail (UK): Usually starts with letters like "AA", "AB", etc., or is 13-14 chars
  if (/^[A-Z]{2}\d{9}GB$/i.test(cleaned)) {
    return {
      name: 'Royal Mail',
      trackingUrl: `https://www.royalmail.com/track-your-item#/tracking-results/${cleaned}`,
    };
  }
  
  // DPD UK: Usually 14 digits or starts with "DPD"
  if (/^\d{14}$/.test(cleaned) || cleaned.startsWith('DPD')) {
    return {
      name: 'DPD',
      trackingUrl: `https://track.dpd.co.uk/search?searchType=reference&reference=${cleaned}`,
    };
  }
  
  // Evri (formerly Hermes): Usually 16 character alphanumeric
  if (/^[A-Z0-9]{16}$/i.test(cleaned)) {
    return {
      name: 'Evri',
      trackingUrl: `https://www.evri.com/track/parcel/${cleaned}`,
    };
  }
  
  // UPS: 1Z followed by 16 chars
  if (/^1Z[A-Z0-9]{16}$/i.test(cleaned)) {
    return {
      name: 'UPS',
      trackingUrl: `https://www.ups.com/track?tracknum=${cleaned}`,
    };
  }
  
  // FedEx: 12-22 digits
  if (/^\d{12,22}$/.test(cleaned)) {
    return {
      name: 'FedEx',
      trackingUrl: `https://www.fedex.com/fedextrack/?trknbr=${cleaned}`,
    };
  }
  
  // DHL: 10 digits starting with JD, or 10-11 digits
  if (/^JD\d{18}$/i.test(cleaned) || /^\d{10,11}$/.test(cleaned)) {
    return {
      name: 'DHL',
      trackingUrl: `https://www.dhl.com/en/express/tracking.html?AWB=${cleaned}`,
    };
  }
  
  // Yodel: 12-16 character alphanumeric
  if (/^[A-Z0-9]{12,16}$/i.test(cleaned) && !cleaned.startsWith('1Z')) {
    return {
      name: 'Yodel',
      trackingUrl: `https://www.yodel.co.uk/track/${cleaned}`,
    };
  }
  
  // Default - unknown carrier
  return {
    name: 'Shipping Carrier',
    trackingUrl: null,
  };
}

