  // Vendor Login Route
  app.post("/api/auth/vendor/login", async (req, res) => {
    try {
      const { email, password } = loginSchema.parse(req.body);
      
      // Find user by email
      const user = await storage.getUserByEmail(email);
      if (!user || user.role !== "vendor") {
        return res.status(401).json({ error: "Invalid credentials" });
      }

      // Verify password
      if (!user.password) {
        return res.status(401).json({ error: "Invalid credentials" });
      }
      const isValid = await bcrypt.compare(password, user.password);
      if (!isValid) {
        return res.status(401).json({ error: "Invalid credentials" });
      }

      // Get vendor details
      const vendor = await storage.getVendorByUserId(user.id);
      if (!vendor) {
        return res.status(401).json({ error: "Vendor profile not found" });
      }

      if (vendor.approvalStatus === "rejected") {
        return res.status(403).json({ error: "Your vendor application has been rejected" });
      }

      if (vendor.approvalStatus === "pending") {
        req.session.userId = user.id;
        req.session.vendorId = vendor.id;
        return res.json({ 
          user: { id: user.id, email: user.email, role: user.role },
          vendor: { id: vendor.id, businessName: vendor.businessName, approvalStatus: "pending" }
        });
      }

      if (!vendor.isActive) {
        return res.status(401).json({ error: "Account not active" });
      }

      // Set session
      req.session.userId = user.id;
      req.session.vendorId = vendor.id;

      // Check if user also has APPROVED reseller access (some vendors can also be resellers)
      const reseller = await storage.getResellerByUserId(user.id);
      const hasApprovedResellerAccess = reseller && reseller.approvalStatus === "approved";
      
      // Determine redirect based on partner type:
      // - If user has approved reseller access, go to reseller dashboard (has EPOS, storefronts)
      // - Otherwise, go to wholesaler dashboard (simple product ordering)
      const redirectTo = hasApprovedResellerAccess ? "/reseller/dashboard" : "/wholesaler/dashboard";
      
      // Only set resellerId in session if reseller is APPROVED (security: prevent unauthorized reseller API access)
      if (hasApprovedResellerAccess) {
        req.session.resellerId = reseller.id;
      }
      
      res.json({ 
        user: { id: user.id, email: user.email, role: user.role },
        vendor: { id: vendor.id, businessName: vendor.businessName, approvalStatus: vendor.approvalStatus },
        redirectTo
      });
    } catch (error) {
      console.error("Vendor login error:", error);
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Unified B2B Login (Auto-detects Vendor or Reseller)
  app.post("/api/auth/b2b/login", async (req, res) => {
    try {
      const { email, password } = loginSchema.parse(req.body);
      
      // Find user by email
      const user = await storage.getUserByEmail(email);
      if (!user || (user.role !== "vendor" && user.role !== "reseller")) {
        return res.status(401).json({ error: "Invalid credentials" });
      }

      // Verify password
      if (!user.password) {
        return res.status(401).json({ error: "Invalid credentials" });
      }
      const isValid = await bcrypt.compare(password, user.password);
      if (!isValid) {
        return res.status(401).json({ error: "Invalid credentials" });
      }

      // Check for vendor account first (some users have both vendor and reseller)
      const vendor = await storage.getVendorByUserId(user.id);
      const reseller = await storage.getResellerByUserId(user.id);
      
      // Determine which accounts exist and are approved
      const hasApprovedVendor = vendor && vendor.approvalStatus === "approved";
      const hasApprovedReseller = reseller && reseller.approvalStatus === "approved";
      const hasPendingVendor = vendor && vendor.approvalStatus === "pending";
      const hasPendingReseller = reseller && reseller.approvalStatus === "pending";

      // If user has both vendor and reseller accounts that are approved
      // Priority: Always prioritize vendor access when both are approved
      if (hasApprovedVendor && hasApprovedReseller) {
        // Both are approved - vendor takes priority
        // Set both session IDs so they can access both dashboards
        req.session.userId = user.id;
        req.session.vendorId = vendor.id;
        req.session.resellerId = reseller.id;
        
        // Always redirect to vendor dashboard when both roles exist
        return res.json({ 
          user: { id: user.id, email: user.email, role: "vendor", hasBothRoles: true },
          redirectTo: "/vendor/dashboard"
        });
      }

      // Handle vendor-only login
      if (hasApprovedVendor) {
        req.session.userId = user.id;
        req.session.vendorId = vendor.id;
        if (reseller) req.session.resellerId = reseller.id; // Keep reseller access if they have it

        return res.json({ 
          user: { id: user.id, email: user.email, role: "vendor" },
          redirectTo: "/vendor/dashboard"
        });
      }

      // Handle reseller-only login
      if (hasApprovedReseller) {
        req.session.userId = user.id;
        req.session.resellerId = reseller.id;
        if (vendor) req.session.vendorId = vendor.id; // Keep vendor access if they have it

        return res.json({ 
          user: { id: user.id, email: user.email, role: "reseller" },
          redirectTo: "/reseller/dashboard"
        });
      }

      // Handle pending accounts
      if (hasPendingVendor && !hasApprovedReseller) {
        req.session.userId = user.id;
        req.session.vendorId = vendor.id;
        return res.json({ 
          user: { id: user.id, email: user.email, role: "vendor" },
          vendor: { id: vendor.id, businessName: vendor.businessName, approvalStatus: "pending" },
          redirectTo: "/vendor/dashboard"
        });
      }

      if (hasPendingReseller && !hasApprovedVendor) {
        req.session.userId = user.id;
        req.session.resellerId = reseller.id;
        return res.json({ 
          user: { id: user.id, email: user.email, role: "reseller" },
          reseller: { id: reseller.id, businessName: reseller.businessName, approvalStatus: "pending" },
          redirectTo: "/reseller/dashboard"
        });
      }

      // Check for rejected accounts
      if (vendor?.approvalStatus === "rejected" && (!reseller || reseller.approvalStatus === "rejected")) {
        return res.status(403).json({ error: "Your application has been rejected" });
      }

      // No valid B2B account found
      return res.status(401).json({ error: "No active B2B account found for this email" });
    } catch (error) {
      console.error("B2B login error:", error);
      res.status(400).json({ error: "Invalid request" });
    }
  });

