  // Password Reset Routes - OTP Based
  app.post("/api/auth/forgot-password", async (req, res) => {
    try {
      const { email } = forgotPasswordSchema.parse(req.body);
      
      // Find user by email
      const user = await storage.getUserByEmail(email);
      
      // Always return success to prevent email enumeration
      // but only send OTP if user exists
      if (user) {
        // Generate 6-digit OTP
        const otp = Math.floor(100000 + Math.random() * 900000).toString();
        
        // OTP expires in 10 minutes
        const expiresAt = new Date(Date.now() + 10 * 60 * 1000);
        
        // Store OTP in database
        await storage.createPasswordResetOTP({
          email: user.email,
          otp,
          isVerified: false,
          expiresAt
        });
        
        // Send OTP email via Gmail
        try {
          const transporter = nodemailer.createTransport({
            service: 'gmail',
            auth: {
              user: process.env.GMAIL_USER || 'noreply@1strep.com',
              pass: process.env.GMAIL_APP_PASSWORD || process.env.GMAIL_PASSWORD
            }
          });
          
          await transporter.sendMail({
            from: process.env.GMAIL_USER || 'noreply@1strep.com',
            to: user.email,
            subject: "Your Password Reset OTP Code",
            html: `
              <div style="font-family: Arial, sans-serif; background-color: #000; color: #fff; padding: 20px;">
                <div style="max-width: 600px; margin: 0 auto;">
                  <h1>Password Reset Request</h1>
                  <p>Your OTP code is:</p>
                  <div style="background-color: #fff; color: #000; padding: 20px; text-align: center; font-size: 32px; letter-spacing: 5px; border-radius: 8px; margin: 20px 0; font-weight: bold;">
                    ${otp}
                  </div>
                  <p>This code will expire in 10 minutes.</p>
                  <p>If you didn't request a password reset, please ignore this email.</p>
                </div>
              </div>
            `
          });
          console.log(`OTP email sent to ${user.email} via Gmail`);
        } catch (emailError) {
          console.error('Failed to send OTP email:', emailError);
          // Still return success but log the error
        }

        smsPasswordReset((user as any).phoneNumber || null, otp);
      }
      
      // Always return success message
      res.json({ 
        message: "If an account exists with that email, we've sent an OTP code." 
      });
    } catch (error) {
      console.error("Forgot password error:", error);
      res.status(400).json({ error: "Invalid request" });
    }
  });

