  // Reset password with OTP endpoint
  app.post("/api/auth/reset-password-with-otp", async (req, res) => {
    try {
      const { email, otp, password } = resetPasswordWithOTPSchema.parse(req.body);
      
      // Verify OTP exists and is verified
      const resetOTP = await storage.getPasswordResetOTP(email, otp);
      
      if (!resetOTP || !resetOTP.isVerified) {
        return res.status(400).json({ error: "OTP verification required" });
      }
      
      if (new Date() > new Date(resetOTP.expiresAt)) {
        await storage.deletePasswordResetOTP(email, otp);
        return res.status(400).json({ error: "OTP has expired" });
      }
      
      // Find user by email
      const user = await storage.getUserByEmail(email);
      
      if (!user) {
        return res.status(400).json({ error: "User not found" });
      }
      
      // Hash new password
      const hashedPassword = await bcrypt.hash(password, 12);
      
      // Update user's password
      await storage.updateUserPassword(user.id, hashedPassword);
      
      // Delete the used OTP
      await storage.deletePasswordResetOTP(email, otp);
      
      // Clean up any other expired OTPs
      await storage.deleteExpiredPasswordResetOTPs();
      
      res.json({ message: "Password has been reset successfully" });
    } catch (error) {
      console.error("Reset password error:", error);
      res.status(400).json({ error: "Invalid request" });
    }
  });

  app.post("/api/auth/reset-password", async (req, res) => {
    try {
      const { token, password } = resetPasswordSchema.parse(req.body);
      
      // Hash the token to match what's stored in database
      const hashedToken = crypto.createHash('sha256').update(token).digest('hex');
      
      // Find token in database
      const resetToken = await storage.getPasswordResetToken(hashedToken);
      
      if (!resetToken) {
        return res.status(400).json({ error: "Invalid or expired reset token" });
      }
      
      // Check if token has expired
      if (new Date() > new Date(resetToken.expiresAt)) {
        await storage.deletePasswordResetToken(hashedToken);
        return res.status(400).json({ error: "Reset token has expired" });
      }
      
      // Hash new password
      const hashedPassword = await bcrypt.hash(password, 12);
      
      // Update user's password
      await storage.updateUserPassword(resetToken.userId, hashedPassword);
      
      // Delete the used token
      await storage.deletePasswordResetToken(hashedToken);
      
      // Clean up any other expired tokens
      await storage.deleteExpiredPasswordResetTokens();
      
      res.json({ message: "Password has been reset successfully" });
    } catch (error) {
      console.error("Reset password error:", error);
      res.status(400).json({ error: "Invalid request" });
    }
  });

