  app.post("/api/admin/reseller-licences/:id/approve-trial", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const trialDays = typeof req.body?.trialDays === 'number' && req.body.trialDays > 0
        ? Math.min(Math.round(req.body.trialDays), 365)
        : 30;
      
      const licence = await storage.approveResellerTrialRequest(id, req.user!.id, trialDays);
      
      if (!licence) {
        return res.status(404).json({ error: "Trial request not found" });
      }
      
      // Get reseller for logging and vendor creation
      const reseller = await storage.getReseller(licence.resellerId);
      console.log(`✅ Trial approved for reseller ${reseller?.businessName || licence.resellerId} - ${trialDays} days free trial started`);
      
      // Create vendor profile for the reseller if they don't have one
      // This is needed so they can add their own products via /api/vendor/products
      if (reseller) {
        const user = await storage.getUser(reseller.userId);
        if (user) {
          const existingVendor = await storage.getVendorByUserId(user.id);
          if (!existingVendor) {
            console.log(`📋 Creating vendor profile for trial reseller ${reseller.businessName}`);
            await storage.createVendor({
              userId: user.id,
              businessName: reseller.businessName,
              contactName: reseller.contactName,
              email: reseller.email || user.email || '',
              phone: reseller.phone || '',
              businessAddress: reseller.businessAddress || '',
              businessType: 'sole_trader',
              description: `Trial wholesaler profile for reseller ${reseller.businessName}`,
              website: '',
              socialLinks: {},
              logo: '',
              status: 'approved', // Auto-approve since trial was approved
              canAddOwnProducts: true, // Enable adding own products
            });
            console.log(`✅ Wholesaler profile created for ${reseller.businessName}`);
          } else {
            // Ensure existing vendor can add own products
            await storage.updateVendor(existingVendor.id, { canAddOwnProducts: true });
            console.log(`✅ Enabled canAddOwnProducts for existing wholesaler ${reseller.businessName}`);
          }
        }
      }
      
      // Emit WebSocket event to notify reseller in real-time
      emitResellerLicenceEvent({
        type: 'trial_approved',
        resellerId: licence.resellerId,
        status: licence.status,
        trialEndsAt: licence.trialEndsAt?.toISOString(),
        timestamp: new Date().toISOString()
      });
      
      res.json({ 
        message: `Trial approved successfully! Reseller now has ${trialDays} days to add their own products.`,
        licence 
      });
    } catch (error) {
      console.error("Trial approval error:", error);
      res.status(500).json({ error: "Failed to approve trial" });
    }
  });

  // Admin: Update trial days for an active licence
  app.patch("/api/admin/reseller-licences/:id/update-trial", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const rawDays = req.body?.trialDays;
      const trialDays = typeof rawDays === 'number' ? Math.round(rawDays) : parseInt(rawDays);
      if (!trialDays || isNaN(trialDays) || trialDays < 1 || trialDays > 365) {
        return res.status(400).json({ error: "trialDays must be between 1 and 365" });
      }
      const [licence] = await db.select().from(resellerLicences).where(eq(resellerLicences.id, id));
      if (!licence) return res.status(404).json({ error: "Licence not found" });
      const startDate = licence.trialStartedAt || new Date();
      const newEndDate = new Date(startDate);
      newEndDate.setDate(newEndDate.getDate() + trialDays);
      const updateResult = await db.update(resellerLicences)
        .set({ trialEndsAt: newEndDate, updatedAt: new Date() })
        .where(eq(resellerLicences.id, id))
        .returning();
      const updated = updateResult[0];
      if (!updated) {
        return res.status(404).json({ error: "Licence not found or could not be updated" });
      }
      const reseller = await storage.getReseller(updated.resellerId);
      console.log(`✅ Trial updated for ${reseller?.businessName || updated.resellerId}: now ${trialDays} days (ends ${newEndDate.toISOString()})`);
      res.json({ message: `Trial updated to ${trialDays} days`, licence: updated });
    } catch (error) {
      console.error("Update trial error:", error);
      res.status(500).json({ error: "Failed to update trial days" });
    }
  });

