  // Place order
  app.post("/api/reseller/orders", requireAuth, requireReseller, async (req, res) => {
    try {
      const resellerId = req.reseller!.id;

      const reseller = await storage.getReseller(resellerId);
      if (!reseller || reseller.approvalStatus !== "approved") {
        return res.status(403).json({ error: "Reseller not approved" });
      }

      const { items, shippingAddress, paymentMethod } = req.body;

      if (!items || items.length === 0) {
        return res.status(400).json({ error: "No items in order" });
      }

      // Validate payment method against reseller's allowed methods
      const allowedMethods = reseller.allowedPaymentMethods || "both";
      const requestedMethod = paymentMethod || "credit";
      
      if (allowedMethods === "credit" && requestedMethod !== "credit") {
        return res.status(403).json({ error: "You are only allowed to use credit payment" });
      }
      
      if (allowedMethods === "pay_now" && requestedMethod !== "pay_now") {
        return res.status(403).json({ error: "You are only allowed to pay upfront" });
      }
      
      if (!["credit", "pay_now"].includes(requestedMethod)) {
        return res.status(400).json({ error: "Invalid payment method" });
      }

      // Recalculate order total entirely from database prices (ignore client prices)
      let orderTotal = 0;
      const serverCalculatedItems = [];
      
      for (const item of items) {
        // Validate quantity is positive integer
        const quantity = parseInt(item.quantity);
        if (!Number.isInteger(quantity) || quantity < 1) {
          return res.status(400).json({ error: "Invalid quantity - must be a positive integer" });
        }

        const product = await storage.getProduct(item.productId);
        if (!product) {
          return res.status(400).json({ error: `Product ${item.productId} not found` });
        }

        // Get variant for wholesale price priority - MUST exist for order to proceed
        const variant = await storage.getProductVariantByDetails(item.productId, item.size, item.color);
        if (!variant) {
          return res.status(400).json({ 
            error: `Product variant not found: ${product.name} (${item.size}, ${item.color})` 
          });
        }

        // Calculate wholesale price using priority: variant wholesaleSalePrice → product wholesaleSalePrice → variant wholesalePrice → product wholesalePrice
        // Note: Sale prices are FINAL prices - no additional discount is applied when using a sale price
        let wholesaleFinalPrice: number;
        let isSalePrice = false;
        
        // Priority 1: Variant wholesale sale price (if set) - FINAL, no additional discount
        const variantWSalePrice = variant.wholesaleSalePrice ? parseFloat(variant.wholesaleSalePrice) : NaN;
        if (!isNaN(variantWSalePrice) && variantWSalePrice > 0) {
          wholesaleFinalPrice = variantWSalePrice;
          isSalePrice = true;
        }
        // Priority 2: Product-level wholesale sale price (if set) - FINAL, no additional discount
        else {
          const productWSalePrice = product.wholesaleSalePrice ? parseFloat(product.wholesaleSalePrice) : NaN;
          if (!isNaN(productWSalePrice) && productWSalePrice > 0) {
            wholesaleFinalPrice = productWSalePrice;
            isSalePrice = true;
          }
          // Priority 3: Variant wholesale price (if set) - subject to reseller discount
          else {
            const variantWPrice = variant.wholesalePrice ? parseFloat(variant.wholesalePrice) : NaN;
            if (!isNaN(variantWPrice) && variantWPrice > 0) {
              wholesaleFinalPrice = variantWPrice;
            }
            // Fallback: Product wholesale price - subject to reseller discount
            else {
              wholesaleFinalPrice = parseFloat(product.wholesalePrice);
            }
          }
        }
        
        // Validate the price parsed correctly
        if (isNaN(wholesaleFinalPrice) || wholesaleFinalPrice <= 0) {
          return res.status(400).json({ 
            error: `Invalid wholesale price for product: ${product.name}` 
          });
        }

        // Apply reseller-specific discount ONLY if not using a sale price
        // Sale prices are already discounted and should not be reduced further
        const discountPercentage = parseFloat(reseller.discountPercentage.toString());
        const unitPrice = isSalePrice 
          ? wholesaleFinalPrice 
          : wholesaleFinalPrice * (1 - discountPercentage / 100);
        const totalPrice = unitPrice * quantity;

        // Store server-calculated values
        serverCalculatedItems.push({
          productId: item.productId,
          size: item.size,
          color: item.color,
          quantity,
          unitPrice,
          totalPrice
        });

        orderTotal += totalPrice;
      }

      // Check credit limit only if using credit payment
      if (requestedMethod === "credit") {
        const creditAvailable = parseFloat(reseller.creditLimit) - parseFloat(reseller.currentCredit);
        
        if (orderTotal > creditAvailable) {
          return res.status(400).json({ 
            error: `Insufficient credit limit. Order total: £${orderTotal.toFixed(2)}, Available: £${creditAvailable.toFixed(2)}` 
          });
        }
      }

      // Create order with server-calculated total
      const orderNumber = `ORD-${Date.now()}-${Math.random().toString(36).substring(7).toUpperCase()}`;
      const order = await storage.createOrder({
        resellerId,
        orderNumber,
        totalAmount: orderTotal.toFixed(2),
        discountAmount: "0.00",
        finalAmount: orderTotal.toFixed(2),
        paymentMethod: requestedMethod,
        shippingAddress: shippingAddress || reseller.businessAddress
      });

      // Create order items using server-calculated prices
      for (const calcItem of serverCalculatedItems) {
        await storage.createOrderItem({
          orderId: order.id,
          productId: calcItem.productId,
          size: calcItem.size,
          color: calcItem.color,
          quantity: calcItem.quantity,
          unitPrice: calcItem.unitPrice.toFixed(2),
          totalPrice: calcItem.totalPrice.toFixed(2)
        });
      }

      // Update reseller credit only if using credit payment
      if (requestedMethod === "credit") {
        const newCredit = parseFloat(reseller.currentCredit) + orderTotal;
        await storage.updateReseller(resellerId, {
          currentCredit: newCredit.toFixed(2),
          lastOrderDate: new Date()
        });
        
        const creditAvailable = parseFloat(reseller.creditLimit) - parseFloat(reseller.currentCredit);
        res.status(201).json({ 
          message: "Order placed successfully",
          order: { id: order.id, orderNumber: order.orderNumber },
          paymentMethod: "credit",
          creditUsed: orderTotal.toFixed(2),
          creditRemaining: (creditAvailable - orderTotal).toFixed(2)
        });
      } else {
        // For pay_now, create Stripe checkout session
        
        // Check if Stripe is available
        if (!stripe) {
          console.error("Stripe payment requested but Stripe is not configured");
          // Roll back the order
          await storage.deleteOrder(order.id);
          return res.status(503).json({ 
            error: "Payment processing is temporarily unavailable. Please contact support or use credit payment."
          });
        }
        
        await storage.updateReseller(resellerId, {
          lastOrderDate: new Date()
        });
        
        // Create Stripe checkout session using server-calculated prices
        try {
          const lineItems = [];
          
          for (const calcItem of serverCalculatedItems) {
            // Get product name for Stripe display
            const product = await storage.getProduct(calcItem.productId);
            if (!product) {
              // Roll back the order if product not found
              await storage.deleteOrder(order.id);
              return res.status(400).json({ error: `Product ${calcItem.productId} not found` });
            }
            
            lineItems.push({
              price_data: {
                currency: 'gbp',
                product_data: {
                  name: product.name,
                  description: `${calcItem.size} | ${calcItem.color}`,
                },
                unit_amount: Math.round(calcItem.unitPrice * 100), // Convert to pence
              },
              quantity: calcItem.quantity,
            });
          }
          
          // Use production URL for Stripe redirects
          const baseUrl = getProductionBaseUrl();
          
          const session = await stripe.checkout.sessions.create({
            payment_method_types: ['card'],
        statement_descriptor_suffix: '1STREP FIT',
        payment_method_options: { card: { request_three_d_secure: 'automatic' } },
            line_items: lineItems,
            mode: 'payment',
            success_url: `${baseUrl}/reseller-dashboard?payment=success&order=${order.orderNumber}`,
            cancel_url: `${baseUrl}/reseller-dashboard?payment=cancelled`,
            metadata: {
              orderId: order.id,
              orderNumber: order.orderNumber,
              resellerId: resellerId,
              orderType: 'b2b'
            }
          });

          console.log('Stripe session created:', {
            sessionId: session.id,
            checkoutUrl: session.url,
            orderNumber: order.orderNumber
          });

          res.status(201).json({ 
            message: "Order placed successfully - Proceed to payment",
            order: { id: order.id, orderNumber: order.orderNumber },
            paymentMethod: "pay_now",
            totalAmount: orderTotal.toFixed(2),
            checkoutUrl: session.url
          });
        } catch (stripeError: any) {
          console.error("Stripe checkout session creation failed:", stripeError);
          
          // Roll back the order since payment session creation failed
          try {
            await storage.deleteOrder(order.id);
          } catch (deleteError) {
            console.error("Failed to roll back order after Stripe error:", deleteError);
          }
          
          // Return user-friendly error without exposing internal details
          res.status(500).json({ 
            error: "Failed to create payment session. Your order has been cancelled. Please try again or contact support."
          });
        }
      }
    } catch (error) {
      console.error("Place order error:", error);
      res.status(500).json({ error: "Failed to place order" });
    }
  });

