  // Category sales data for sorting categories by sales performance
  // Uses productType derived from product name to match frontend grouping logic
  app.get("/api/category-sales", async (req, res) => {
    try {
      // Compute productType from product name using same logic as frontend
      const productTypeCase = sql<string>`
        CASE 
          WHEN LOWER(${products.name}) LIKE '%hoodie%' THEN 'Hoodies'
          WHEN LOWER(${products.name}) LIKE '%t-shirt%' OR LOWER(${products.name}) LIKE '%tshirt%' THEN 'T-Shirts'
          WHEN LOWER(${products.name}) LIKE '%sports bra%' OR LOWER(${products.name}) LIKE '%bra%' THEN 'Sports Bras'
          WHEN LOWER(${products.name}) LIKE '%legging%' THEN 'Leggings'
          WHEN LOWER(${products.name}) LIKE '%tank%' THEN 'Tanks'
          WHEN LOWER(${products.name}) LIKE '%hat%' OR LOWER(${products.name}) LIKE '%jacket%' THEN 'Accessories'
          ELSE 'General'
        END
      `;

      const salesByProductType = await db
        .select({
          category: productTypeCase,
          totalSales: sql<number>`COALESCE(SUM(${customerOrderItems.quantity}), 0)::int`,
        })
        .from(customerOrderItems)
        .innerJoin(products, eq(customerOrderItems.productId, products.id))
        .groupBy(productTypeCase)
        .orderBy(sql`SUM(${customerOrderItems.quantity}) DESC`);

      res.json(salesByProductType);
    } catch (error) {
      console.error("Get category sales error:", error);
      res.status(500).json({ error: "Failed to get category sales data" });
    }
  });

