  // Get products expanded by color - each color variant appears as a separate product card (cached)
  app.get("/api/products/by-color", async (req, res) => {
    try {
      // Check cache first - this is an expensive query
      const cached = getCached<any[]>('products-by-color');
      if (cached) {
        return res.json(cached);
      }
      
      const products = await storage.getAllProducts();
      const expandedProducts: any[] = [];
      
      for (const product of products) {
        // Get color images and variants for this product
        const colorImages = await storage.getProductColorImages(product.id);
        const variants = await storage.getProductVariants(product.id);
        
        // Filter to only active variants with valid colors (treat undefined as active)
        // Pre-normalize color strings for consistent comparison
        const activeVariants = variants
          .filter(v => v.color && v.isActive !== false)
          .map(v => ({ ...v, colorNorm: v.color.toLowerCase().trim() }));
        
        // Build a union of all colors from active variants (authoritative source)
        // This ensures all active variant colors appear, regardless of product.colors array state
        const colorMap = new Map<string, string>();
        for (const variant of activeVariants) {
          if (!colorMap.has(variant.colorNorm)) {
            colorMap.set(variant.colorNorm, variant.color);
          }
        }
        const uniqueColors = Array.from(colorMap.values());
        
        // Get all product images to find primary image (non-color-specific only)
        const allImages = await storage.getProductImages(product.id);
        // For hero section, use a non-color-specific primary image if available
        const globalPrimaryImage = allImages.find(img => img.isPrimary && !img.color);
        
        // The main/primary image for hero sections: 
        // 1. Use product's main imageUrl (set directly on product)
        // 2. Fall back to global primary image from product_images (non-color-specific)
        const heroImageUrl = product.imageUrl || globalPrimaryImage?.url;
        
        if (uniqueColors.length === 0) {
          // No color variants - show as single product with primary image
          expandedProducts.push({
            ...product,
            imageUrl: heroImageUrl,
            heroImageUrl: heroImageUrl,
            // Hero hover image uses the product's main hover image for the hero section
            heroHoverImageUrl: product.hoverImageUrl,
            displayColor: null,
            colorVariantId: null
            // hoverImageUrl is preserved from product spread
          });
        } else {
          // Create a product card for each color
          for (const color of uniqueColors) {
            // Get the variant with the lowest price for this color (using pre-normalized colors)
            const colorLowerNorm = color.toLowerCase().trim();
            const colorVariants = activeVariants.filter(v => v.colorNorm === colorLowerNorm);
            
            // Skip colors that have no active variants
            if (colorVariants.length === 0) {
              continue;
            }
            
            // Find the color image for this color
            const colorImage = colorImages.find(img => 
              img.color?.toLowerCase() === color?.toLowerCase()
            );
            
            const lowestPriceVariant = colorVariants.reduce((min, v) => 
              parseFloat(v.retailPrice) < parseFloat(min.retailPrice) ? v : min
            , colorVariants[0]);
            
            expandedProducts.push({
              ...product,
              // Use color-specific image only - don't fall back to product image
              // This allows frontend to show "No image" for colors without specific images
              imageUrl: colorImage?.url || null,
              // Use color-specific hover image only - don't fall back
              hoverImageUrl: colorImage?.hoverUrl || null,
              // Main/primary image for hero sections
              heroImageUrl: heroImageUrl,
              // Hero hover image uses the product's main hover image for the hero section
              heroHoverImageUrl: product.hoverImageUrl,
              // Track which color this card represents
              displayColor: color,
              colorVariantId: lowestPriceVariant?.id,
              // Use variant-specific price if available
              retailPrice: lowestPriceVariant?.retailPrice || product.retailPrice,
              // Include the color in the display name (convert hex to readable name)
              displayName: `${product.name} - ${hexToColorName(color)}`
            });
          }
        }
      }
      
      // Cache the result
      setCache('products-by-color', expandedProducts);
      res.json(expandedProducts);
    } catch (error) {
      console.error("Products by color error:", error);
      res.status(500).json({ error: "Failed to load products by color" });
    }
  });

  app.get("/api/products/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const products = await storage.getAllProducts();
      let product = products.find(p => p.id === id);
      let isVendorProduct = false;
      
      // If not found in regular products, check vendor products (reseller's own products)
      if (!product) {
        const vendorProduct = await storage.getVendorProduct(id);
        if (vendorProduct) {
          // Convert vendor product to product format for display
          product = {
            ...vendorProduct,
            isVendorProduct: true
          } as any;
          isVendorProduct = true;
        }
      }
      
      if (!product) {
        return res.status(404).json({ error: "Product not found" });
      }
      
      // Get color-specific images for this product
      const colorImages = await storage.getProductColorImages(id);
      const colorImagesMap: Record<string, string> = {};
      const colorHoverImagesMap: Record<string, string> = {};
      const colorAdditionalImagesMap: Record<string, string[]> = {};
      
      // Sort by sortOrder for proper primary/additional distinction
      const sortedColorImages = [...colorImages].sort((a, b) => a.sortOrder - b.sortOrder);
      
      sortedColorImages.forEach(img => {
        if (img.color) {
          if (img.isPrimary || img.sortOrder === 0) {
            // Primary color image
            colorImagesMap[img.color] = img.url;
            if (img.hoverUrl) {
              colorHoverImagesMap[img.color] = img.hoverUrl;
            }
          } else {
            // Additional gallery image for this color
            if (!colorAdditionalImagesMap[img.color]) {
              colorAdditionalImagesMap[img.color] = [];
            }
            colorAdditionalImagesMap[img.color].push(img.url);
          }
        }
      });
      
      // Get additional product images from product_images table (non-color specific)
      const productImages = await storage.getProductImages(id);
      const additionalImages = productImages
        .filter(img => !img.isPrimary && !img.color)
        .sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0))
        .map(img => img.url);
      
      res.json({
        ...product,
        colorImages: colorImagesMap,
        colorHoverImages: colorHoverImagesMap,
        colorAdditionalImages: colorAdditionalImagesMap,
        additionalImages: additionalImages
      });
    } catch (error) {
      console.error("Product detail error:", error);
      res.status(500).json({ error: "Failed to load product" });
    }
  });

