  // Cart Routes
  app.get("/api/cart", optionalAuth, async (req, res) => {
    try {
      const userId = req.user?.id || null;
      const sessionId = req.sessionID || null;
      
      console.log('🛒 GET /api/cart - userId:', userId, 'sessionId:', sessionId);

      // Get or create cart
      let cart = await storage.getCart(userId, sessionId);
      console.log('🛒 Found cart:', cart ? cart.id : 'none - will create');
      
      if (!cart) {
        try {
          cart = await storage.createCart({
            userId,
            sessionId,
          });
          console.log('🛒 Created new cart:', cart.id);
        } catch (createError: any) {
          // Handle race condition: cart may have been created by another request
          if (createError?.code === '23505') {
            console.log('🛒 Cart creation race condition - fetching existing cart');
            cart = await storage.getCart(userId, sessionId);
            if (!cart) {
              throw new Error("Failed to get or create cart");
            }
          } else {
            throw createError;
          }
        }
      }

      // Get cart items and enrich with current product images if missing
      const rawItems = await storage.getCartItems(cart.id);
      
      // Sanitize cart items - filter out any that are missing required productId
      // and delete invalid items from the database
      const validRawItems = [];
      for (const item of rawItems) {
        if (!item.productId) {
          console.log(`🛒 Removing invalid cart item without productId: ${item.id}`);
          try {
            await storage.removeCartItem(item.id);
          } catch (e) {
            console.error('Failed to remove invalid cart item:', e);
          }
        } else {
          validRawItems.push(item);
        }
      }
      
      // Enrich items with product images if image is missing or empty
      const items = await Promise.all(validRawItems.map(async (item) => {
        // If item already has a valid image, use it
        if (item.image && item.image.trim() !== '') {
          return item;
        }
        
        // Try to get the image from the product
        try {
          const product = await storage.getProduct(item.productId);
          if (product) {
            // Try color-specific image first
            const colorImages = await storage.getProductColorImages(item.productId);
            const colorImage = colorImages.find(img => 
              img.color?.toLowerCase() === item.color?.toLowerCase()
            );
            
            return {
              ...item,
              image: colorImage?.url || product.imageUrl || ''
            };
          }
        } catch (err) {
          console.log('Could not enrich cart item image');
        }
        
        return item;
      }));

      res.json({ cart, items });
    } catch (error) {
      console.error("Get cart error:", error);
      res.status(500).json({ error: "Failed to load cart" });
    }
  });

  app.post("/api/cart/items", optionalAuth, async (req, res) => {
    try {
      const userId = req.user?.id || null;
      const sessionId = req.sessionID || null;
      
      console.log('🛒 POST /api/cart/items - userId:', userId, 'sessionId:', sessionId);

      // Get or create cart
      let cart = await storage.getCart(userId, sessionId);
      console.log('🛒 Found cart:', cart ? cart.id : 'none - will create');
      
      if (!cart) {
        try {
          cart = await storage.createCart({
            userId,
            sessionId,
          });
          console.log('🛒 Created new cart:', cart.id);
        } catch (createError: any) {
          // Handle race condition: cart may have been created by another request
          if (createError?.code === '23505') {
            console.log('🛒 Cart creation race condition - fetching existing cart');
            cart = await storage.getCart(userId, sessionId);
            if (!cart) {
              throw new Error("Failed to get or create cart");
            }
          } else {
            throw createError;
          }
        }
      }

      const { productId, size, color, quantity, storefrontSlug, resellerId } = req.body;
      console.log('🛒 Adding item:', { productId, size, color, quantity, storefrontSlug, resellerId });

      // Validate required fields
      if (!productId || !size || !color) {
        return res.status(400).json({ error: "Missing required fields" });
      }

      // Validate quantity is a positive integer
      const validatedQuantity = parseInt(quantity || 1);
      if (!Number.isInteger(validatedQuantity) || validatedQuantity < 1) {
        return res.status(400).json({ error: "Quantity must be a positive integer" });
      }

      // Fetch product details from database (authoritative source)
      const product = await storage.getProduct(productId);
      if (!product) {
        return res.status(404).json({ error: "Product not found" });
      }

      // Verify variant exists
      const variant = await storage.getProductVariantByDetails(productId, size, color);
      if (!variant) {
        return res.status(400).json({ 
          error: `Product variant not available: ${product.name} (${size}, ${color})` 
        });
      }

      // Check stock availability
      if (variant.stockQuantity < validatedQuantity) {
        return res.status(400).json({ 
          error: `Insufficient stock. Available: ${variant.stockQuantity}`,
          availableQuantity: variant.stockQuantity
        });
      }

      // Get color-specific image if available
      let itemImage = product.imageUrl || '';
      try {
        const colorImages = await storage.getProductColorImages(productId);
        const colorImage = colorImages.find(img => 
          img.color?.toLowerCase() === color?.toLowerCase()
        );
        if (colorImage?.url) {
          itemImage = colorImage.url;
        }
      } catch (err) {
        console.log('No color image found, using default product image');
      }

      // Calculate effective price using priority: variant salePrice → product salePrice → variant retailPrice → product retailPrice
      // Use validated numeric parsing to ensure prices are valid
      let effectivePrice = product.retailPrice;
      
      // Priority 1: Variant sale price (if set)
      const variantSalePrice = variant.salePrice ? parseFloat(variant.salePrice) : NaN;
      if (!isNaN(variantSalePrice) && variantSalePrice > 0) {
        effectivePrice = variant.salePrice;
      }
      // Priority 2: Product-level sale price (if set and no variant sale price)
      else {
        const productSalePrice = product.salePrice ? parseFloat(product.salePrice) : NaN;
        if (!isNaN(productSalePrice) && productSalePrice > 0) {
          effectivePrice = product.salePrice;
        }
        // Priority 3: Variant retail price (if set)
        else {
          const variantRetailPrice = variant.retailPrice ? parseFloat(variant.retailPrice) : NaN;
          if (!isNaN(variantRetailPrice) && variantRetailPrice > 0) {
            effectivePrice = variant.retailPrice;
          }
          // Fallback: Product retail price (already set)
        }
      }
      
      // Validate the final price is valid
      const finalPriceValue = parseFloat(effectivePrice);
      if (isNaN(finalPriceValue) || finalPriceValue <= 0) {
        return res.status(400).json({ error: "Invalid product price" });
      }

      // Use server-side data for cart item
      const itemData = {
        cartId: cart.id,
        productId,
        name: product.name,
        price: effectivePrice,
        size,
        color,
        quantity: validatedQuantity,
        image: itemImage,
        category: product.category || '',
        storefrontSlug: storefrontSlug || null,
        resellerId: resellerId || null,
      };

      // Check if item already exists in cart
      const existingItems = await storage.getCartItems(cart.id);
      const existingItem = existingItems.find(
        item => item.productId === productId && item.size === size && item.color === color
      );

      if (existingItem && existingItem.storefrontSlug === (storefrontSlug || null)) {
        // Verify we have enough stock for the new total
        const newQuantity = existingItem.quantity + validatedQuantity;
        if (variant.stockQuantity < newQuantity) {
          return res.status(400).json({ 
            error: `Insufficient stock. Available: ${variant.stockQuantity}, requested: ${newQuantity}`,
            availableQuantity: variant.stockQuantity
          });
        }
        
        // Update quantity
        const updated = await storage.updateCartItem(existingItem.id, newQuantity);
        res.json(updated);
      } else {
        // Add new item
        const item = await storage.addCartItem(itemData);
        res.status(201).json(item);
      }
    } catch (error) {
      console.error("Add to cart error:", error);
      res.status(500).json({ error: "Failed to add to cart" });
    }
  });

