  // Code128 barcode pattern generator - creates scannable barcodes
  const generateCode128Barcode = (data: string): { svg: string; width: number } => {
    // Code128 encoding tables
    const CODE128_START_B = 104;
    const CODE128_STOP = 106;
    
    // Code128B character set patterns (each pattern is 11 modules wide)
    const CODE128_PATTERNS: { [key: number]: string } = {
      0: "11011001100", 1: "11001101100", 2: "11001100110", 3: "10010011000",
      4: "10010001100", 5: "10001001100", 6: "10011001000", 7: "10011000100",
      8: "10001100100", 9: "11001001000", 10: "11001000100", 11: "11000100100",
      12: "10110011100", 13: "10011011100", 14: "10011001110", 15: "10111001100",
      16: "10011101100", 17: "10011100110", 18: "11001110010", 19: "11001011100",
      20: "11001001110", 21: "11011100100", 22: "11001110100", 23: "11101101110",
      24: "11101001100", 25: "11100101100", 26: "11100100110", 27: "11101100100",
      28: "11100110100", 29: "11100110010", 30: "11011011000", 31: "11011000110",
      32: "11000110110", 33: "10100011000", 34: "10001011000", 35: "10001000110",
      36: "10110001000", 37: "10001101000", 38: "10001100010", 39: "11010001000",
      40: "11000101000", 41: "11000100010", 42: "10110111000", 43: "10110001110",
      44: "10001101110", 45: "10111011000", 46: "10111000110", 47: "10001110110",
      48: "11101110110", 49: "11010001110", 50: "11000101110", 51: "11011101000",
      52: "11011100010", 53: "11011101110", 54: "11101011000", 55: "11101000110",
      56: "11100010110", 57: "11101101000", 58: "11101100010", 59: "11100011010",
      60: "11101111010", 61: "11001000010", 62: "11110001010", 63: "10100110000",
      64: "10100001100", 65: "10010110000", 66: "10010000110", 67: "10000101100",
      68: "10000100110", 69: "10110010000", 70: "10110000100", 71: "10011010000",
      72: "10011000010", 73: "10000110100", 74: "10000110010", 75: "11000010010",
      76: "11001010000", 77: "11110111010", 78: "11000010100", 79: "10001111010",
      80: "10100111100", 81: "10010111100", 82: "10010011110", 83: "10111100100",
      84: "10011110100", 85: "10011110010", 86: "11110100100", 87: "11110010100",
      88: "11110010010", 89: "11011011110", 90: "11011110110", 91: "11110110110",
      92: "10101111000", 93: "10100011110", 94: "10001011110", 95: "10111101000",
      96: "10111100010", 97: "11110101000", 98: "11110100010", 99: "10111011110",
      100: "10111101110", 101: "11101011110", 102: "11110101110",
      103: "11010000100", // START A
      104: "11010010000", // START B
      105: "11010011100", // START C
      106: "1100011101011", // STOP (13 modules)
    };
    
    // Convert character to Code128B value
    const charToCode128B = (char: string): number => {
      const code = char.charCodeAt(0);
      if (code >= 32 && code <= 126) {
        return code - 32;
      }
      return 0; // Default to space for unsupported characters
    };
    
    // Build the barcode pattern
    let pattern = CODE128_PATTERNS[CODE128_START_B]; // Start with Code B
    let checksum = CODE128_START_B;
    
    // Encode each character
    for (let i = 0; i < data.length; i++) {
      const value = charToCode128B(data[i]);
      pattern += CODE128_PATTERNS[value];
      checksum += value * (i + 1);
    }
    
    // Add checksum
    const checksumValue = checksum % 103;
    pattern += CODE128_PATTERNS[checksumValue];
    
    // Add stop pattern
    pattern += CODE128_PATTERNS[CODE128_STOP];
    
    // Convert pattern to SVG rectangles with quiet zones
    let svg = '';
    const quietZone = 20; // Required quiet zone for Code128
    let xPos = quietZone; // Start after quiet zone
    const barHeight = 50;
    const moduleWidth = 2;
    
    for (let i = 0; i < pattern.length; i++) {
      if (pattern[i] === '1') {
        svg += `<rect x="${xPos}" y="0" width="${moduleWidth}" height="${barHeight}" fill="black"/>`;
      }
      xPos += moduleWidth;
    }
    
    // Total width includes both quiet zones
    return { svg, width: xPos + quietZone };
  };

  // Generate professional barcode SVG for a variant
  app.get("/api/admin/products/barcodes/:variantId", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { variantId } = req.params;
      
      const variant = await storage.getProductVariant(variantId);
      if (!variant) {
        return res.status(404).json({ error: "Product variant not found" });
      }

      // Get the parent product to check for barcode descriptor
      const product = await storage.getProduct(variant.productId);
      
      // Priority: 1. Variant barcode descriptor, 2. Product barcode descriptor, 3. Variant SKU, 4. Variant ID
      const barcodeData = variant.barcodeDescriptor || product?.barcodeDescriptor || variant.sku || variantId;
      
      // Generate Code128 barcode pattern (scannable)
      const { svg: barcodePattern, width: barcodeWidth } = generateCode128Barcode(barcodeData);
      
      // Calculate centering offset for the barcode
      const svgWidth = 500;
      const barcodeScale = Math.min(1.5, (svgWidth - 60) / barcodeWidth);
      const scaledWidth = barcodeWidth * barcodeScale;
      const xOffset = (svgWidth - scaledWidth) / 2;
      
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="500" height="280" viewBox="0 0 500 280">
        <!-- Background -->
        <rect width="500" height="280" fill="white"/>
        
        <!-- Title -->
        <text x="250" y="25" font-size="16" font-weight="bold" text-anchor="middle" fill="black" font-family="Arial, sans-serif">Product Barcode Label</text>
        
        <!-- Divider -->
        <line x1="20" y1="35" x2="480" y2="35" stroke="black" stroke-width="0.5"/>
        
        <!-- Code128 Barcode (scannable) -->
        <g transform="translate(${xOffset}, 60) scale(${barcodeScale})">
          ${barcodePattern}
        </g>
        
        <!-- Human readable barcode number -->
        <text x="250" y="175" font-size="14" font-weight="bold" text-anchor="middle" fill="black" font-family="monospace, 'Courier New'">${barcodeData}</text>
        
        <!-- Barcode format label -->
        <text x="250" y="195" font-size="9" text-anchor="middle" fill="#666" font-family="Arial, sans-serif">Code128</text>
        
        <!-- Product info -->
        <text x="250" y="220" font-size="11" text-anchor="middle" fill="#333" font-family="Arial, sans-serif">${product?.name || 'Product'}</text>
        <text x="250" y="238" font-size="10" text-anchor="middle" fill="#666" font-family="Arial, sans-serif">${variant.size || ''} ${variant.color ? '/ ' + variant.color : ''}</text>
        
        <!-- Footer -->
        <text x="20" y="265" font-size="9" fill="#666" font-family="Arial, sans-serif">1stRep Premium Apparel</text>
        <text x="480" y="265" font-size="9" text-anchor="end" fill="#666" font-family="Arial, sans-serif">Scan with any barcode reader</text>
      </svg>`;

      res.setHeader('Content-Type', 'image/svg+xml');
      res.send(svg);
    } catch (error) {
      console.error("Barcode generation error:", error);
      res.status(500).json({ error: "Failed to generate barcode" });
    }
  });

