  // Stripe status endpoint - checks if Stripe can process payments
  app.get("/api/stripe/status", async (req, res) => {
    try {
      const secretKey = (process.env.STRIPE_SECRET_KEY || "").trim();
      const publishableKey = (process.env.STRIPE_PUBLISHABLE_KEY || process.env.VITE_STRIPE_PUBLISHABLE_KEY || "").trim();
      
      if (!secretKey || !publishableKey) {
        return res.json({ 
          available: false, 
          reason: "not_configured",
          message: "Stripe is not configured"
        });
      }

      const stripe = new Stripe(secretKey, { apiVersion: "2025-04-30.basil" });
      
      // Try to retrieve account to check if it's restricted
      const account = await stripe.accounts.retrieve();
      
      // Check for restrictions
      if (account.requirements?.disabled_reason) {
        return res.json({
          available: false,
          reason: "account_restricted",
          message: "Stripe account has restrictions",
          disabledReason: account.requirements.disabled_reason
        });
      }

      // Check if charges are enabled
      if (account.charges_enabled === false) {
        return res.json({
          available: false,
          reason: "charges_disabled",
          message: "Stripe charges are currently disabled"
        });
      }

      res.json({ 
        available: true,
        reason: "operational",
        message: "Stripe is operational"
      });
    } catch (error: any) {
      console.error("Stripe status check error:", error.message);
      
      // Check for specific error types
      if (error.type === 'StripeAuthenticationError') {
        return res.json({
          available: false,
          reason: "authentication_error",
          message: "Stripe authentication failed"
        });
      }
      
      if (error.code === 'account_invalid') {
        return res.json({
          available: false,
          reason: "account_invalid",
          message: "Stripe account is invalid"
        });
      }

      res.json({
        available: false,
        reason: "error",
        message: error.message || "Stripe status check failed"
      });
    }
  });



