  app.post("/api/admin/resellers/:id/approve", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const { commissionRate } = req.body;
      
      // Validate commission rate if provided
      if (commissionRate !== undefined) {
        const rate = parseFloat(commissionRate);
        if (isNaN(rate) || rate < 0 || rate > 100) {
          return res.status(400).json({ error: "Commission rate must be between 0 and 100" });
        }
      }
      
      const reseller = await storage.approveReseller(id, req.user!.id, commissionRate);
      
      if (!reseller) {
        return res.status(404).json({ error: "Reseller not found" });
      }

      // Update isActive to true when approved
      await storage.updateReseller(id, { isActive: true });

      // Note: Trial is NOT automatically created - resellers must request a trial first
      // and admin must approve the trial request before they can add their own products

      // Log the approval activity
      await storage.createActivityLog({
        resellerId: reseller.id,
        adminUserId: req.user!.id,
        actionType: "status_change",
        description: "Reseller application approved",
        oldValue: JSON.stringify({ approvalStatus: "pending" }),
        newValue: JSON.stringify({ approvalStatus: "approved", isActive: true }),
      });

      // AUTO-SYNC: Add all active 1stRep products to new reseller's storefront and EPOS
      try {
        // Get all active 1stRep products (products table contains only 1stRep products, vendor products are in vendor_products table)
        const allProducts = await storage.getAllProducts();
        const activeProducts = allProducts.filter(p => p.isActive !== false);
        
        console.log(`🔄 Auto-syncing ${activeProducts.length} 1stRep products to reseller ${reseller.id}...`);
        
        let syncedProducts = 0;
        let syncedInventory = 0;
        
        for (const product of activeProducts) {
          try {
            // Check if product already exists in reseller's storefront
            const existingProducts = await storage.getResellerProductsWithDetails(id);
            const alreadyExists = existingProducts.some(p => p.productId === product.id);
            
            if (!alreadyExists) {
              // Add product to storefront
              await storage.addProductToStorefront({
                resellerId: id,
                productId: product.id,
                isActive: true,
                displayOrder: 0
              });
              syncedProducts++;
              
              // Create inventory entries for EPOS for all variants
              const productVariants = await storage.getProductVariants(product.id);
              
              if (productVariants.length > 0) {
                // Use actual active variants from database
                const activeVariants = productVariants.filter(v => v.isActive !== false);
                for (const variant of activeVariants) {
                  const existingItem = await storage.getInventoryItem(id, product.id, variant.size || undefined, variant.color || undefined);
                  if (!existingItem) {
                    await storage.createInventoryItem({
                      resellerId: id,
                      productId: product.id,
                      size: variant.size || undefined,
                      color: variant.color || undefined,
                      quantity: 0,
                      reorderLevel: 5
                    });
                    syncedInventory++;
                  }
                }
              } else {
                // No variants - create from product sizes/colors arrays
                const sizes = product.sizes && product.sizes.length > 0 ? product.sizes : [undefined];
                const colors = product.colors && product.colors.length > 0 ? product.colors : [undefined];
                
                for (const size of sizes) {
                  for (const color of colors) {
                    const existingItem = await storage.getInventoryItem(id, product.id, size, color);
                    if (!existingItem) {
                      await storage.createInventoryItem({
                        resellerId: id,
                        productId: product.id,
                        size,
                        color,
                        quantity: 0,
                        reorderLevel: 5
                      });
                      syncedInventory++;
                    }
                  }
                }
              }
            }
          } catch (productSyncError) {
            console.error(`Failed to sync product ${product.id}:`, productSyncError);
            // Continue with other products
          }
        }
        
        console.log(`✅ Auto-synced ${syncedProducts} products and ${syncedInventory} inventory entries to reseller ${reseller.id}`);
      } catch (syncError) {
        console.error('Auto-sync warning (non-blocking):', syncError);
        // Don't fail approval if sync fails
      }

      // Get user details for email
      const resellerUser = await storage.getUser(reseller.userId);
      
      // Send approval email + SMS
      if (resellerUser) {
        try {
          await sendResellerApprovedEmail({
            name: reseller.contactPerson,
            email: resellerUser.email,
            tier: reseller.tier,
            discountPercentage: parseFloat(reseller.discountPercentage)
          });
          console.log(`Reseller approval email sent to ${resellerUser.email}`);
        } catch (emailError) {
          console.error('Failed to send reseller approval email:', emailError);
        }
        smsResellerApproved(reseller.phoneNumber, reseller.contactPerson, reseller.tier, parseFloat(reseller.discountPercentage));
      }

      res.json({ message: "Reseller approved successfully with 1stRep products auto-synced", reseller });
    } catch (error) {
      console.error("Approve reseller error:", error);
      res.status(500).json({ error: "Failed to approve reseller" });
    }
  });

