  // Admin - Get reseller orders (both wholesale and customer orders)
  app.get("/api/admin/resellers/:id/orders", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      
      const reseller = await storage.getReseller(id);
      if (!reseller) {
        return res.status(404).json({ error: "Reseller not found" });
      }

      // Get wholesale orders (orders from 1stRep)
      const wholesaleOrders = await storage.getResellerOrders(id);
      
      // Get customer orders (orders through reseller storefront - resellerCustomerOrders table)
      const storefrontCustomerOrders = await storage.getResellerCustomerOrders(id);
      
      // Get EPOS orders from main customerOrders table where resellerId matches
      const eposOrdersRaw = await db.select().from(customerOrders)
        .where(eq(customerOrders.resellerId, id))
        .orderBy(desc(customerOrders.orderDate));
      
      // Get items for EPOS orders
      const eposOrdersWithItems = await Promise.all(
        eposOrdersRaw.map(async (order) => {
          const items = await db.select().from(customerOrderItems)
            .where(eq(customerOrderItems.orderId, order.id));
          const hasVendorProducts = items.some(item => item.vendorProductId);
          const vendorProductTotal = items
            .filter(item => item.vendorProductId)
            .reduce((sum, item) => sum + parseFloat(item.totalPrice), 0);
          const catalogProductTotal = items
            .filter(item => !item.vendorProductId)
            .reduce((sum, item) => sum + parseFloat(item.totalPrice), 0);
          const resellerRate = reseller.commissionRate ? parseFloat(reseller.commissionRate) / 100 : 0.10;
          const catalogEarnings = catalogProductTotal * resellerRate;
          const totalEarnings = vendorProductTotal + catalogEarnings;
          const platformFee = catalogProductTotal - catalogEarnings;
          
          return { 
            ...order, 
            items,
            itemCount: items.length,
            customerName: `${order.customerFirstName || ''} ${order.customerLastName || ''}`.trim() || 'EPOS Customer',
            orderType: 'epos',
            channel: order.channel || 'reseller_epos',
            resellerEarnings: totalEarnings.toFixed(2),
            platformCommission: platformFee.toFixed(2),
          };
        })
      );
      
      // Get order items for each storefront order
      const wholesaleOrdersWithItems = await Promise.all(
        wholesaleOrders.map(async (order) => {
          const items = await storage.getOrderItems(order.id);
          return { ...order, items };
        })
      );

      const storefrontOrdersWithItems = await Promise.all(
        storefrontCustomerOrders.map(async (order) => {
          const items = await storage.getResellerCustomerOrderItems(order.id);
          return { ...order, items, orderType: 'storefront' };
        })
      );

      // Combine storefront and EPOS orders
      const allCustomerOrders = [...storefrontOrdersWithItems, ...eposOrdersWithItems]
        .sort((a, b) => new Date(b.orderDate).getTime() - new Date(a.orderDate).getTime());

      // Calculate order stats with channel breakdown
      const storefrontOnly = storefrontCustomerOrders;
      const eposOnly = eposOrdersRaw;
      
      const stats = {
        totalWholesaleOrders: wholesaleOrders.length,
        totalCustomerOrders: storefrontOnly.length + eposOnly.length,
        pendingWholesale: wholesaleOrders.filter(o => o.status === 'pending').length,
        pendingCustomer: [...storefrontOnly, ...eposOnly].filter(o => o.status === 'pending').length,
        completedWholesale: wholesaleOrders.filter(o => o.status === 'delivered').length,
        completedCustomer: [...storefrontOnly, ...eposOnly].filter(o => o.status === 'delivered' || o.status === 'completed').length,
        totalWholesaleValue: wholesaleOrders.reduce((sum, o) => sum + parseFloat(o.totalAmount || '0'), 0),
        totalCustomerValue: [...storefrontOnly, ...eposOnly].reduce((sum, o) => sum + parseFloat(o.totalAmount || '0'), 0),
        storefrontOrders: storefrontOnly.length,
        storefrontValue: storefrontOnly.reduce((sum, o) => sum + parseFloat(o.totalAmount || '0'), 0),
        storefrontCommission: storefrontOnly.reduce((sum, o) => sum + parseFloat((o as any).resellerEarnings || '0'), 0),
        eposOrders: eposOnly.length,
        eposValue: eposOnly.reduce((sum, o) => sum + parseFloat(o.totalAmount || '0'), 0),
        eposCommission: 0,
        totalCommission: storefrontOnly.reduce((sum, o) => sum + parseFloat((o as any).resellerEarnings || '0'), 0),
      };

      res.json({
        wholesaleOrders: wholesaleOrdersWithItems,
        customerOrders: allCustomerOrders,
        stats
      });
    } catch (error) {
      console.error("Get reseller orders error:", error);
      res.status(500).json({ error: "Failed to load reseller orders" });
    }
  });

  // Admin - Get reseller earnings and commissions with optional date filtering
  app.get("/api/admin/resellers/:id/earnings", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const { startDate, endDate } = req.query;
      
      const reseller = await storage.getReseller(id);
      if (!reseller) {
        return res.status(404).json({ error: "Reseller not found" });
      }

      // Get commission payments for this reseller
      const commissionPayments = await storage.getCommissionPaymentsByReseller(id);
      
      // Get commission rules for this reseller
      const commissionRules = await storage.getCommissionRulesForReseller(id);

      // Reseller commission rate for EPOS earnings calculation
      const commissionRateRaw = reseller.commissionRate || reseller.discountPercentage || '10';
      const catalogueCommissionRate = parseFloat(commissionRateRaw) / 100;
      
      // Get storefront orders
      let storefrontOrders = await storage.getResellerCustomerOrders(id);

      // Get EPOS orders from main customerOrders table
      const eposCancelledStatuses = ['cancelled', 'refunded', 'failed'];
      let eposOrdersRaw = await db.select().from(customerOrders).where(eq(customerOrders.resellerId, id));

      // Filter by date range if provided
      const start = startDate ? new Date(startDate as string) : null;
      const end = endDate ? new Date(endDate as string) : null;
      if (start || end) {
        storefrontOrders = storefrontOrders.filter(order => {
          const d = new Date(order.orderDate || order.createdAt);
          return (!start || d >= start) && (!end || d <= end);
        });
        eposOrdersRaw = eposOrdersRaw.filter(order => {
          const d = new Date(order.orderDate);
          return (!start || d >= start) && (!end || d <= end);
        });
      }

      // Calculate EPOS earnings per order via items — tracking catalogue vs own revenue split
      const eposOrders: Array<{
        id: string; totalAmount: string; resellerEarnings: string; orderDate: Date; customerEmail: string;
        _catRev: number; _ownRev: number; _catEarnings: number; _ownEarnings: number;
      }> = [];

      // Product-level aggregation maps: key = productName, value = { qty, revenue, earnings }
      type ProductRow = { productName: string; qty: number; revenue: number; earnings: number };
      const catProductMap = new Map<string, ProductRow>();
      const ownProductMap = new Map<string, ProductRow>();

      const addToProductMap = (map: Map<string, ProductRow>, name: string, qty: number, revenue: number, earnings: number) => {
        const existing = map.get(name);
        if (existing) {
          existing.qty += qty;
          existing.revenue += revenue;
          existing.earnings += earnings;
        } else {
          map.set(name, { productName: name, qty, revenue, earnings });
        }
      };

      // Only process genuine EPOS channel orders (prevents any accidental overlap)
      const eposChannels = new Set(['reseller_epos', 'reseller_epos_own', 'reseller_epos_own_stripe']);
      const eposOnly = eposOrdersRaw.filter(o => eposChannels.has(o.channel || ''));

      for (const order of eposOnly) {
        if (eposCancelledStatuses.includes(order.status || '')) continue;
        const items = await db.select().from(customerOrderItems).where(eq(customerOrderItems.orderId, order.id));

        let _catRev = 0, _ownRev = 0, _catEarnings = 0, _ownEarnings = 0;

        if (items.length === 0) {
          // No line-items recorded — use channel as classifier
          const orderTotal = parseFloat(order.totalAmount || '0');
          const isOwnChannel = order.channel === 'reseller_epos_own' || order.channel === 'reseller_epos_own_stripe';
          if (isOwnChannel) {
            _ownRev = orderTotal;
            // If payment went directly to reseller's own Square, 1stRep never held
            // these funds — earnings owed = 0. Revenue still shows for reporting.
            _ownEarnings = (order as any).ownSquarePaid ? 0 : orderTotal;
            addToProductMap(ownProductMap, 'Own Product (unspecified)', 1, orderTotal, _ownEarnings);
          } else {
            _catRev = orderTotal;
            _catEarnings = orderTotal * catalogueCommissionRate;
            addToProductMap(catProductMap, 'Catalogue Item (unspecified)', 1, orderTotal, orderTotal * catalogueCommissionRate);
          }
        } else {
          for (const item of items) {
            const itemRevenue = parseFloat(item.unitPrice) * item.quantity;
            if (item.vendorProductId) {
              _ownRev += itemRevenue;
              // Same BYOS check for line-item level (order-level flag applies to all items)
              const itemOwnEarnings = (order as any).ownSquarePaid ? 0 : itemRevenue;
              _ownEarnings += itemOwnEarnings;
              addToProductMap(ownProductMap, item.productName, item.quantity, itemRevenue, itemOwnEarnings);
            } else {
              const earn = itemRevenue * catalogueCommissionRate;
              _catRev += itemRevenue;
              _catEarnings += earn;
              addToProductMap(catProductMap, item.productName, item.quantity, itemRevenue, earn);
            }
          }
        }

        eposOrders.push({
          id: order.id,
          totalAmount: order.totalAmount,
          resellerEarnings: (_catEarnings + _ownEarnings).toFixed(2),
          orderDate: order.orderDate,
          customerEmail: order.customerEmail || 'epos@customer',
          _catRev, _ownRev, _catEarnings, _ownEarnings,
        });
      }

      // Combine storefront + EPOS for the recent-orders list
      const allOrders = [
        ...storefrontOrders.map(o => ({ id: o.id, totalAmount: o.totalAmount, resellerEarnings: o.resellerEarnings || '0', orderDate: o.orderDate, source: 'storefront' })),
        ...eposOrders.map(o => ({ ...o, source: 'epos' })),
      ];

      // Revenue breakdown: catalogue vs own products
      let catalogueRevenue = 0;
      let ownProductRevenue = 0;
      let catalogueEarnings = 0;
      let ownProductEarnings = 0;

      // EPOS orders — use the per-item breakdown computed above
      for (const order of eposOrders) {
        catalogueRevenue += order._catRev;
        ownProductRevenue += order._ownRev;
        catalogueEarnings += order._catEarnings;
        ownProductEarnings += order._ownEarnings;
      }

      // Storefront orders — split by item vendorProductId + accumulate product map
      for (const sfOrder of storefrontOrders) {
        const sfItems = await db.select().from(customerOrderItems).where(eq(customerOrderItems.orderId, sfOrder.id)).catch(() => []);
        if (sfItems.length === 0) {
          // No line-items: treat whole order as catalogue at stored earnings
          catalogueRevenue += parseFloat(sfOrder.totalAmount || '0');
          catalogueEarnings += parseFloat(sfOrder.resellerEarnings || '0');
        } else {
          for (const item of sfItems) {
            const rev = parseFloat(item.unitPrice) * item.quantity;
            if (item.vendorProductId) {
              ownProductRevenue += rev;
              ownProductEarnings += rev;
              addToProductMap(ownProductMap, item.productName, item.quantity, rev, rev);
            } else {
              const earn = rev * catalogueCommissionRate;
              catalogueRevenue += rev;
              catalogueEarnings += earn;
              addToProductMap(catProductMap, item.productName, item.quantity, rev, earn);
            }
          }
        }
      }

      // Sort product rows by revenue descending
      const catalogueProductSales = Array.from(catProductMap.values()).sort((a, b) => b.revenue - a.revenue);
      const ownProductSales = Array.from(ownProductMap.values()).sort((a, b) => b.revenue - a.revenue);

      const totalRevenue = catalogueRevenue + ownProductRevenue;
      const totalEarnings = catalogueEarnings + ownProductEarnings;
      // Platform commission = what 1stRep keeps from catalogue sales
      const platformCommission = catalogueRevenue - catalogueEarnings;

      // Use payout requests for commission payout status
      const resellerPayoutRequests = await storage.getPayoutRequestsByReseller(id);
      const pendingPayoutTotal = resellerPayoutRequests.filter(p => ['pending','approved','processing'].includes(p.status || '')).reduce((s, p) => s + parseFloat(p.amount || '0'), 0);
      const paidPayoutTotal = resellerPayoutRequests.filter(p => p.status === 'paid').reduce((s, p) => s + parseFloat(p.amount || '0'), 0);
      // Available balance = total earned - already paid out. Deliberately NOT
      // clamped to zero — a negative value is a real signal (paid out or
      // requested more than was ever earned) that the admin panel surfaces
      // rather than silently hiding behind a floor of £0.00.
      const availableBalance = totalEarnings - paidPayoutTotal - pendingPayoutTotal;

      // Commission payments filtering (legacy, kept for compatibility)
      let filteredPayments = commissionPayments;
      if (start || end) {
        filteredPayments = commissionPayments.filter(p => {
          const d = new Date(p.createdAt);
          return (!start || d >= start) && (!end || d <= end);
        });
      }

      const stats = {
        totalRevenue,
        totalEarnings,
        catalogueRevenue,
        catalogueEarnings,
        ownProductRevenue,
        ownProductEarnings,
        platformCommission,
        totalCommissionPaid: platformCommission,  // kept for UI compatibility
        pendingCommission: availableBalance,
        paidCommission: paidPayoutTotal,
        pendingPayoutTotal,
        availableBalance,
        commissionRate: parseFloat(commissionRateRaw),
        totalOrders: allOrders.length,
        storefrontOrders: storefrontOrders.length,
        eposOrders: eposOrders.length,
        averageOrderValue: allOrders.length > 0 ? totalRevenue / allOrders.length : 0,
        catalogueProductSales,
        ownProductSales,
      };

      // Build recentOrders combining both, sorted by date
      const recentOrders = allOrders
        .sort((a, b) => new Date(b.orderDate).getTime() - new Date(a.orderDate).getTime())
        .slice(0, 10);

      res.json({
        commissionPayments: filteredPayments,
        commissionRules,
        recentOrders,
        stats
      });
    } catch (error) {
      console.error("Get reseller earnings error:", error);
      res.status(500).json({ error: "Failed to load reseller earnings" });
    }
  });

