  // Vendor Dashboard - Get comprehensive stats
  app.get("/api/vendor/dashboard", requireAuth, requireVendor, async (req, res) => {
    try {
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      // Get vendor products
      const products = await storage.getVendorProducts(vendor.id);
      const activeProducts = products.filter(p => p.isActive);
      const vendorProductIds = products.map(p => p.id);
      
      // Get reseller permissions
      const permissions = await storage.getVendorResellerPermissions(vendor.id);
      const activeResellers = permissions.filter(p => p.isApproved).length;
      
      // Calculate stats from products (legacy method)
      const totalProducts = products.length;
      const productBasedTotalSold = products.reduce((sum, p) => sum + (p.totalSold || 0), 0);
      
      // Get actual order data for accurate stats
      // Get orders where vendorId matches
      const vendorOrders = await db.select().from(customerOrders)
        .where(eq(customerOrders.vendorId, vendor.id));
      
      // Also get order items containing vendor products
      const orderItemsWithVendorProducts = vendorProductIds.length > 0 
        ? await db.select().from(customerOrderItems)
            .where(sql`vendor_product_id IN (${sql.join(vendorProductIds.map(id => sql`${id}`), sql`, `)})`)
        : [];
      
      // Calculate actual revenue from order items
      const actualRevenue = orderItemsWithVendorProducts.reduce((sum, item) => 
        sum + parseFloat(item.totalPrice), 0
      );
      
      // Calculate actual quantity sold
      const actualQuantitySold = orderItemsWithVendorProducts.reduce((sum, item) => 
        sum + item.quantity, 0
      );
      
      // Get unique order IDs for order count
      const uniqueOrderIds = [...new Set(orderItemsWithVendorProducts.map(item => item.orderId))];
      const totalOrders = uniqueOrderIds.length;
      
      // Use actual data if available, fallback to product-based stats
      const totalSold = actualQuantitySold > 0 ? actualQuantitySold : productBasedTotalSold;
      const totalRevenue = actualRevenue > 0 ? actualRevenue : products.reduce((sum, p) => {
        const sold = p.totalSold || 0;
        const price = parseFloat(p.retailPrice as string) || 0;
        return sum + (sold * price);
      }, 0);

      res.json({
        vendor,
        stats: {
          totalProducts,
          activeProducts: activeProducts.length,
          totalSold,
          totalRevenue: totalRevenue.toFixed(2),
          totalOrders,
          activeResellers,
          pendingPermissions: permissions.filter(p => !p.isApproved).length,
          averageRating: vendor.averageRating || "0.00",
        }
      });
    } catch (error) {
      console.error("Vendor dashboard error:", error);
      res.status(500).json({ error: "Failed to load dashboard" });
    }
  });

