  // Vendor Categories - Create custom category
  app.post("/api/vendor/categories", requireAuth, requireVendor, async (req, res) => {
    try {
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      const { name, description, imageUrl } = req.body;
      if (!name) {
        return res.status(400).json({ error: "Category name is required" });
      }

      // Generate slug from name
      const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') + '-' + vendor.id.slice(0, 6);
      
      // Check if slug exists
      const existingCategory = await storage.getCategoryBySlug(slug);
      if (existingCategory) {
        return res.status(400).json({ error: "A category with a similar name already exists" });
      }

      const category = await storage.createCategory({
        name,
        slug,
        description: description || '',
        scope: 'vendor',
        vendorId: vendor.id,
        imageUrl: imageUrl || '',
        isActive: true,
        displayOrder: 100, // Default high order for custom categories
      });

      res.status(201).json({ message: "Category created successfully", category });
    } catch (error) {
      console.error("Create vendor category error:", error);
      res.status(500).json({ error: "Failed to create category" });
    }
  });

  // Vendor Categories - Update category (only vendor's own categories)
  app.patch("/api/vendor/categories/:categoryId", requireAuth, requireVendor, async (req, res) => {
    try {
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      const { categoryId } = req.params;
      const category = await storage.getCategory(categoryId);
      
      if (!category) {
        return res.status(404).json({ error: "Category not found" });
      }

      // Vendors can only edit their own categories
      if (category.vendorId !== vendor.id) {
        return res.status(403).json({ error: "Not authorized to edit this category" });
      }

      const { name, description, imageUrl, isActive } = req.body;
      const updates: any = {};
      if (name !== undefined) updates.name = name;
      if (description !== undefined) updates.description = description;
      if (imageUrl !== undefined) updates.imageUrl = imageUrl;
      if (isActive !== undefined) updates.isActive = isActive;

      const updatedCategory = await storage.updateCategory(categoryId, updates);
      res.json({ message: "Category updated successfully", category: updatedCategory });
    } catch (error) {
      console.error("Update vendor category error:", error);
      res.status(500).json({ error: "Failed to update category" });
    }
  });

