  // Vendor Reseller Access - All vendors automatically have reseller access
  app.get("/api/vendor/reseller-access-status", requireAuth, requireVendor, async (req, res) => {
    try {
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      // Check if a reseller record exists for this user
      let reseller = await storage.getResellerByUserId(req.user!.id);
      
      // Auto-create and approve reseller record for vendors if it doesn't exist
      if (!reseller) {
        reseller = await storage.createReseller({
          userId: req.user!.id,
          businessName: vendor.businessName,
          contactPerson: vendor.businessName,
          businessAddress: vendor.businessAddress || "Not provided",
          phoneNumber: vendor.phoneNumber || "Not provided",
          tier: "bronze",
          discountPercentage: "15.00",
          creditLimit: "5000.00",
          isActive: true, // Auto-activate for vendors
        });
        console.log(`Auto-created reseller access for vendor: ${vendor.businessName}`);
      } else if (!reseller.isActive) {
        // Auto-activate if not active (vendors always get access)
        await storage.updateReseller(reseller.id, { isActive: true });
        reseller = { ...reseller, isActive: true };
      }

      res.json({
        hasResellerAccess: true,
        status: "approved",
        reseller: {
          id: reseller.id,
          businessName: reseller.businessName,
          tier: reseller.tier,
          discountPercentage: reseller.discountPercentage,
          creditLimit: reseller.creditLimit,
        }
      });
    } catch (error) {
      console.error("Check reseller access error:", error);
      res.status(500).json({ error: "Failed to check reseller access" });
    }
  });

  // Vendor Reseller Access - Request reseller access (creates reseller record for vendor's user)
  app.post("/api/vendor/request-reseller-access", requireAuth, requireVendor, async (req, res) => {
    try {
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      // Check if reseller access already exists
      const existingReseller = await storage.getResellerByUserId(req.user!.id);
      if (existingReseller) {
        return res.status(400).json({ 
          error: "Reseller access already requested",
          status: existingReseller.approvalStatus 
        });
      }

      // Create reseller profile for this vendor's user
      const reseller = await storage.createReseller({
        userId: req.user!.id,
        businessName: vendor.businessName,
        contactPerson: vendor.businessName, // Use business name as contact
        businessAddress: vendor.businessAddress || "Not provided",
        phoneNumber: vendor.phoneNumber || "Not provided",
        tier: "bronze",
        discountPercentage: "10.00",
        creditLimit: "1000.00",
        isActive: false, // Requires admin approval
      });

      // Send notification email (optional)
      try {
        const user = await storage.getUser(req.user!.id);
        if (user?.email) {
          console.log(`Vendor ${vendor.businessName} requested reseller access`);
        }
      } catch (emailError) {
        console.error('Email notification failed:', emailError);
      }

      res.status(201).json({ 
        message: "Reseller access requested successfully. Please wait for admin approval.",
        paidAt: (paymentMethod === "paypal" && paypalOrderId) ? new Date() : null,
          status: (paymentMethod === "paypal" && paypalOrderId) ? "processing" : "pending",
        reseller: {
          id: reseller.id,
          businessName: reseller.businessName,
        }
      });
    } catch (error) {
      console.error("Request reseller access error:", error);
      res.status(500).json({ error: "Failed to request reseller access" });
    }
  });

