  // Get vendor Stripe Connect status
  app.get("/api/vendor/stripe-connect/status", requireAuth, requireVendor, async (req, res) => {
    try {
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      res.json({
        stripeAccountId: vendor.stripeAccountId,
        onboardingStatus: vendor.stripeOnboardingStatus || "not_started",
        chargesEnabled: vendor.stripeChargesEnabled || false,
        payoutsEnabled: vendor.stripePayoutsEnabled || false,
        accountEmail: vendor.stripeAccountEmail,
      });
    } catch (error) {
      console.error("Get Stripe Connect status error:", error);
      res.status(500).json({ error: "Failed to get Stripe Connect status" });
    }
  });

  // Create Stripe Connect account for vendor
  app.post("/api/vendor/stripe-connect/create-account", requireAuth, requireVendor, async (req, res) => {
    try {
      if (!stripe) {
        return res.status(503).json({ error: "Stripe not configured. Please contact support." });
      }

      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      // Check if vendor already has a Stripe account — verify it's still valid on this platform
      if (vendor.stripeAccountId) {
        try {
          await stripe.accounts.retrieve(vendor.stripeAccountId);
          return res.status(400).json({ 
            error: "Stripe account already exists",
            stripeAccountId: vendor.stripeAccountId 
          });
        } catch (verifyErr: any) {
          // Account doesn't exist on this platform (e.g. switched from test to live keys)
          // Clear the stale account ID and fall through to create a new one
          await storage.updateVendor(vendor.id, {
            stripeAccountId: null,
            stripeOnboardingStatus: "not_started",
            stripeChargesEnabled: false,
            stripePayoutsEnabled: false,
            stripeAccountEmail: null,
          });
        }
      }

      const user = await storage.getUser(req.user!.id);
      
      // Create a Stripe Connect Express account
      const account = await stripe.accounts.create({
        type: "express",
        country: "GB", // UK market
        email: user?.email || undefined,
        capabilities: {
          card_payments: { requested: true },
          transfers: { requested: true },
        },
        business_type: "individual",
        business_profile: {
          name: vendor.businessName,
          url: vendor.websiteUrl || undefined,
        },
        metadata: {
          vendorId: vendor.id,
          userId: req.user!.id,
        },
      });

      // Update vendor with Stripe account ID
      await storage.updateVendor(vendor.id, {
        stripeAccountId: account.id,
        stripeOnboardingStatus: "pending",
        stripeAccountEmail: user?.email || null,
      });

      res.json({
        success: true,
        stripeAccountId: account.id,
        message: "Stripe Connect account created. Complete onboarding to start receiving payments.",
      });
    } catch (error: any) {
      console.error("Create Stripe Connect account error:", error);
      res.status(500).json({ error: error.message || "Failed to create Stripe Connect account" });
    }
  });

  // Get Stripe Connect onboarding link
  app.post("/api/vendor/stripe-connect/onboarding-link", requireAuth, requireVendor, async (req, res) => {
    try {
      if (!stripe) {
        return res.status(503).json({ error: "Stripe not configured. Please contact support." });
      }

      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      if (!vendor.stripeAccountId) {
        return res.status(400).json({ error: "No Stripe account found. Please create one first." });
      }

      // Use production URL for Stripe Connect return URLs
      const baseUrl = getProductionBaseUrl();

      const accountLink = await stripe.accountLinks.create({
        account: vendor.stripeAccountId,
        refresh_url: `${baseUrl}/vendor/dashboard?stripe_refresh=true`,
        return_url: `${baseUrl}/vendor/dashboard?stripe_success=true`,
        type: "account_onboarding",
      });

      res.json({
        url: accountLink.url,
        expiresAt: accountLink.expires_at,
      });
    } catch (error: any) {
      console.error("Create onboarding link error:", error);
      res.status(500).json({ error: error.message || "Failed to create onboarding link" });
    }
  });

  // Refresh/check Stripe Connect account status
  app.post("/api/vendor/stripe-connect/refresh-status", requireAuth, requireVendor, async (req, res) => {
    try {
      if (!stripe) {
        return res.status(503).json({ error: "Stripe not configured" });
      }

      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor || !vendor.stripeAccountId) {
        return res.status(404).json({ error: "No Stripe account found" });
      }

      // Retrieve latest account status from Stripe
      const account = await stripe.accounts.retrieve(vendor.stripeAccountId);

      // Determine onboarding status
      let onboardingStatus = "pending";
      if (account.charges_enabled && account.payouts_enabled) {
        onboardingStatus = "complete";
      } else if (account.details_submitted) {
        onboardingStatus = "pending_verification";
      }

      // Update vendor with latest status
      await storage.updateVendor(vendor.id, {
        stripeOnboardingStatus: onboardingStatus,
        stripeChargesEnabled: account.charges_enabled || false,
        stripePayoutsEnabled: account.payouts_enabled || false,
      });

      res.json({
        stripeAccountId: vendor.stripeAccountId,
        onboardingStatus,
        chargesEnabled: account.charges_enabled || false,
        payoutsEnabled: account.payouts_enabled || false,
        detailsSubmitted: account.details_submitted || false,
      });
    } catch (error: any) {
      console.error("Refresh Stripe status error:", error);
      res.status(500).json({ error: error.message || "Failed to refresh status" });
    }
  });

