  // Get Stripe Connect onboarding link for reseller
  app.post("/api/reseller/stripe-connect/onboarding-link", requireAuth, requireReseller, async (req, res) => {
    try {
      if (!stripe) {
        return res.status(503).json({ error: "Stripe not configured. Please contact support." });
      }

      const reseller = await storage.getReseller(req.reseller!.id);
      if (!reseller) {
        return res.status(404).json({ error: "Reseller not found" });
      }

      if (!reseller.stripeAccountId) {
        return res.status(400).json({ error: "No Stripe account found. Please create one first." });
      }

      // Use production URL for Stripe Connect return URLs
      const baseUrl = getProductionBaseUrl();

      const accountLink = await stripe.accountLinks.create({
        account: reseller.stripeAccountId,
        refresh_url: `${baseUrl}/reseller/dashboard?stripe_refresh=true`,
        return_url: `${baseUrl}/reseller/dashboard?stripe_success=true`,
        type: "account_onboarding",
      });

      res.json({
        url: accountLink.url,
        expiresAt: accountLink.expires_at,
      });
    } catch (error: any) {
      console.error("Create onboarding link error:", error);
      // If Stripe says the account doesn't exist on this platform (e.g. stale test account ID),
      // clear it from the DB so the reseller can connect a fresh live account
      if (error?.message?.includes("not connected to your platform") || error?.message?.includes("does not exist")) {
        try {
          const reseller = await storage.getReseller(req.reseller!.id);
          if (reseller?.stripeAccountId) {
            await storage.updateReseller(reseller.id, {
              stripeAccountId: null,
              stripeOnboardingStatus: "not_started",
              stripeChargesEnabled: false,
              stripePayoutsEnabled: false,
              stripeAccountEmail: null,
            });
          }
        } catch (_) {}
        return res.status(400).json({ 
          error: "Your previous Stripe connection is no longer valid. Please click 'Connect Bank Account' to reconnect.",
          accountReset: true
        });
      }
      res.status(500).json({ error: error.message || "Failed to create onboarding link" });
    }
  });

