  // ─── Bring Your Own Stripe (BYOS) — reseller's own Stripe account ───────────
  // Helpers: AES-256-GCM encrypt/decrypt using platform SECRET_KEY
  function encryptOwnStripeKey(plaintext: string): string {
    const masterKey = crypto.scryptSync(process.env.SECRET_KEY || 'fallback-stripe-enc-key', 'byos-salt-v1', 32);
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', masterKey, iv);
    const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
    const authTag = cipher.getAuthTag();
    return Buffer.concat([iv, authTag, encrypted]).toString('base64');
  }

  function decryptOwnStripeKey(ciphertext: string): string {
    const masterKey = crypto.scryptSync(process.env.SECRET_KEY || 'fallback-stripe-enc-key', 'byos-salt-v1', 32);
    const data = Buffer.from(ciphertext, 'base64');
    const iv = data.subarray(0, 16);
    const authTag = data.subarray(16, 32);
    const encrypted = data.subarray(32);
    const decipher = crypto.createDecipheriv('aes-256-gcm', masterKey, iv);
    decipher.setAuthTag(authTag);
    return Buffer.concat([decipher.update(encrypted), decipher.final()]).toString('utf8');
  }

