  // POST /api/reseller/own-stripe/setup — validate & save own Stripe keys
  app.post("/api/reseller/own-stripe/setup", requireAuth, requireReseller, async (req, res) => {
    try {
      const { publishableKey, secretKey } = req.body;
      if (!publishableKey || !secretKey) {
        return res.status(400).json({ error: "Both publishable key and secret key are required" });
      }
      if (!publishableKey.startsWith('pk_')) {
        return res.status(400).json({ error: "Invalid publishable key — must start with pk_live_ or pk_test_" });
      }
      if (!secretKey.startsWith('sk_')) {
        return res.status(400).json({ error: "Invalid secret key — must start with sk_live_ or sk_test_" });
      }

      // Validate the secret key works by calling Stripe
      let accountName = '';
      try {
        const testStripe = new Stripe(secretKey, { apiVersion: "2025-08-27.basil" as any });
        const account = await testStripe.accounts.retrieve();
        accountName = account.business_profile?.name || account.email || '';
      } catch (stripeErr: any) {
        return res.status(400).json({ error: "Invalid Stripe secret key — could not authenticate with Stripe. Please check the key and try again." });
      }

      const encryptedSecret = encryptOwnStripeKey(secretKey);
      await storage.updateReseller(req.reseller!.id, {
        ownStripePublishableKey: publishableKey,
        ownStripeSecretKeyEnc: encryptedSecret,
        ownStripeSetupAt: new Date(),
      } as any);

      res.json({
        success: true,
        publishableKey,
        accountName,
        message: "Your Stripe account has been connected. Customers can now pay directly into your account.",
      });
    } catch (error: any) {
      console.error("Own Stripe setup error:", error);
      res.status(500).json({ error: error.message || "Failed to save Stripe keys" });
    }
  });

