      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      if (!req.file) {
        return res.status(400).json({ error: "No image file provided" });
      }

      // Generate unique filename
      const timestamp = Date.now();
      const sanitizedVendorName = vendor.businessName.replace(/[^a-zA-Z0-9]/g, '-').toLowerCase();
      const ext = req.file.originalname.split('.').pop() || 'jpg';
      const key = `vendor-products/${sanitizedVendorName}/${timestamp}-${Math.random().toString(36).substring(7)}.${ext}`;

      const objectStorageService = new ObjectStorageService();
      const objectPath = await objectStorageService.uploadBuffer(key, req.file.buffer, req.file.mimetype);

      res.json({ 
        success: true, 
        imageUrl: objectPath,
        message: "Image uploaded successfully" 
      });
