  // Vendor Orders - Get orders containing vendor products
  app.get("/api/vendor/orders", requireAuth, requireVendor, async (req, res) => {
    try {
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      // Get vendor products to find related order items
      const vendorProducts = await storage.getVendorProducts(vendor.id);
      const vendorProductIds = vendorProducts.map(p => p.id);

      // Get orders where vendorId matches OR orders that have items with vendor product IDs
      const allOrders = await db.select().from(customerOrders)
        .where(or(
          eq(customerOrders.vendorId, vendor.id),
          // Also check orders with channel 'vendor_epos' that don't have vendorId set (legacy)
          and(
            eq(customerOrders.channel, 'vendor_epos'),
            isNull(customerOrders.vendorId)
          )
        ))
        .orderBy(desc(customerOrders.orderDate));
      
      // Also get orders containing vendor product items (by checking order_items)
      const orderItemsWithVendorProducts = vendorProductIds.length > 0 
        ? await db.select().from(customerOrderItems)
            .where(sql`vendor_product_id IN (${sql.join(vendorProductIds.map(id => sql`${id}`), sql`, `)})`)
        : [];
      
      // Get unique order IDs from order items
      const orderIdsFromItems = [...new Set(orderItemsWithVendorProducts.map(item => item.orderId))];
      
      // Fetch those orders too
      let ordersFromItems: any[] = [];
      if (orderIdsFromItems.length > 0) {
        ordersFromItems = await db.select().from(customerOrders)
          .where(sql`id IN (${sql.join(orderIdsFromItems.map(id => sql`${id}`), sql`, `)})`)
          .orderBy(desc(customerOrders.orderDate));
      }
      
      // Combine and deduplicate orders
      const allOrdersMap = new Map<string, any>();
      [...allOrders, ...ordersFromItems].forEach(order => {
        allOrdersMap.set(order.id, order);
      });
      
      const combinedOrders = Array.from(allOrdersMap.values())
        .sort((a, b) => new Date(b.orderDate).getTime() - new Date(a.orderDate).getTime());
      
      // Fetch order items for each order
      const ordersWithItems = await Promise.all(combinedOrders.map(async (order) => {
        const items = await db.select().from(customerOrderItems)
          .where(eq(customerOrderItems.orderId, order.id));
        
        // Filter to only show vendor's product items
        const vendorItems = items.filter(item => 
          item.vendorProductId && vendorProductIds.includes(item.vendorProductId)
        );
        
        // Calculate vendor revenue (sum of vendor product items)
        const vendorRevenue = vendorItems.reduce((sum, item) => 
          sum + parseFloat(item.totalPrice), 0
        );
        
        return {
          ...order,
          items: vendorItems,
          allItems: items,
          vendorRevenue: vendorRevenue.toFixed(2),
          itemCount: vendorItems.length,
          totalItemCount: items.length,
        };
      }));
      
      // Only return orders that have vendor products
      const vendorOrders = ordersWithItems.filter(order => order.itemCount > 0 || order.vendorId === vendor.id);

      console.log(`📦 Vendor ${vendor.businessName} orders: ${vendorOrders.length} orders found`);
      res.json(vendorOrders);
    } catch (error) {
      console.error("Get vendor orders error:", error);
      res.status(500).json({ error: "Failed to load orders" });
    }
  });

