  // Create payment intent for approved wholesale order
  app.post("/api/wholesaler/orders/:id/pay", requireAuth, requireVendor, async (req, res) => {
    try {
      const { id } = req.params;
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Wholesaler account not found" });
      }
      
      const [order] = await db.select()
        .from(wholesalerOrders)
        .where(and(
          eq(wholesalerOrders.id, id),
          eq(wholesalerOrders.vendorId, vendor.id)
        ))
        .limit(1);
      
      if (!order) {
        return res.status(404).json({ error: "Order not found" });
      }
      
      if (order.status !== 'approved') {
        return res.status(400).json({ error: "Order must be approved before payment" });
      }
      
      // Create Stripe payment intent
      if (!stripe) {
        return res.status(503).json({ error: "Payment service unavailable" });
      }
      const amountInPence = Math.round(parseFloat(order.totalAmount) * 100);
      
      const paymentIntent = await stripe.paymentIntents.create({
        amount: amountInPence,
        currency: 'gbp',
        statement_descriptor_suffix: '1STREP WHOLESALE',
        metadata: {
          wholesaleOrderId: order.id,
          orderNumber: order.orderNumber,
          vendorId: vendor.id,
          vendorName: vendor.businessName
        },
        description: `Wholesale Order ${order.orderNumber}`
      });
      
      // Update order with payment intent
      await db.update(wholesalerOrders)
        .set({ 
          stripePaymentIntentId: paymentIntent.id,
          updatedAt: new Date()
        })
        .where(eq(wholesalerOrders.id, id));
      
      res.json({ 
        clientSecret: paymentIntent.client_secret,
        amount: order.totalAmount
      });
    } catch (error) {
      console.error("Create wholesale payment error:", error);
      res.status(500).json({ error: "Failed to create payment" });
    }
  });

  // Confirm wholesale order payment
  app.post("/api/wholesaler/orders/:id/confirm-payment", requireAuth, requireVendor, async (req, res) => {
    try {
      const { id } = req.params;
      const { paymentIntentId } = req.body;
      
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Wholesaler account not found" });
      }
      
      const [order] = await db.select()
        .from(wholesalerOrders)
        .where(and(
          eq(wholesalerOrders.id, id),
          eq(wholesalerOrders.vendorId, vendor.id)
        ))
        .limit(1);
      
      if (!order) {
        return res.status(404).json({ error: "Order not found" });
      }
      
      // Verify payment with Stripe
      if (!stripe) {
        return res.status(503).json({ error: "Payment service unavailable" });
      }
      const paymentIntent = await stripe.paymentIntents.retrieve(paymentIntentId || order.stripePaymentIntentId);
      
      if (paymentIntent.status !== 'succeeded') {
        return res.status(400).json({ error: "Payment not completed" });
      }
      
      // Update order to paid
      await db.update(wholesalerOrders)
        .set({ 
          status: 'paid',
          stripePaymentStatus: 'succeeded',
          paidAt: new Date(),
          updatedAt: new Date()
        })
        .where(eq(wholesalerOrders.id, id));
      
      // Create admin notification for paid order
      try {
        await storage.createAdminNotification({
          type: 'wholesale_order',
          title: 'Wholesale Order Paid',
          message: `${vendor.businessName} has paid for wholesale order ${order.orderNumber} - ready for processing`,
          link: '/admin/wholesale-orders',
          isRead: false,
        });
      } catch (notifError) {
        console.error("Failed to create admin notification:", notifError);
      }
      
      // Get order items for email
      const orderItems = await db.select()
        .from(wholesalerOrderItems)
        .where(eq(wholesalerOrderItems.orderId, id));
      
      const itemCount = orderItems.reduce((sum, item) => sum + (item.quantity || 0), 0);
      
      // Send email + SMS notifications
      try {
        // Email to wholesaler
        await sendWholesaleOrderPaymentEmail({
          email: vendor.email,
          businessName: vendor.businessName,
          orderNumber: order.orderNumber,
          totalAmount: (Number(order.totalAmount) / 100).toFixed(2),
          itemCount
        });
        
        // Email to admin
        await sendWholesaleOrderAdminNotificationEmail({
          orderNumber: order.orderNumber,
          businessName: vendor.businessName,
          totalAmount: (Number(order.totalAmount) / 100).toFixed(2),
          itemCount
        });
        
        console.log(`📧 Wholesale order payment emails sent for ${order.orderNumber}`);
      } catch (emailError) {
        console.error("Failed to send wholesale order emails:", emailError);
      }
      smsWholesaleOrderPaid(vendor.phoneNumber, vendor.businessName, order.orderNumber, (Number(order.totalAmount) / 100).toFixed(2), itemCount);
      
      console.log(`💳 Wholesale order ${order.orderNumber} paid by ${vendor.businessName}`);
      
      res.json({ message: "Payment confirmed successfully! Your order will be processed shortly." });
    } catch (error) {
      console.error("Confirm wholesale payment error:", error);
      res.status(500).json({ error: "Failed to confirm payment" });
    }
  });

