  // =====================================================
  // VENDOR EPOS SECURITY API ROUTES
  // =====================================================

  // Verify EPOS PIN and create session with rate limiting
  app.post("/api/vendor/epos/verify-pin", requireAuth, requireVendor, async (req, res) => {
    try {
      const { pin } = req.body;
      if (!pin || pin.length !== 4) {
        return res.status(400).json({ error: "Invalid PIN format" });
      }

      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      // Rate limiting: Check if vendor is locked out
      const lockedUntil = (vendor as any).eposLockedUntil;
      if (lockedUntil && new Date(lockedUntil) > new Date()) {
        // Still locked - reject without logging duplicate blocked attempts
        const remainingMinutes = Math.ceil((new Date(lockedUntil).getTime() - Date.now()) / 60000);
        return res.status(429).json({ 
          error: `Too many failed attempts. Try again in ${remainingMinutes} minute(s).`,
          lockedUntil: lockedUntil
        });
      }
      
      // If lockout has expired, reset failed attempts counter and re-fetch vendor
      let currentVendor = vendor;
      let currentFailedAttempts = (vendor as any).eposFailedAttempts || 0;
      if (lockedUntil && new Date(lockedUntil) <= new Date()) {
        await db.update(vendors)
          .set({ 
            eposFailedAttempts: 0,
            eposLockedUntil: null
          })
          .where(eq(vendors.id, vendor.id));
        // Re-fetch vendor to get fresh data
        const refreshedVendor = await storage.getVendorByUserId(req.user!.id);
        if (refreshedVendor) {
          currentVendor = refreshedVendor;
        }
        // Reset counter to prevent immediate re-lock
        currentFailedAttempts = 0;
      }

      // Check if vendor has a PIN set - require PIN setup if not
      const storedPinHash = (currentVendor as any).eposPinHash;
      let isValid = false;

      if (!storedPinHash) {
        // No PIN set - allow default "1234" for first-time setup only
        // After verifying with default, they must set a custom PIN
        isValid = pin === "1234";
        if (isValid) {
          // First-time login: Create LIMITED session for PIN setup only
          // verified: false prevents EPOS operations until secure PIN is set
          const sessionDuration = 10; // Short session for PIN setup
          const expiresAt = new Date(Date.now() + sessionDuration * 60 * 1000);
          
          (req.session as any).eposSession = {
            vendorId: currentVendor.id,
            expiresAt: expiresAt.toISOString(),
            verified: false, // NOT verified - cannot perform EPOS operations
            requiresPinSetup: true // Flag for frontend to force PIN change
          };

          await storage.createEposActivityLog({
            userId: req.user!.id,
            vendorId: currentVendor.id,
            activityType: "login",
            details: JSON.stringify({ success: true, firstTimeLogin: true, limitedSession: true }),
            ipAddress: req.ip || req.connection.remoteAddress,
            userAgent: req.headers["user-agent"],
          });

          return res.json({ 
            success: true, 
            expiresAt: expiresAt.toISOString(),
            sessionDuration,
            requiresPinSetup: true // Tell frontend to prompt for PIN change
          });
        }
      } else {
        // Verify against stored hash
        const bcrypt = await import("bcryptjs");
        isValid = await bcrypt.compare(pin, storedPinHash);
        
        // Security: Check if stored hash matches weak PINs - BLOCK access and require PIN change
        if (isValid) {
          const weakPins = ["1234", "0000", "1111", "2222", "3333", "4444", "5555", "6666", "7777", "8888", "9999", "1212", "0123"];
          let isWeakPin = false;
          for (const weakPin of weakPins) {
            if (await bcrypt.compare(weakPin, storedPinHash)) {
              isWeakPin = true;
              break;
            }
          }
          
          if (isWeakPin) {
            // PIN is too weak - DO NOT grant access or create session
            // User must change PIN via settings page, not EPOS
            
            // SECURITY: Clear any existing EPOS session to prevent session reuse
            delete (req.session as any).eposSession;

            await storage.createEposActivityLog({
              userId: req.user!.id,
              vendorId: currentVendor.id,
              activityType: "weak_pin_blocked",
              details: JSON.stringify({ blocked: true, weakPinDetected: true }),
              ipAddress: req.ip || req.connection.remoteAddress,
              userAgent: req.headers["user-agent"],
            });

            // Return 403 to block access - no session created
            // User must change PIN via vendor settings, not via EPOS
            return res.status(403).json({ 
              error: "Your PIN is too weak. Please set a new secure PIN in your vendor settings before accessing EPOS.",
              requiresPinSetup: true,
              weakPinBlocked: true
            });
          }
        }
      }

      if (!isValid) {
        // Increment failed attempts using the reset-aware counter
        const failedAttempts = currentFailedAttempts + 1;
        const maxAttempts = 5;
        const lockoutMinutes = 15;

        let updateData: any = { eposFailedAttempts: failedAttempts };
        
        // Lock account after max attempts
        if (failedAttempts >= maxAttempts) {
          const lockoutUntil = new Date(Date.now() + lockoutMinutes * 60 * 1000);
          updateData.eposLockedUntil = lockoutUntil;
          
          await storage.createEposActivityLog({
            userId: req.user!.id,
            vendorId: currentVendor.id,
            activityType: "account_locked",
            details: JSON.stringify({ 
              reason: "Too many failed attempts", 
              failedAttempts,
              lockoutMinutes 
            }),
            ipAddress: req.ip || req.connection.remoteAddress,
            userAgent: req.headers["user-agent"],
          });
        }

        await db.update(vendors)
          .set(updateData)
          .where(eq(vendors.id, currentVendor.id));

        // Log failed attempt
        await storage.createEposActivityLog({
          userId: req.user!.id,
          vendorId: currentVendor.id,
          activityType: "login_failed",
          details: JSON.stringify({ 
            reason: "Invalid PIN",
            attemptNumber: failedAttempts,
            remainingAttempts: maxAttempts - failedAttempts
          }),
          ipAddress: req.ip || req.connection.remoteAddress,
          userAgent: req.headers["user-agent"],
        });

        const remainingAttempts = maxAttempts - failedAttempts;
        if (remainingAttempts <= 0) {
          return res.status(429).json({ 
            error: `Account locked for ${lockoutMinutes} minutes due to too many failed attempts.`
          });
        }
        
        return res.status(401).json({ 
          error: `Invalid PIN. ${remainingAttempts} attempt(s) remaining.`
        });
      }

      // Successful login - reset failed attempts
      await db.update(vendors)
        .set({ 
          eposLastActivity: new Date(),
          eposFailedAttempts: 0,
          eposLockedUntil: null
        })
        .where(eq(vendors.id, currentVendor.id));

      // Log successful login
      await storage.createEposActivityLog({
        userId: req.user!.id,
        vendorId: currentVendor.id,
        activityType: "login",
        details: JSON.stringify({ success: true }),
        ipAddress: req.ip || req.connection.remoteAddress,
        userAgent: req.headers["user-agent"],
      });

      // Create session token (store in session)
      const sessionDuration = (currentVendor as any).eposSessionDuration || 30;
      const expiresAt = new Date(Date.now() + sessionDuration * 60 * 1000);
      
      // Store EPOS session info in user session
      (req.session as any).eposSession = {
        vendorId: currentVendor.id,
        expiresAt: expiresAt.toISOString(),
        verified: true
      };

      res.json({ 
        success: true, 
        expiresAt: expiresAt.toISOString(),
        sessionDuration
      });
    } catch (error) {
      console.error("EPOS PIN verification error:", error);
      res.status(500).json({ error: "Failed to verify PIN" });
    }
  });

  // Set or update EPOS PIN
  app.post("/api/vendor/epos/set-pin", requireAuth, requireVendor, async (req, res) => {
    try {
      const { currentPin, newPin } = req.body;
      if (!newPin || newPin.length !== 4 || !/^\d{4}$/.test(newPin)) {
        return res.status(400).json({ error: "New PIN must be exactly 4 digits" });
      }

      // Security: Reject default PIN and common weak PINs
      const weakPins = ["1234", "0000", "1111", "2222", "3333", "4444", "5555", "6666", "7777", "8888", "9999", "1212", "0123"];
      if (weakPins.includes(newPin)) {
        return res.status(400).json({ error: "This PIN is too easy to guess. Please choose a more secure PIN." });
      }

      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      // If PIN already exists, verify current PIN
      const storedPinHash = (vendor as any).eposPinHash;
      if (storedPinHash) {
        if (!currentPin) {
          return res.status(400).json({ error: "Current PIN required to change PIN" });
        }
        const bcrypt = await import("bcryptjs");
        const isValid = await bcrypt.compare(currentPin, storedPinHash);
        if (!isValid) {
          return res.status(401).json({ error: "Current PIN is incorrect" });
        }
      }

      // Hash and store new PIN
      const bcrypt = await import("bcryptjs");
      const hashedPin = await bcrypt.hash(newPin, 10);
      
      await db.update(vendors)
        .set({ eposPinHash: hashedPin })
        .where(eq(vendors.id, vendor.id));

      // Log PIN change
      await storage.createEposActivityLog({
        userId: req.user!.id,
        vendorId: vendor.id,
        activityType: "pin_changed",
        details: JSON.stringify({ success: true, firstTimeSetup: !storedPinHash }),
        ipAddress: req.ip || req.connection.remoteAddress,
        userAgent: req.headers["user-agent"],
      });

      // Update session to fully verified after first-time PIN setup
      const eposSession = (req.session as any).eposSession;
      if (eposSession) {
        eposSession.requiresPinSetup = false;
        eposSession.verified = true; // Now fully verified with secure PIN
        
        // Extend session duration for first-time setup
        const sessionDuration = (vendor as any).eposSessionDuration || 30;
        const expiresAt = new Date(Date.now() + sessionDuration * 60 * 1000);
        eposSession.expiresAt = expiresAt.toISOString();
      }

      res.json({ success: true, message: "PIN updated successfully" });
    } catch (error) {
      console.error("Set EPOS PIN error:", error);
      res.status(500).json({ error: "Failed to set PIN" });
    }
  });

  // Check EPOS session validity
  app.get("/api/vendor/epos/session", requireAuth, requireVendor, async (req, res) => {
    try {
      const eposSession = (req.session as any).eposSession;
      
      // No session at all
      if (!eposSession) {
        return res.json({ valid: false, reason: "No active session" });
      }
      
      // Session exists but not verified - check if it's a first-time PIN setup session
      if (!eposSession.verified) {
        if (eposSession.requiresPinSetup) {
          // First-time login - allow PIN setup but not EPOS operations
          return res.json({ 
            valid: false, 
            reason: "PIN setup required",
            requiresPinSetup: true,
            expiresAt: eposSession.expiresAt
          });
        }
        return res.json({ valid: false, reason: "Session not verified" });
      }

      const expiresAt = new Date(eposSession.expiresAt);
      if (expiresAt < new Date()) {
        // Session expired
        delete (req.session as any).eposSession;
        return res.json({ valid: false, reason: "Session expired" });
      }

      // Critical security check: Always verify vendor has a secure PIN set
      // Even if session exists, if vendor has no custom PIN or weak PIN, BLOCK access
      const vendor = await storage.getVendorByUserId(req.user!.id);
      const storedPinHash = vendor && (vendor as any).eposPinHash;
      
      let hasSecurePin = !!storedPinHash;
      
      // Check if stored hash matches any weak PIN
      if (storedPinHash) {
        const bcrypt = await import("bcryptjs");
        const weakPins = ["1234", "0000", "1111", "2222", "3333", "4444", "5555", "6666", "7777", "8888", "9999", "1212", "0123"];
        for (const weakPin of weakPins) {
          if (await bcrypt.compare(weakPin, storedPinHash)) {
            hasSecurePin = false; // PIN is weak, force change
            break;
          }
        }
      }
      
      // If no custom PIN or weak PIN, session is INVALID - must change PIN first
      if (!hasSecurePin) {
        // Update session to require PIN setup
        eposSession.requiresPinSetup = true;
        eposSession.verified = false;
        
        return res.json({ 
          valid: false, // BLOCK access - not valid until secure PIN is set
          reason: "Weak PIN detected. Please set a secure PIN.",
          requiresPinSetup: true,
          weakPinBlocked: true
        });
      }

      res.json({ 
        valid: true, 
        expiresAt: eposSession.expiresAt,
        vendorId: eposSession.vendorId,
        requiresPinSetup: false // Secure PIN confirmed
      });
    } catch (error) {
      console.error("Check EPOS session error:", error);
      res.status(500).json({ error: "Failed to check session" });
    }
  });

  // Refresh EPOS session (extend timeout)
  app.post("/api/vendor/epos/refresh-session", requireAuth, requireVendor, async (req, res) => {
    try {
      const eposSession = (req.session as any).eposSession;
      
      if (!eposSession || !eposSession.verified) {
        return res.status(401).json({ error: "No active session" });
      }

      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }
      
      // Security check: Verify vendor has a secure PIN before refreshing session
      const storedPinHash = (vendor as any).eposPinHash;
      if (storedPinHash) {
        const bcrypt = await import("bcryptjs");
        const weakPins = ["1234", "0000", "1111", "2222", "3333", "4444", "5555", "6666", "7777", "8888", "9999", "1212", "0123"];
        for (const weakPin of weakPins) {
          if (await bcrypt.compare(weakPin, storedPinHash)) {
            // Weak PIN detected - invalidate session
            delete (req.session as any).eposSession;
            return res.status(403).json({ 
              error: "Weak PIN detected. Please set a secure PIN.",
              weakPinBlocked: true 
            });
          }
        }
      }
      
      const sessionDuration = (vendor as any).eposSessionDuration || 30;
      const expiresAt = new Date(Date.now() + sessionDuration * 60 * 1000);

      // Update session
      (req.session as any).eposSession = {
        ...eposSession,
        expiresAt: expiresAt.toISOString()
      };

      // Update last activity
      if (vendor) {
        await db.update(vendors)
          .set({ eposLastActivity: new Date() })
          .where(eq(vendors.id, vendor.id));
      }

      res.json({ success: true, expiresAt: expiresAt.toISOString() });
    } catch (error) {
      console.error("Refresh EPOS session error:", error);
      res.status(500).json({ error: "Failed to refresh session" });
    }
  });

  // Lock EPOS (end session)
  app.post("/api/vendor/epos/lock", requireAuth, requireVendor, async (req, res) => {
    try {
      const vendor = await storage.getVendorByUserId(req.user!.id);
      
      // Clear EPOS session
      delete (req.session as any).eposSession;

      // Log lock event
      if (vendor) {
        await storage.createEposActivityLog({
          userId: req.user!.id,
          vendorId: vendor.id,
          activityType: "lock",
          details: JSON.stringify({ manual: true }),
          ipAddress: req.ip || req.connection.remoteAddress,
          userAgent: req.headers["user-agent"],
        });
      }

      res.json({ success: true });
    } catch (error) {
      console.error("Lock EPOS error:", error);
      res.status(500).json({ error: "Failed to lock EPOS" });
    }
  });

  // Get EPOS activity log (for vendor to review)
  app.get("/api/vendor/epos/activity-log", requireAuth, requireVendor, async (req, res) => {
    try {
      const vendor = await storage.getVendorByUserId(req.user!.id);
      if (!vendor) {
        return res.status(404).json({ error: "Vendor not found" });
      }

      const logs = await storage.getEposActivityLogs(vendor.id, "vendor");
      res.json(logs);
    } catch (error) {
      console.error("Get EPOS activity log error:", error);
      res.status(500).json({ error: "Failed to load activity log" });
    }
  });

  // =====================================================
