  app.patch("/api/admin/resellers/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const updates = req.body;

      // Only set default discount if tier is changing AND discount is not explicitly provided
      if (updates.tier && updates.discountPercentage === undefined) {
        const tierDiscounts: Record<string, string> = {
          bronze: "10.00",
          silver: "15.00",
          gold: "25.00",
          platinum: "35.00"
        };
        updates.discountPercentage = tierDiscounts[updates.tier];
      }

      const reseller = await storage.updateReseller(id, updates);
      
      if (!reseller) {
        return res.status(404).json({ error: "Reseller not found" });
      }

      // Log the activity
      const actionType = updates.tier !== undefined ? "tier_change" : 
                         updates.creditLimit !== undefined ? "credit_adjust" : 
                         "profile_update";
      await storage.createActivityLog({
        resellerId: reseller.id,
        adminUserId: req.user!.id,
        actionType,
        description: `Admin updated reseller: ${Object.keys(updates).join(", ")}`,
        newValue: JSON.stringify(updates),
      });

      res.json({ message: "Reseller updated successfully", reseller });
    } catch (error) {
      console.error("Update reseller error:", error);
      res.status(500).json({ error: "Failed to update reseller" });
    }
  });

  // Admin deactivate/reactivate reseller
  app.patch("/api/admin/resellers/:id/status", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const { isActive } = req.body;

      const reseller = await storage.updateReseller(id, { isActive });
      if (!reseller) {
        return res.status(404).json({ error: "Reseller not found" });
      }

      // Also deactivate the user account if deactivating
      if (!isActive && reseller.userId) {
        await db.update(users).set({ isActive: false }).where(eq(users.id, reseller.userId));
      } else if (isActive && reseller.userId) {
        await db.update(users).set({ isActive: true }).where(eq(users.id, reseller.userId));
      }

      await storage.createActivityLog({
        resellerId: reseller.id,
        adminUserId: req.user!.id,
        actionType: "status_change",
        description: `Admin ${isActive ? 'activated' : 'deactivated'} reseller: ${reseller.businessName}`,
        newValue: JSON.stringify({ isActive }),
      });

      res.json({ message: `Reseller ${isActive ? 'activated' : 'deactivated'} successfully`, reseller });
    } catch (error) {
      console.error("Update reseller status error:", error);
      res.status(500).json({ error: "Failed to update reseller status" });
    }
  });

