  // Reseller Earnings & Payout Routes with optional date filtering
  app.get("/api/reseller/earnings", requireAuth, requireReseller, async (req, res) => {
    try {
      const resellerId = req.reseller!.id;
      const { startDate, endDate } = req.query;
      
      // Get data from legacy system
      const legacyBalance = await storage.getResellerEarningsBalance(resellerId);
      const payoutRequests = await storage.getPayoutRequestsByReseller(resellerId);
      let orders = await storage.getResellerCustomerOrders(resellerId);
      
      // Filter orders by date range if provided
      if (startDate || endDate) {
        const start = startDate ? new Date(startDate as string) : new Date(0);
        const end = endDate ? new Date(endDate as string) : new Date();
        orders = orders.filter(order => {
          const orderDate = new Date(order.orderDate || order.createdAt);
          return orderDate >= start && orderDate <= end;
        });
      }
      
      // Get data from new commissions table
      let resellerCommissions = await db.select().from(commissions)
        .where(eq(commissions.resellerId, resellerId));
      
      // Filter commissions by date range if provided
      if (startDate || endDate) {
        const start = startDate ? new Date(startDate as string) : new Date(0);
        const end = endDate ? new Date(endDate as string) : new Date();
        resellerCommissions = resellerCommissions.filter(c => {
          const commissionDate = new Date(c.createdAt);
          return commissionDate >= start && commissionDate <= end;
        });
      }
      
      // Calculate commission summary from new table
      const commissionSummary = {
        pending: resellerCommissions.filter(c => c.status === 'pending')
          .reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        confirmed: resellerCommissions.filter(c => c.status === 'confirmed')
          .reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        requested: resellerCommissions.filter(c => c.status === 'requested')
          .reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        approved: resellerCommissions.filter(c => c.status === 'approved')
          .reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        paid: resellerCommissions.filter(c => c.status === 'paid')
          .reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        total: resellerCommissions.reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
      };
      
      // Merge with legacy balance for backward compatibility
      const balance = {
        ...legacyBalance,
        commissionSummary, // Add new commission breakdown
        commissionRate: req.reseller!.commissionRate || '0',
      };
      
      // Get delivered orders for earnings breakdown
      const deliveredOrders = orders.filter(o => o.status === 'delivered');
      
      res.json({
        balance,
        payoutRequests,
        recentEarnings: deliveredOrders.slice(0, 10).map(order => ({
          orderId: order.id,
          orderNumber: order.orderNumber,
          amount: order.resellerEarnings,
          orderDate: order.orderDate
        })),
        // Include detailed commission records from new table
        recentCommissions: resellerCommissions.slice(0, 20).map(c => ({
          id: c.id,
          orderId: c.orderId,
          amount: c.commissionAmount,
          rate: c.commissionRate,
          status: c.status,
          createdAt: c.createdAt,
        })),
      });
    } catch (error) {
      console.error("Get reseller earnings error:", error);
      res.status(500).json({ error: "Failed to load earnings data" });
    }
  });

  // Reseller Earnings Breakdown - Separate own products from catalogue commission
  app.get("/api/reseller/earnings/breakdown", requireAuth, requireReseller, async (req, res) => {
    try {
      const resellerId = req.reseller!.id;
      
      // Check if reseller has vendor access (licensed to sell own products)
      const vendor = await storage.getVendorByUserId(req.user!.id);
      const vendorProducts = vendor ? await storage.getVendorProducts(vendor.id) : [];
      const vendorProductIds = vendorProducts.map(p => p.id);
      
      // Get all EPOS orders for this reseller
      const eposOrders = await db.select().from(customerOrders)
        .where(eq(customerOrders.resellerId, resellerId));
      
      // Get all storefront orders
      const storefrontOrders = await storage.getResellerCustomerOrders(resellerId);
      
      // Initialize breakdown stats
      let ownProductsStats = {
        totalRevenue: 0,
        totalOrders: 0,
        totalItemsSold: 0,
        recentOrders: [] as any[],
      };
      
      let catalogueStats = {
        totalCommission: 0,
        totalRevenue: 0,
        totalOrders: 0,
        totalItemsSold: 0,
        recentOrders: [] as any[],
      };
      
      // Process EPOS orders
      for (const order of eposOrders) {
        const items = await db.select().from(customerOrderItems)
          .where(eq(customerOrderItems.orderId, order.id));
        
        // Separate own products from catalogue products
        const ownProductItems = items.filter(item => 
          item.vendorProductId && vendorProductIds.includes(item.vendorProductId)
        );
        const catalogueItems = items.filter(item => !item.vendorProductId);
        
        // Own products revenue (100% to reseller)
        if (ownProductItems.length > 0) {
          const ownRevenue = ownProductItems.reduce((sum, item) => sum + parseFloat(item.totalPrice), 0);
          const ownQuantity = ownProductItems.reduce((sum, item) => sum + item.quantity, 0);
          
          ownProductsStats.totalRevenue += ownRevenue;
          ownProductsStats.totalItemsSold += ownQuantity;
          ownProductsStats.totalOrders += 1;
          
          if (ownProductsStats.recentOrders.length < 10) {
            ownProductsStats.recentOrders.push({
              orderId: order.id,
              orderNumber: order.orderNumber,
              orderDate: order.orderDate,
              revenue: ownRevenue.toFixed(2),
              itemCount: ownProductItems.length,
              channel: 'epos',
              items: ownProductItems.map(i => ({
                name: i.productName,
                quantity: i.quantity,
                price: i.totalPrice,
              })),
            });
          }
        }
        
        // Catalogue products commission
        if (catalogueItems.length > 0) {
          const catalogueRevenue = catalogueItems.reduce((sum, item) => sum + parseFloat(item.totalPrice), 0);
          const catalogueQuantity = catalogueItems.reduce((sum, item) => sum + item.quantity, 0);
          const commissionRate = parseFloat(req.reseller!.commissionRate || '10');
          const commission = (catalogueRevenue * commissionRate) / 100;
          
          catalogueStats.totalRevenue += catalogueRevenue;
          catalogueStats.totalCommission += commission;
          catalogueStats.totalItemsSold += catalogueQuantity;
          catalogueStats.totalOrders += 1;
          
          if (catalogueStats.recentOrders.length < 10) {
            catalogueStats.recentOrders.push({
              orderId: order.id,
              orderNumber: order.orderNumber,
              orderDate: order.orderDate,
              revenue: catalogueRevenue.toFixed(2),
              commission: commission.toFixed(2),
              itemCount: catalogueItems.length,
              channel: 'epos',
            });
          }
        }
      }
      
      // Process storefront orders (these are all catalogue products with commission)
      // Only count delivered orders - matches the balance/payout calculation
      const deliveredStorefrontOrders = storefrontOrders.filter(o => o.status === 'delivered');
      for (const order of deliveredStorefrontOrders) {
        const revenue = parseFloat(order.totalAmount);
        const earnings = parseFloat(order.resellerEarnings);
        
        catalogueStats.totalRevenue += revenue;
        catalogueStats.totalCommission += earnings;
        catalogueStats.totalOrders += 1;
        
        if (catalogueStats.recentOrders.length < 10) {
          catalogueStats.recentOrders.push({
            orderId: order.id,
            orderNumber: order.orderNumber,
            orderDate: order.orderDate,
            revenue: revenue.toFixed(2),
            commission: earnings.toFixed(2),
            channel: 'storefront',
          });
        }
      }
      
      res.json({
        hasVendorAccess: !!vendor,
        vendorTier: vendor?.licenceTier || null,
        ownProducts: {
          totalRevenue: ownProductsStats.totalRevenue.toFixed(2),
          totalOrders: ownProductsStats.totalOrders,
          totalItemsSold: ownProductsStats.totalItemsSold,
          recentOrders: ownProductsStats.recentOrders,
          description: "Revenue from your own products (100% earnings)",
        },
        catalogue: {
          totalCommission: catalogueStats.totalCommission.toFixed(2),
          totalRevenue: catalogueStats.totalRevenue.toFixed(2),
          commissionRate: req.reseller!.commissionRate || '10',
          totalOrders: catalogueStats.totalOrders,
          totalItemsSold: catalogueStats.totalItemsSold,
          recentOrders: catalogueStats.recentOrders,
          description: "Commission from 1stRep catalogue products",
        },
        combined: {
          totalEarnings: (ownProductsStats.totalRevenue + catalogueStats.totalCommission).toFixed(2),
          totalRevenue: (ownProductsStats.totalRevenue + catalogueStats.totalRevenue).toFixed(2),
          totalOrders: ownProductsStats.totalOrders + catalogueStats.totalOrders,
        },
      });
    } catch (error) {
      console.error("Get reseller earnings breakdown error:", error);
      res.status(500).json({ error: "Failed to load earnings breakdown" });
    }
  });

