  // Admin Payout Management Routes
  app.get("/api/admin/payouts", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { status } = req.query;
      let payoutRequests = await storage.getAllPayoutRequests();
      
      if (status && status !== 'all') {
        payoutRequests = payoutRequests.filter(p => p.status === status);
      }

      // Enrich with reseller or vendor info
      const enrichedPayouts = await Promise.all(
        payoutRequests.map(async (payout) => {
          let recipientName = 'Unknown';
          let recipientEmail = null;
          let recipientStripeConnected = false;
          let recipientStripeAccountId = null;

          // Handle both legacy (resellerId only) and new (recipientType) payouts
          const recipientType = payout.recipientType || 'reseller';
          
          if (recipientType === 'vendor' && payout.vendorId) {
            const vendor = await storage.getVendor(payout.vendorId);
            if (vendor) {
              recipientName = vendor.businessName;
              const user = await storage.getUser(vendor.userId);
              recipientEmail = user?.email || null;
              recipientStripeConnected = vendor.stripeOnboardingStatus === 'complete' && vendor.stripeChargesEnabled;
              recipientStripeAccountId = vendor.stripeAccountId;
            }
          } else if (payout.resellerId) {
            const reseller = await storage.getReseller(payout.resellerId);
            if (reseller) {
              recipientName = reseller.businessName;
              const user = await storage.getUser(reseller.userId);
              recipientEmail = user?.email || null;
              recipientStripeConnected = reseller.stripeOnboardingStatus === 'complete' && reseller.stripeChargesEnabled;
              recipientStripeAccountId = reseller.stripeAccountId;
            }
          }

          return {
            ...payout,
            recipientType,
            recipientName,
            recipientEmail,
            recipientStripeConnected,
            recipientStripeAccountId,
            // Keep legacy fields for backwards compatibility
            resellerName: recipientType === 'reseller' ? recipientName : undefined,
            resellerEmail: recipientType === 'reseller' ? recipientEmail : undefined,
            resellerStripeConnected: recipientType === 'reseller' ? recipientStripeConnected : undefined,
            resellerStripeAccountId: recipientType === 'reseller' ? recipientStripeAccountId : undefined,
          };
        })
      );

      res.json(enrichedPayouts);
    } catch (error) {
      console.error("Get admin payouts error:", error);
      res.status(500).json({ error: "Failed to load payout requests" });
    }
  });

