  // Admin: Pay reseller directly via Stripe Transfer
  app.post("/api/admin/payouts/:id/pay-stripe", requireAuth, requireAdmin, async (req, res) => {
    try {
      if (!stripe) {
        return res.status(503).json({ error: "Stripe not configured. Please contact support." });
      }

      const { id } = req.params;
      const { adminNotes } = req.body;
      
      const payoutRequest = await storage.getPayoutRequest(id);

      if (!payoutRequest) {
        return res.status(404).json({ error: "Payout request not found" });
      }

      if (payoutRequest.status !== 'approved') {
        return res.status(400).json({ error: "Only approved requests can be paid via Stripe" });
      }

      // Get the reseller to check their Stripe account
      const reseller = await storage.getReseller(payoutRequest.resellerId);
      if (!reseller) {
        return res.status(404).json({ error: "Reseller not found" });
      }

      if (!reseller.stripeAccountId) {
        return res.status(400).json({ error: "Reseller has not connected their Stripe account" });
      }

      if (reseller.stripeOnboardingStatus !== 'complete') {
        return res.status(400).json({ error: "Reseller has not completed Stripe onboarding" });
      }

      if (!reseller.stripePayoutsEnabled) {
        return res.status(400).json({ error: "Reseller's Stripe account is not enabled for payouts" });
      }

      // Update status to processing
      await storage.updatePayoutRequest(id, {
        status: 'processing',
        processedAt: new Date()
      });

      try {
        // Create the transfer to the connected account
        // Amount is in pence (GBP minor units)
        const amountInPence = Math.round(parseFloat(payoutRequest.amount) * 100);

        const transfer = await stripe.transfers.create({
          amount: amountInPence,
          currency: 'gbp',
          destination: reseller.stripeAccountId,
          metadata: {
            payoutRequestId: payoutRequest.id,
            requestNumber: payoutRequest.requestNumber,
            resellerId: reseller.id,
            resellerName: reseller.businessName,
          },
        }, {
          idempotencyKey: `payout-${payoutRequest.id}`, // Prevent duplicate transfers
        });

        // Update the payout request with success
        const updatedRequest = await storage.updatePayoutRequest(id, {
          status: 'paid',
          stripeTransferId: transfer.id,
          transactionReference: transfer.id,
          adminNotes: adminNotes || payoutRequest.adminNotes,
          paidAt: new Date(),
          transferError: null // Clear any previous errors
        });

        // Create audit log entry for Stripe payment
        const adminUser = await storage.getUser(req.user!.id);
        await storage.createPayoutAuditLog({
          payoutId: id,
          action: 'paid',
          previousStatus: 'processing',
          newStatus: 'paid',
          performedBy: req.user!.id,
          performedByName: adminUser?.firstName && adminUser?.lastName 
            ? `${adminUser.firstName} ${adminUser.lastName}` 
            : adminUser?.email || 'Admin',
          performedByRole: 'admin',
          notes: adminNotes,
          metadata: JSON.stringify({ 
            stripeTransferId: transfer.id, 
            paymentMethod: 'stripe_connect',
            amount: transfer.amount / 100,
            currency: transfer.currency
          }),
          ipAddress: req.ip || req.connection?.remoteAddress,
          userAgent: req.headers['user-agent'],
        });

        console.log(`💳 Stripe transfer completed for payout ${payoutRequest.requestNumber} - Transfer ID: ${transfer.id}`);

        // Reseller notification: payout sent via Stripe
        storage.createNotification({
          resellerId: payoutRequest.resellerId,
          type: 'payout_update',
          title: 'Payout Sent via Stripe',
          message: `Your payout of £${parseFloat(payoutRequest.amount).toFixed(2)} (${payoutRequest.requestNumber}) has been sent to your bank account via Stripe. Transfer ID: ${transfer.id}`,
          link: '/reseller-dashboard?tab=earnings',
        }).catch(err => console.error('Failed to create Stripe payout reseller notification:', err));

        res.json({
          message: "Payment sent via Stripe",
          payoutRequest: updatedRequest,
          transfer: {
            id: transfer.id,
            amount: transfer.amount / 100, // Convert back to pounds
            currency: transfer.currency,
          }
        });
      } catch (stripeError: any) {
        // Handle Stripe transfer errors
        console.error("Stripe transfer error:", stripeError);

        // Update payout request with error, revert to approved status
        await storage.updatePayoutRequest(id, {
          status: 'approved',
          transferError: stripeError.message || "Stripe transfer failed",
          processedAt: null
        });

        res.status(400).json({ 
          error: "Stripe transfer failed", 
          details: stripeError.message 
        });
      }
    } catch (error: any) {
      console.error("Pay via Stripe error:", error);
      res.status(500).json({ error: error.message || "Failed to process Stripe payment" });
    }
  });

  // Admin - Create manual/admin-initiated payout
  app.post("/api/admin/payouts/manual", requireAuth, requireAdmin, async (req, res) => {
    try {
      const {
        recipientType,
        recipientId,
        amount,
        payoutMethod,
        bankAccountName,
        bankAccountNumber,
        bankSortCode,
        paypalEmail,
        payoutReason,
        isAdjustment,
        payImmediately
      } = req.body;

      // Validate required fields
      if (!recipientType || !recipientId || !amount || !payoutMethod) {
        return res.status(400).json({ error: "Missing required fields" });
      }

      if (!['reseller', 'vendor'].includes(recipientType)) {
        return res.status(400).json({ error: "Invalid recipient type" });
      }

      const parsedAmount = parseFloat(amount);
      if (isNaN(parsedAmount) || parsedAmount <= 0) {
        return res.status(400).json({ error: "Invalid amount" });
      }

      // Validate recipient exists
      let recipient: any;
      let stripeAccountId: string | null = null;
      
      if (recipientType === 'reseller') {
        recipient = await storage.getReseller(recipientId);
        if (!recipient) {
          return res.status(404).json({ error: "Reseller not found" });
        }
        stripeAccountId = recipient.stripeAccountId;

        // Check available balance if not an adjustment
        if (!isAdjustment) {
          const balance = await storage.getResellerEarningsBalance(recipientId);
          if (parsedAmount > balance.availableBalance) {
            return res.status(400).json({ 
              error: "Insufficient available balance",
              availableBalance: balance.availableBalance
            });
          }
        }
      } else {
        recipient = await storage.getVendor(recipientId);
        if (!recipient) {
          return res.status(404).json({ error: "Vendor not found" });
        }
        stripeAccountId = recipient.stripeAccountId;
      }

      // Validate payment method details
      if (payoutMethod === 'bank_transfer') {
        if (!bankAccountName || !bankAccountNumber || !bankSortCode) {
          return res.status(400).json({ error: "Bank account details required" });
        }
      } else if (payoutMethod === 'paypal') {
        if (!paypalEmail) {
          return res.status(400).json({ error: "PayPal email required" });
        }
      } else if (payoutMethod === 'stripe_connect') {
        if (!stripeAccountId) {
          return res.status(400).json({ error: "Recipient has not connected their Stripe account" });
        }
      }

      // Generate request number
      const timestamp = Date.now();
      const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
      const requestNumber = `ADM-PAY-${timestamp}-${random}`;

      // Create the payout request (auto-approved since it's admin-initiated)
      const payoutRequest = await storage.createPayoutRequest({
        resellerId: recipientType === 'reseller' ? recipientId : null,
        vendorId: recipientType === 'vendor' ? recipientId : null,
        recipientType,
        requestType: 'admin_initiated',
        requestNumber,
        amount: parsedAmount.toFixed(2),
        status: 'approved', // Admin-initiated payouts are auto-approved
        payoutMethod,
        bankAccountName: payoutMethod === 'bank_transfer' ? bankAccountName : null,
        bankAccountNumber: payoutMethod === 'bank_transfer' ? bankAccountNumber : null,
        bankSortCode: payoutMethod === 'bank_transfer' ? bankSortCode : null,
        paypalEmail: payoutMethod === 'paypal' ? paypalEmail : null,
        stripeAccountId: payoutMethod === 'stripe_connect' ? stripeAccountId : null,
        initiatedByAdminId: req.user!.id,
        payoutReason: payoutReason || 'Admin-initiated payment',
        isAdjustment: isAdjustment || false,
      });

      console.log(`✅ Admin-initiated payout created: ${requestNumber} for ${recipientType} ${recipientId} - £${parsedAmount.toFixed(2)}`);

      // If payImmediately and using Stripe Connect, process the payment now
      if (payImmediately && payoutMethod === 'stripe_connect' && stripe && stripeAccountId) {
        try {
          // Check if account can receive payouts
          const stripePayoutsEnabled = recipientType === 'reseller' 
            ? recipient.stripePayoutsEnabled 
            : recipient.stripePayoutsEnabled;
            
          if (!stripePayoutsEnabled) {
            return res.json({
              message: "Payout created but cannot pay immediately - Stripe account not enabled for payouts",
              payoutRequest,
              requiresManualPayment: true
            });
          }

          const amountInPence = Math.round(parsedAmount * 100);

          const transfer = await stripe.transfers.create({
            amount: amountInPence,
            currency: 'gbp',
            destination: stripeAccountId,
            metadata: {
              payoutRequestId: payoutRequest.id,
              requestNumber: payoutRequest.requestNumber,
              recipientType,
              recipientId,
              recipientName: recipient.businessName,
              adminInitiated: 'true'
            },
          }, {
            idempotencyKey: `admin-payout-${payoutRequest.id}`,
          });

          // Update to paid status
          const updatedRequest = await storage.updatePayoutRequest(payoutRequest.id, {
            status: 'paid',
            stripeTransferId: transfer.id,
            transactionReference: transfer.id,
            paidAt: new Date(),
            processedAt: new Date()
          });

          console.log(`💳 Stripe transfer completed for admin payout ${requestNumber} - Transfer ID: ${transfer.id}`);

          return res.json({
            message: "Payment sent via Stripe",
            payoutRequest: updatedRequest,
            transfer: {
              id: transfer.id,
              amount: transfer.amount / 100,
              currency: transfer.currency,
            }
          });
        } catch (stripeError: any) {
          console.error("Stripe transfer error for admin payout:", stripeError);
          
          // Update with error but keep approved status
          await storage.updatePayoutRequest(payoutRequest.id, {
            transferError: stripeError.message || "Stripe transfer failed"
          });

          return res.json({
            message: "Payout created but Stripe transfer failed",
            payoutRequest,
            error: stripeError.message,
            requiresManualPayment: true
          });
        }
      }

      res.json({
        message: "Admin-initiated payout created",
        payoutRequest
      });
    } catch (error: any) {
      console.error("Create admin payout error:", error);
      res.status(500).json({ error: error.message || "Failed to create payout" });
    }
  });

  // Admin Dashboard - Commission Overview
