  // Reseller Order Management Routes
  app.get("/api/reseller/orders", requireAuth, requireReseller, async (req, res) => {
    try {
      // Get reseller profile to get commission rate
      const reseller = await storage.getReseller(req.reseller!.id);
      const resellerCommissionRate = reseller?.commissionRate ? parseFloat(reseller.commissionRate) / 100 : 0.10;
      
      // Get orders from reseller storefront (resellerCustomerOrders table)
      const storefrontOrders = await storage.getResellerCustomerOrders(req.reseller!.id);
      
      // Also get EPOS orders from main customerOrders table where resellerId matches
      const eposOrders = await db.select().from(customerOrders)
        .where(eq(customerOrders.resellerId, req.reseller!.id))
        .orderBy(desc(customerOrders.orderDate));
      
      // Get items for EPOS orders
      const eposOrdersWithItems = await Promise.all(eposOrders.map(async (order) => {
        const items = await db.select().from(customerOrderItems)
          .where(eq(customerOrderItems.orderId, order.id));
        
        const hasVendorProducts = items.some(item => item.vendorProductId);
        const vendorProductTotal = items
          .filter(item => item.vendorProductId)
          .reduce((sum, item) => sum + parseFloat(item.totalPrice), 0);
        const catalogProductTotal = items
          .filter(item => !item.vendorProductId)
          .reduce((sum, item) => sum + parseFloat(item.totalPrice), 0);
        
        // For EPOS: reseller keeps 100% of own products + commission on catalogue products
        const catalogEarnings = catalogProductTotal * resellerCommissionRate;
        const totalEarnings = vendorProductTotal + catalogEarnings;
        const platformFee = catalogProductTotal - catalogEarnings;
        
        const itemsTotal = vendorProductTotal + catalogProductTotal;
        
        return {
          ...order,
          totalAmount: itemsTotal > 0 ? itemsTotal.toFixed(2) : order.totalAmount,
          items,
          itemCount: items.length,
          channel: order.channel || 'reseller_epos',
          resellerEarnings: totalEarnings.toFixed(2),
          platformCommission: platformFee.toFixed(2),
          catalogRevenue: catalogProductTotal.toFixed(2),
          hasVendorProducts,
          orderType: 'epos',
        };
      }));
      
      // Format storefront orders with items
      const formattedStorefrontOrders = await Promise.all(storefrontOrders.map(async (order) => {
        const items = await db.select().from(resellerCustomerOrderItems)
          .where(eq(resellerCustomerOrderItems.orderId, order.id));
        return {
          ...order,
          items,
          itemCount: items.length,
          orderType: 'storefront',
        };
      }));
      
      // Combine and sort by date
      const allOrders = [...formattedStorefrontOrders, ...eposOrdersWithItems]
        .sort((a, b) => new Date(b.orderDate).getTime() - new Date(a.orderDate).getTime());
      
      res.json(allOrders);
    } catch (error) {
      console.error("Get reseller orders error:", error);
      res.status(500).json({ error: "Failed to load orders" });
    }
  });

