  app.get("/api/reseller/orders/stats/summary", requireAuth, requireReseller, async (req, res) => {
    try {
      // Get reseller profile to get commission rate
      const reseller = await storage.getReseller(req.reseller!.id);
      const resellerCommissionRate = reseller?.commissionRate ? parseFloat(reseller.commissionRate) / 100 : 0.10;
      
      // Get storefront order stats
      const storefrontStats = await storage.getResellerOrderStats(req.reseller!.id);
      
      // Also get EPOS order stats from main customerOrders table
      const eposOrders = await db.select().from(customerOrders)
        .where(eq(customerOrders.resellerId, req.reseller!.id));
      
      // Calculate EPOS stats using item-level totals for accuracy
      const eposTotalOrders = eposOrders.length;
      let eposTotalRevenue = 0;
      let eposTotalEarnings = 0;
      
      for (const order of eposOrders) {
        const items = await db.select().from(customerOrderItems)
          .where(eq(customerOrderItems.orderId, order.id));
        const vendorProductTotal = items
          .filter(item => item.vendorProductId)
          .reduce((sum, item) => sum + parseFloat(item.totalPrice), 0);
        const catalogProductTotal = items
          .filter(item => !item.vendorProductId)
          .reduce((sum, item) => sum + parseFloat(item.totalPrice), 0);
        
        const orderItemsTotal = vendorProductTotal + catalogProductTotal;
        eposTotalRevenue += orderItemsTotal;
        eposTotalEarnings += vendorProductTotal + (catalogProductTotal * resellerCommissionRate);
      }
      
      const eposPendingOrders = eposOrders.filter(order => 
        order.status === "pending" || order.status === "processing"
      ).length;
      
      // Combine stats
      res.json({
        totalOrders: storefrontStats.totalOrders + eposTotalOrders,
        totalRevenue: (parseFloat(storefrontStats.totalRevenue) + eposTotalRevenue).toFixed(2),
        totalEarnings: (parseFloat(storefrontStats.totalEarnings) + eposTotalEarnings).toFixed(2),
        pendingOrders: storefrontStats.pendingOrders + eposPendingOrders,
        // Breakdowns
        storefrontOrders: storefrontStats.totalOrders,
        eposOrders: eposTotalOrders,
        storefrontRevenue: storefrontStats.totalRevenue,
        eposRevenue: eposTotalRevenue.toFixed(2),
      });
    } catch (error) {
      console.error("Get reseller order stats error:", error);
      res.status(500).json({ error: "Failed to load order stats" });
    }
  });

