  // Admin - Sales by Channel Analytics (for tracking EPOS, website, reseller sales)
  app.get("/api/admin/sales-by-channel", requireAuth, requireAdmin, async (req, res) => {
    try {
      const startDate = req.query.startDate ? new Date(req.query.startDate as string) : undefined;
      const endDate = req.query.endDate ? new Date(req.query.endDate as string) : undefined;

      // Query customer orders grouped by channel
      const channelQuery = db
        .select({
          channel: customerOrders.channel,
          orderCount: sql<number>`count(*)::int`,
          totalRevenue: sql<number>`coalesce(sum(${customerOrders.totalAmount}::numeric), 0)::float`,
          paidOrders: sql<number>`count(case when ${customerOrders.isPaid} = true then 1 end)::int`,
        })
        .from(customerOrders);

      // Apply date filters if provided
      const conditions = [];
      if (startDate) {
        conditions.push(gte(customerOrders.orderDate, startDate));
      }
      if (endDate) {
        conditions.push(lte(customerOrders.orderDate, endDate));
      }

      let query = channelQuery;
      if (conditions.length > 0) {
        query = channelQuery.where(and(...conditions)) as any;
      }

      const results = await query.groupBy(customerOrders.channel);

      // Format results with channel labels
      const channelLabels: Record<string, string> = {
        website: "Main Website",
        customer_epos: "Customer EPOS (In-Store)",
        reseller_epos: "Reseller Storefronts",
        admin: "Admin Created",
        unknown: "Unknown/Legacy Orders",
      };

      const formattedResults = results.map((row) => {
        // Handle NULL channel values explicitly
        const channel = row.channel || "unknown";
        const revenueNumeric = Number(row.totalRevenue || 0);
        return {
          channel,
          channelLabel: channelLabels[channel] || channel,
          orderCount: Number(row.orderCount) || 0,
          totalRevenue: revenueNumeric,
          totalRevenueFormatted: revenueNumeric.toFixed(2),
          paidOrders: Number(row.paidOrders) || 0,
        };
      });

      // Calculate totals
      const totalRevenueNumeric = formattedResults.reduce((sum, r) => sum + r.totalRevenue, 0);
      const totals = {
        totalOrders: formattedResults.reduce((sum, r) => sum + r.orderCount, 0),
        totalRevenue: totalRevenueNumeric,
        totalRevenueFormatted: totalRevenueNumeric.toFixed(2),
        totalPaidOrders: formattedResults.reduce((sum, r) => sum + r.paidOrders, 0),
      };

      res.json({
        channels: formattedResults,
        totals,
        dateRange: {
          startDate: startDate?.toISOString() || null,
          endDate: endDate?.toISOString() || null,
        },
      });
    } catch (error) {
      console.error("Sales by channel analytics error:", error);
      res.status(500).json({ error: "Failed to load channel analytics" });
    }
  });

