  // Get order analytics summary (admin only)
  app.get("/api/admin/orders/summary", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { startDate, endDate } = req.query;
      
      let query = db.select().from(customerOrders);
      
      // Apply date filters if provided
      const conditions: any[] = [];
      if (startDate) {
        conditions.push(sql`${customerOrders.orderDate} >= ${new Date(startDate as string)}`);
      }
      if (endDate) {
        conditions.push(sql`${customerOrders.orderDate} <= ${new Date(endDate as string)}`);
      }
      
      const orders = conditions.length > 0 
        ? await db.select().from(customerOrders).where(and(...conditions))
        : await db.select().from(customerOrders);
      
      // Calculate summary by source (all supported channels)
      const byChannel = {
        website: orders.filter(o => o.channel === 'website' || !o.channel).length,
        customer_epos: orders.filter(o => o.channel === 'customer_epos').length,
        reseller_storefront: orders.filter(o => o.channel === 'reseller_storefront').length,
        reseller_epos: orders.filter(o => o.channel === 'reseller_epos').length,
        vendor_storefront: orders.filter(o => o.channel === 'vendor_storefront').length,
        vendor_epos: orders.filter(o => o.channel === 'vendor_epos').length,
        admin: orders.filter(o => o.channel === 'admin').length,
      };
      
      // Get reseller breakdown
      const resellerOrders = orders.filter(o => o.resellerId);
      const resellerIds = [...new Set(resellerOrders.map(o => o.resellerId))];
      const resellerBreakdown: { resellerId: string; resellerName: string; count: number; revenue: number }[] = [];
      
      for (const resellerId of resellerIds) {
        if (!resellerId) continue;
        const reseller = await db.select().from(resellers).where(eq(resellers.id, resellerId)).limit(1);
        const resellerOrdersFiltered = resellerOrders.filter(o => o.resellerId === resellerId);
        resellerBreakdown.push({
          resellerId,
          resellerName: reseller[0]?.businessName || 'Unknown',
          count: resellerOrdersFiltered.length,
          revenue: resellerOrdersFiltered.reduce((sum, o) => sum + parseFloat(o.totalAmount || '0'), 0),
        });
      }
      
      // Calculate totals
      const totalOrders = orders.length;
      const totalRevenue = orders.reduce((sum, o) => sum + parseFloat(o.totalAmount || '0'), 0);
      const averageOrderValue = totalOrders > 0 ? totalRevenue / totalOrders : 0;
      
      res.json({
        totalOrders,
        totalRevenue,
        averageOrderValue,
        byChannel,
        resellerBreakdown: resellerBreakdown.sort((a, b) => b.count - a.count),
        byStatus: {
          pending: orders.filter(o => o.status === 'pending').length,
          paid: orders.filter(o => o.status === 'paid').length,
          shipped: orders.filter(o => o.status === 'shipped').length,
          delivered: orders.filter(o => o.status === 'delivered').length,
          cancelled: orders.filter(o => o.status === 'cancelled').length,
        }
      });
    } catch (error) {
      console.error("Get order summary error:", error);
      res.status(500).json({ error: "Failed to fetch order summary" });
    }
  });

  // Get all customer orders (admin only) with source info
  app.get("/api/admin/orders", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { startDate, endDate, channel, resellerId } = req.query;
      
      // Build query conditions
      const conditions: any[] = [];
      if (startDate) {
        conditions.push(sql`${customerOrders.orderDate} >= ${new Date(startDate as string)}`);
      }
      if (endDate) {
        conditions.push(sql`${customerOrders.orderDate} <= ${new Date(endDate as string)}`);
      }
      if (channel && channel !== 'all') {
        conditions.push(eq(customerOrders.channel, channel as string));
      }
      if (resellerId && resellerId !== 'all') {
        conditions.push(eq(customerOrders.resellerId, resellerId as string));
      }
      
      // Get all customer orders with items
      const orders = conditions.length > 0
        ? await db.select().from(customerOrders).where(and(...conditions)).orderBy(desc(customerOrders.orderDate))
        : await db.select().from(customerOrders).orderBy(desc(customerOrders.orderDate));
      
      // Get all resellers for name lookup — build dual map covering both
      // reseller profile ID (resellers.id) and auth user ID (resellers.userId)
      // because different code paths store either value as customerOrders.resellerId
      const allResellers = await db.select().from(resellers);
      const resellerMap = new Map<string, string>();
      const resellerAddressMap = new Map<string, string>();
      for (const r of allResellers) {
        if (r.id) {
          resellerMap.set(r.id, r.businessName);
          if (r.businessAddress) resellerAddressMap.set(r.id, r.businessAddress);
        }
        if (r.userId) {
          resellerMap.set(r.userId, r.businessName);
          if (r.businessAddress) resellerAddressMap.set(r.userId, r.businessAddress);
        }
      }

      // Get all users for phone number fallback
      const allUsers = await db.select().from(users);
      const userMap = new Map(allUsers.map(u => [u.id, u.phoneNumber]));

      // Get order items for each order
      const ordersWithItems = await Promise.all(
        orders.map(async (order) => {
          const items = await db
            .select()
            .from(customerOrderItems)
            .where(eq(customerOrderItems.orderId, order.id));

          // Use customerPhone, or fallback to user's phone if order has userId
          const phoneNumber = order.customerPhone || (order.userId ? userMap.get(order.userId) : null) || null;

          return {
            ...order,
            items,
            phoneNumber, // Map customerPhone to phoneNumber for frontend compatibility
            resellerName: order.resellerId ? resellerMap.get(order.resellerId) || null : null,
            resellerBusinessAddress: order.resellerId ? resellerAddressMap.get(order.resellerId) || null : null,
          };
        })
      );

      res.json(ordersWithItems);
    } catch (error) {
      console.error("Get all orders error:", error);
      res.status(500).json({ error: "Failed to fetch orders" });
    }
  });

  // Update order status and tracking (admin only)
  app.patch("/api/admin/orders/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const { status, trackingNumber, notes } = req.body;

      // Get current order to capture previous status for history
      const [currentOrder] = await db.select().from(customerOrders).where(eq(customerOrders.id, id));
      if (!currentOrder) {
        return res.status(404).json({ error: "Order not found" });
      }
      const previousStatus = currentOrder.status;

      const updateData: any = {};
      if (status) updateData.status = status;
      if (trackingNumber !== undefined) updateData.trackingNumber = trackingNumber;
      if (notes !== undefined) updateData.notes = notes;

      // Update timestamp and payment flag based on status
      if (status === "paid") {
        if (!updateData.paidAt) updateData.paidAt = new Date();
        updateData.isPaid = true;
      } else if (status === "pending" || status === "cancelled") {
        updateData.isPaid = false;
      }
      
      if (status === "shipped" && !updateData.shippedAt) {
        updateData.shippedAt = new Date();
      } else if (status === "delivered" && !updateData.deliveredAt) {
        updateData.deliveredAt = new Date();
      }

      const [updatedOrder] = await db
        .update(customerOrders)
        .set(updateData)
        .where(eq(customerOrders.id, id))
        .returning();

      // Record status change in history for audit trail
      if (status && status !== previousStatus) {
        const adminUser = req.user;
        const adminName = adminUser ? `${adminUser.firstName || ''} ${adminUser.lastName || ''}`.trim() || adminUser.email : 'System';
        
        await db.insert(customerOrderStatusHistory).values({
          orderId: id,
          previousStatus: previousStatus as any,
          newStatus: status as any,
          changedBy: adminUser?.id,
          changedByName: adminName,
          notes: notes || `Status updated from ${previousStatus} to ${status}`,
          ipAddress: req.ip || req.headers['x-forwarded-for']?.toString() || null,
        });
        console.log(`📋 Order ${id} status history recorded: ${previousStatus} → ${status} by ${adminName}`);
      }

      if (!updatedOrder) {
        return res.status(404).json({ error: "Order not found" });
      }

      // Send shipping notification email + SMS when status changes to shipped
      if (status === "shipped" && status !== previousStatus) {
        try {
          const trackingNumber = updatedOrder.trackingNumber || undefined;
          const carrier = trackingNumber ? detectCarrier(trackingNumber) : null;
          await sendShippingNotification({
            customerName: `${updatedOrder.customerFirstName} ${updatedOrder.customerLastName}`,
            customerEmail: updatedOrder.customerEmail,
            orderNumber: updatedOrder.orderNumber,
            trackingNumber: trackingNumber,
            carrier: carrier?.name || undefined,
            trackingUrl: carrier?.trackingUrl || undefined,
            estimatedDelivery: undefined,
          });
          console.log(`📧 Shipping notification sent to ${updatedOrder.customerEmail}`);
        } catch (emailError) {
          console.error('Failed to send shipping notification:', emailError);
        }
        const shippedItems = await db.select().from(customerOrderItems).where(eq(customerOrderItems.orderId, updatedOrder.id));
        const shippedItemSummary = summariseOrderItems(shippedItems.map(item => ({ name: item.productName, quantity: item.quantity })));
        smsOrderShipped(
          (updatedOrder as any).customerPhone || null,
          `${updatedOrder.customerFirstName} ${updatedOrder.customerLastName}`,
          updatedOrder.orderNumber,
          shippedItemSummary,
          updatedOrder.trackingNumber || null,
          (message) => {
            db.update(customerOrders).set({ smsLastError: message, smsLastErrorAt: new Date() }).where(eq(customerOrders.id, updatedOrder.id)).catch(e => console.error('Failed to record SMS error:', e));
          }
        );
      }

      // Confirm commissions when order is delivered
      if (status === "delivered") {
        await db.update(commissions)
          .set({ 
            status: 'confirmed',
            updatedAt: new Date(),
          })
          .where(and(
            eq(commissions.orderId, id),
            eq(commissions.status, 'pending')
          ));
        console.log(`✅ Confirmed commissions for order ${id}`);
        
        // Send delivery confirmation email
        try {
          await sendDeliveryConfirmation({
            customerName: `${updatedOrder.customerFirstName} ${updatedOrder.customerLastName}`,
            customerEmail: updatedOrder.customerEmail,
            orderNumber: updatedOrder.orderNumber,
            deliveredAt: updatedOrder.deliveredAt?.toISOString() || new Date().toISOString(),
          });
        } catch (emailError) {
          console.error('Failed to send delivery confirmation email:', emailError);
        }

        // Update partner sales and check for tier upgrade
        const orderTotal = parseFloat(updatedOrder.totalAmount || '0');
        if (!isNaN(orderTotal) && orderTotal > 0) {
          if (updatedOrder.resellerId) {
            try {
              const result = await storage.updatePartnerSalesAndCheckTierUpgrade('reseller', updatedOrder.resellerId, orderTotal);
              if (result.upgraded && result.newTier) {
                console.log(`🎉 Reseller ${updatedOrder.resellerId} upgraded to tier: ${result.newTier.name}`);
              }
            } catch (tierError) {
              console.error('Failed to update reseller tier:', tierError);
            }
          }
        }
      }
      
      // Cancel commissions when order is cancelled
      if (status === "cancelled") {
        await db.update(commissions)
          .set({ 
            status: 'cancelled',
            updatedAt: new Date(),
          })
          .where(and(
            eq(commissions.orderId, id),
            eq(commissions.status, 'pending')
          ));
        console.log(`❌ Cancelled commissions for order ${id}`);
      }

      // Send status update email for ALL status changes (except shipped/delivered which have their own emails)
      if (status && status !== previousStatus && status !== 'shipped' && status !== 'delivered') {
        try {
          const carrier = updatedOrder.trackingNumber ? detectCarrier(updatedOrder.trackingNumber) : null;
          await sendOrderStatusUpdate({
            customerName: `${updatedOrder.customerFirstName} ${updatedOrder.customerLastName}`,
            customerEmail: updatedOrder.customerEmail,
            orderNumber: updatedOrder.orderNumber,
            previousStatus: previousStatus || 'pending',
            newStatus: status,
            trackingNumber: updatedOrder.trackingNumber || undefined,
            trackingUrl: carrier?.trackingUrl || undefined,
          });
          console.log(`📧 Status update email sent to ${updatedOrder.customerEmail} for status: ${status}`);
        } catch (emailError) {
          console.error('Failed to send status update email:', emailError);
        }
      }

      res.json(updatedOrder);
    } catch (error) {
      console.error("Update order error:", error);
      res.status(500).json({ error: "Failed to update order" });
    }
  });

