  // Helper: decode Gmail message body from payload
  function extractGmailBody(payload: any): string {
    if (!payload) return '';
    if (payload.body?.data) {
      try { return Buffer.from(payload.body.data, 'base64').toString('utf-8'); } catch { return ''; }
    }
    if (payload.parts) {
      // Prefer text/plain
      const textPart = payload.parts.find((p: any) => p.mimeType === 'text/plain');
      if (textPart?.body?.data) {
        try { return Buffer.from(textPart.body.data, 'base64').toString('utf-8'); } catch { return ''; }
      }
      // Recurse into nested multipart
      for (const part of payload.parts) {
        if (part.parts) {
          const nested = extractGmailBody(part);
          if (nested) return nested;
        }
      }
      // Fall back to text/html, strip tags
      const htmlPart = payload.parts.find((p: any) => p.mimeType === 'text/html');
      if (htmlPart?.body?.data) {
        try {
          const html = Buffer.from(htmlPart.body.data, 'base64').toString('utf-8');
          return html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        } catch { return ''; }
      }
    }
    return '';
  }

