  // Get email conversation thread including customer Gmail replies (admin only)
  app.get("/api/admin/orders/:id/email-thread", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, id));
      if (!order) return res.status(404).json({ error: "Order not found" });

      let gmailMessages: any[] = [];
      try {
        const { ReplitConnectors } = await import('@replit/connectors-sdk');
        const gmailConnectors = new ReplitConnectors();

        // Search Gmail for all messages referencing this order number
        const q = encodeURIComponent(`"${order.orderNumber}"`);
        const searchResp = await gmailConnectors.proxy('google-mail', `/gmail/v1/users/me/messages?q=${q}&maxResults=20`);

        if (searchResp.ok) {
          const searchData = await searchResp.json() as any;
          const messageIds: string[] = (searchData.messages || []).map((m: any) => m.id);

          if (messageIds.length > 0) {
            const messageDetails = await Promise.all(
              messageIds.slice(0, 15).map(async (msgId: string) => {
                try {
                  const msgResp = await gmailConnectors.proxy('google-mail', `/gmail/v1/users/me/messages/${msgId}?format=full`);
                  if (!msgResp.ok) return null;
                  const msg = await msgResp.json() as any;
                  const headers: any[] = msg.payload?.headers || [];
                  const getHeader = (name: string) => headers.find((h: any) => h.name.toLowerCase() === name.toLowerCase())?.value || '';
                  const labelIds: string[] = msg.labelIds || [];

                  // Only show INBOX (customer inbound) messages — outbound are already in email-log
                  if (!labelIds.includes('INBOX')) return null;

                  const body = extractGmailBody(msg.payload).substring(0, 3000);
                  return {
                    id: msg.id,
                    direction: 'inbound',
                    from: getHeader('From'),
                    to: getHeader('To'),
                    subject: getHeader('Subject'),
                    date: getHeader('Date'),
                    body,
                    snippet: msg.snippet || '',
                  };
                } catch { return null; }
              })
            );
            gmailMessages = messageDetails.filter(Boolean);
          }
        }
      } catch (e: any) {
        console.warn('Gmail thread fetch skipped (non-fatal):', e?.message);
      }

      res.json({ messages: gmailMessages });
    } catch (error: any) {
      console.error('Email thread error:', error);
      res.status(500).json({ error: 'Failed to fetch email thread' });
    }
  });

  // Get SMS conversation for an order (both directions, admin only) — pulled
  // live from Twilio rather than stored locally, since outbound sends were
  // never logged to our own DB (fire-and-forget in sms.ts).
  app.get("/api/admin/orders/:id/sms-thread", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, id));
      if (!order) return res.status(404).json({ error: "Order not found" });

      const sid = process.env.TWILIO_ACCOUNT_SID;
      const token = process.env.TWILIO_AUTH_TOKEN;
      const ourNumber = process.env.TWILIO_FROM_NUMBER;
      if (!sid || !token || !ourNumber) {
        return res.json({ messages: [], configured: false });
      }

      let rawPhone = order.customerPhone;
      if (!rawPhone && order.userId) {
        const [u] = await db.select({ phoneNumber: users.phoneNumber }).from(users).where(eq(users.id, order.userId));
        rawPhone = u?.phoneNumber || null;
      }
      if (!rawPhone) return res.json({ messages: [], configured: true });

      const customerPhone = normalisePhone(rawPhone);
      const auth = Buffer.from(`${sid}:${token}`).toString('base64');
      const fetchDirection = async (params: string) => {
        const resp = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json?${params}&PageSize=50`, {
          headers: { Authorization: `Basic ${auth}` },
        });
        if (!resp.ok) return [];
        const data = await resp.json() as any;
        return (data.messages || []) as any[];
      };

      const [outbound, inbound] = await Promise.all([
        fetchDirection(`From=${encodeURIComponent(ourNumber)}&To=${encodeURIComponent(customerPhone)}`),
        fetchDirection(`From=${encodeURIComponent(customerPhone)}&To=${encodeURIComponent(ourNumber)}`),
      ]);

      const messages = [...outbound, ...inbound]
        .map((m: any) => ({
          direction: m.direction === 'inbound' ? 'inbound' : 'outbound',
          body: m.body,
          status: m.status,
          date: m.date_created,
        }))
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

      res.json({ messages, configured: true, phone: customerPhone });
    } catch (error: any) {
      console.error('SMS thread error:', error);
      res.status(500).json({ error: 'Failed to fetch SMS thread' });
    }
  });

  // Send a custom SMS to the customer on an order (admin only)
  app.post("/api/admin/orders/:id/sms", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const { message } = req.body;
      if (!message || typeof message !== 'string' || !message.trim()) {
        return res.status(400).json({ error: "Message is required" });
      }

      const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, id));
      if (!order) return res.status(404).json({ error: "Order not found" });

      let rawPhone = order.customerPhone;
      if (!rawPhone && order.userId) {
        const [u] = await db.select({ phoneNumber: users.phoneNumber }).from(users).where(eq(users.id, order.userId));
        rawPhone = u?.phoneNumber || null;
      }
      if (!rawPhone) return res.status(400).json({ error: "No phone number on file for this customer" });

      const sent = await sendSMS(rawPhone, message.trim());
      if (!sent) {
        return res.status(502).json({ error: "SMS could not be sent — check Twilio is configured and the number is valid" });
      }

      // Log this send so we can follow up automatically if there's no reply in 24h
      try {
        await db.insert(customerSmsLog).values({
          orderId: order.id,
          customerPhone: normalisePhone(rawPhone),
          customerFirstName: order.customerFirstName,
          body: message.trim(),
        });
      } catch (logError) {
        console.error('Failed to log customer SMS for follow-up tracking:', logError);
      }

      res.json({ success: true });
    } catch (error: any) {
      console.error('Send order SMS error:', error);
      res.status(500).json({ error: 'Failed to send SMS' });
    }
  });

