  // Get all return requests (admin)
  app.get("/api/admin/returns", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { status } = req.query;

      let query = db.select().from(returnRequests);
      
      if (status && status !== 'all') {
        query = query.where(eq(returnRequests.status, status as any)) as any;
      }

      const returns = await query.orderBy(desc(returnRequests.createdAt));

      res.json(returns);
    } catch (error) {
      console.error("Get returns error:", error);
      res.status(500).json({ error: "Failed to fetch returns" });
    }
  });

  // Update return request (admin)
  app.patch("/api/admin/returns/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const { status, adminNotes, returnLabel, totalRefundAmount } = req.body;
      const adminUser = req.user as User;

      const updateData: any = { updatedAt: new Date() };
      
      if (status) updateData.status = status;
      if (adminNotes !== undefined) updateData.adminNotes = adminNotes;
      if (returnLabel !== undefined) updateData.returnLabel = returnLabel;
      if (totalRefundAmount !== undefined) updateData.totalRefundAmount = totalRefundAmount;

      if (status === 'approved' || status === 'rejected') {
        updateData.processedBy = adminUser.id;
        updateData.processedAt = new Date();
      }

      if (status === 'received') {
        updateData.receivedAt = new Date();
      }

      if (status === 'refunded') {
        updateData.refundedAt = new Date();
      }

      const [updated] = await db
        .update(returnRequests)
        .set(updateData)
        .where(eq(returnRequests.id, id))
        .returning();

      if (!updated) {
        return res.status(404).json({ error: "Return request not found" });
      }

      res.json(updated);
    } catch (error) {
      console.error("Update return error:", error);
      res.status(500).json({ error: "Failed to update return request" });
    }
  });

  // ==================== COMMISSION MANAGEMENT ROUTES ====================

  // Get all commissions (admin view)
  app.get("/api/admin/commissions", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { status, commissionType, resellerId, vendorId, startDate, endDate } = req.query;
      
      const conditions: any[] = [];
      if (status && status !== 'all') {
        conditions.push(eq(commissions.status, status as string));
      }
      if (commissionType && commissionType !== 'all') {
        conditions.push(eq(commissions.commissionType, commissionType as any));
      }
      if (resellerId) {
        conditions.push(eq(commissions.resellerId, resellerId as string));
      }
      if (vendorId) {
        conditions.push(eq(commissions.vendorId, vendorId as string));
      }
      if (startDate) {
        conditions.push(sql`${commissions.createdAt} >= ${new Date(startDate as string)}`);
      }
      if (endDate) {
        conditions.push(sql`${commissions.createdAt} <= ${new Date(endDate as string)}`);
      }
      
      const allCommissions = conditions.length > 0
        ? await db.select().from(commissions).where(and(...conditions)).orderBy(desc(commissions.createdAt))
        : await db.select().from(commissions).orderBy(desc(commissions.createdAt));
      
      // Get reseller/vendor names
      const allResellers = await db.select().from(resellers);
      const allVendors = await db.select().from(vendors);
      const resellerMap = new Map(allResellers.map(r => [r.id, r.businessName]));
      const vendorMap = new Map(allVendors.map(v => [v.id, v.businessName]));
      
      const commissionsWithNames = allCommissions.map(c => ({
        ...c,
        partnerName: c.commissionType === 'reseller' 
          ? resellerMap.get(c.resellerId || '') || 'Unknown Reseller'
          : vendorMap.get(c.vendorId || '') || 'Unknown Vendor',
      }));
      
      res.json(commissionsWithNames);
    } catch (error) {
      console.error("Get commissions error:", error);
      res.status(500).json({ error: "Failed to fetch commissions" });
    }
  });

  // Get commission summary (admin view)
  app.get("/api/admin/commissions/summary", requireAuth, requireAdmin, async (req, res) => {
    try {
      const allCommissions = await db.select().from(commissions);
      
      const summary = {
        totalEarned: allCommissions.reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        pending: allCommissions.filter(c => c.status === 'pending').reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        confirmed: allCommissions.filter(c => c.status === 'confirmed').reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        requested: allCommissions.filter(c => c.status === 'requested').reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        approved: allCommissions.filter(c => c.status === 'approved').reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        paid: allCommissions.filter(c => c.status === 'paid').reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        cancelled: allCommissions.filter(c => c.status === 'cancelled').reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        byReseller: allCommissions.filter(c => c.commissionType === 'reseller').reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        byVendor: allCommissions.filter(c => c.commissionType === 'vendor').reduce((sum, c) => sum + parseFloat(c.commissionAmount || '0'), 0),
        totalCount: allCommissions.length,
      };
      
      res.json(summary);
    } catch (error) {
      console.error("Get commission summary error:", error);
      res.status(500).json({ error: "Failed to fetch commission summary" });
    }
  });

  // Get all commission payouts (admin view)
