  app.get("/api/admin/partner-commission-overrides/:partnerType/:partnerId", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { partnerType, partnerId } = req.params;
      
      if (partnerType !== 'reseller' && partnerType !== 'vendor') {
        return res.status(400).json({ error: "Invalid partner type" });
      }
      
      const overrides = await db.select({
        override: partnerCommissionOverrides,
        product: products,
      })
        .from(partnerCommissionOverrides)
        .leftJoin(products, eq(partnerCommissionOverrides.productId, products.id))
        .where(and(
          eq(partnerCommissionOverrides.partnerType, partnerType),
          partnerType === 'reseller' 
            ? eq(partnerCommissionOverrides.resellerId, partnerId)
            : eq(partnerCommissionOverrides.vendorId, partnerId)
        ))
        .orderBy(desc(partnerCommissionOverrides.createdAt));
      
      res.json(overrides);
    } catch (error) {
      console.error("Get commission overrides error:", error);
      res.status(500).json({ error: "Failed to fetch commission overrides" });
    }
  });

  // Create a commission override for a partner
  app.post("/api/admin/partner-commission-overrides", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { partnerType, resellerId, vendorId, productId, commissionRate, storefrontPrice, notes } = req.body;
      
      if (!partnerType || (partnerType !== 'reseller' && partnerType !== 'vendor')) {
        return res.status(400).json({ error: "Invalid partner type" });
      }
      
      if (partnerType === 'reseller' && !resellerId) {
        return res.status(400).json({ error: "Reseller ID required for reseller override" });
      }
      
      if (partnerType === 'vendor' && !vendorId) {
        return res.status(400).json({ error: "Vendor ID required for vendor override" });
      }
      
      if (commissionRate === undefined || commissionRate < 0 || commissionRate > 100) {
        return res.status(400).json({ error: "Commission rate must be between 0 and 100" });
      }
      
      // Check for existing override
      const existingOverride = await db.select()
        .from(partnerCommissionOverrides)
        .where(and(
          eq(partnerCommissionOverrides.partnerType, partnerType),
          partnerType === 'reseller'
            ? eq(partnerCommissionOverrides.resellerId, resellerId)
            : eq(partnerCommissionOverrides.vendorId, vendorId),
          productId 
            ? eq(partnerCommissionOverrides.productId, productId)
            : isNull(partnerCommissionOverrides.productId)
        ))
        .limit(1);
      
      if (existingOverride.length > 0) {
        return res.status(400).json({ 
          error: productId 
            ? "A commission override already exists for this partner and product" 
            : "A global commission override already exists for this partner"
        });
      }
      
      const [override] = await db.insert(partnerCommissionOverrides).values({
        partnerType,
        resellerId: partnerType === 'reseller' ? resellerId : null,
        vendorId: partnerType === 'vendor' ? vendorId : null,
        productId: productId || null,
        commissionRate: commissionRate.toString(),
        storefrontPrice: storefrontPrice ? storefrontPrice.toString() : null,
        notes: notes || null,
        isActive: true,
      }).returning();
      
      res.json(override);
    } catch (error) {
      console.error("Create commission override error:", error);
      res.status(500).json({ error: "Failed to create commission override" });
    }
  });

