  app.post("/api/admin/support-tickets/:id/messages", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const { message } = req.body;

      // Get the ticket to find customer email
      const ticket = await storage.getSupportTicket(id);
      if (!ticket) {
        return res.status(404).json({ error: "Ticket not found" });
      }

      // Get full user details for sender name
      const user = await storage.getUserById(req.user!.id);
      const senderName = user ? `${user.firstName} ${user.lastName}` : req.user!.email;

      const newMessage = await storage.createTicketMessage({
        ticketId: id,
        userId: req.user!.id,
        senderName,
        senderEmail: req.user!.email,
        isStaff: true,
        message,
      });

      // Send email notification to customer
      if (process.env.GMAIL_USER && process.env.GMAIL_APP_PASSWORD) {
        try {
          const nodemailer = await import('nodemailer');
          const transporter = nodemailer.default.createTransport({
            service: 'gmail',
            auth: {
              user: process.env.GMAIL_USER,
              pass: process.env.GMAIL_APP_PASSWORD,
            },
          });

          // Get the portal URL for live chat - always use production domain
          const portalUrl = `https://1strep.com/support/ticket/${ticket.accessToken}`;

          await transporter.sendMail({
            from: `"1stRep Support" <${process.env.GMAIL_USER}>`,
            to: ticket.customerEmail,
            subject: `Re: ${ticket.subject} [${ticket.ticketNumber}]`,
            html: `
              <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                <div style="background: linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%); padding: 20px; text-align: center;">
                  <h1 style="color: white; margin: 0; font-size: 24px;">1stRep Support</h1>
                </div>
                <div style="padding: 30px; background: #f8f9fa;">
                  <p style="color: #333; font-size: 16px;">Hello ${ticket.customerName},</p>
                  <p style="color: #333; font-size: 16px;">We've responded to your support request:</p>
                  <div style="background: white; border-left: 4px solid #2d5a87; padding: 20px; margin: 20px 0; border-radius: 4px;">
                    <p style="color: #333; font-size: 15px; margin: 0; white-space: pre-wrap;">${message}</p>
                  </div>
                  <p style="color: #666; font-size: 14px;">
                    <strong>Ticket Reference:</strong> ${ticket.ticketNumber}<br>
                    <strong>Subject:</strong> ${ticket.subject}
                  </p>
                  <div style="text-align: center; margin: 25px 0;">
                    <a href="${portalUrl}" style="display: inline-block; background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%); color: white; text-decoration: none; padding: 14px 32px; border-radius: 8px; font-weight: 600; font-size: 16px;">Continue Chat Online</a>
                  </div>
                  <p style="color: #666; font-size: 14px; text-align: center;">
                    Click the button above to view your full conversation and reply in real-time.
                  </p>
                  <hr style="border: none; border-top: 1px solid #ddd; margin: 30px 0;">
                  <p style="color: #999; font-size: 12px; text-align: center;">
                    This is an automated message from 1stRep Support.<br>
                    Your secure ticket portal link: <a href="${portalUrl}" style="color: #3b82f6;">${portalUrl}</a>
                  </p>
                </div>
              </div>
            `,
          });
          console.log(`Support ticket response email sent to ${ticket.customerEmail}`);
        } catch (emailError) {
          console.error("Failed to send support ticket response email:", emailError);
          // Continue even if email fails - the message is still saved
        }
      }

      // Emit WebSocket event for real-time updates to customer portal
      // Use ticket-specific room for security (ticket_<ticketId>)
      if ((global as any).io) {
        (global as any).io.to(`ticket_${ticket.id}`).emit('ticket_message', {
          ticketId: ticket.id,
          ticketNumber: ticket.ticketNumber,
          message: newMessage,
        });
      }

      res.json(newMessage);
    } catch (error) {
      console.error("Create ticket message error:", error);
      res.status(500).json({ error: "Failed to create ticket message" });
    }
  });

