  // Customer sends a message via portal (public - by access token)
  app.post("/api/ticket-portal/:token/messages", async (req, res) => {
    try {
      const { token } = req.params;
      const { message } = req.body;

      if (!message?.trim()) {
        return res.status(400).json({ error: "Message is required" });
      }

      const ticket = await storage.getSupportTicketByAccessToken(token);
      
      if (!ticket) {
        return res.status(404).json({ error: "Ticket not found" });
      }

      if (ticket.status === "closed" || ticket.status === "resolved") {
        return res.status(400).json({ error: "Cannot reply to a closed or resolved ticket" });
      }

      // Create the customer's message
      const newMessage = await storage.createTicketMessage({
        ticketId: ticket.id,
        userId: ticket.userId || undefined,
        senderName: ticket.customerName,
        senderEmail: ticket.customerEmail,
        isStaff: false,
        message: message.trim(),
      });

      // Update ticket status to open if it was in_progress (customer replied)
      if (ticket.status === "in_progress") {
        await storage.updateSupportTicket(ticket.id, { status: "open" });
      }

      // Create admin notification for customer reply
      try {
        await storage.createAdminNotification({
          type: 'support_ticket',
          title: 'Customer Reply on Ticket',
          message: `${ticket.ticketNumber}: ${ticket.customerName} replied`,
          link: '/admin/support',
          isRead: false,
        });
      } catch (notifError) {
        console.error('Failed to create notification for customer reply:', notifError);
      }

      // Emit WebSocket event for real-time updates
      // Emit to both admin room and ticket-specific room
      if ((global as any).io) {
        const messageData = {
          ticketId: ticket.id,
          ticketNumber: ticket.ticketNumber,
          message: newMessage,
        };
        (global as any).io.to('admin').emit('ticket_message', messageData);
        (global as any).io.to(`ticket_${ticket.id}`).emit('ticket_message', messageData);
      }

      res.json(newMessage);
    } catch (error) {
      console.error("Customer send message error:", error);
      res.status(500).json({ error: "Failed to send message" });
    }
  });

  // ==================== JOB APPLICATION ROUTES ====================

  // Submit job application (public)
  app.post("/api/job-applications", async (req, res) => {
    try {
      const { 
        applicantName, 
        applicantEmail, 
        applicantPhone, 
        jobTitle, 
        department, 
        location, 
        coverLetter,
        portfolioUrl,
        linkedinUrl
      } = req.body;

      // Validate required fields
      if (!applicantName || !applicantEmail || !applicantPhone || !jobTitle || !coverLetter) {
        return res.status(400).json({ error: "Please fill in all required fields" });
      }

      // Validate email format
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(applicantEmail)) {
        return res.status(400).json({ error: "Please enter a valid email address" });
      }

      // Send job application email
      const result = await sendJobApplication({
        applicantName,
        applicantEmail,
        applicantPhone,
        jobTitle,
        department: department || "General",
        location: location || "Remote",
        coverLetter,
        portfolioUrl,
        linkedinUrl
      });

      if (result.success) {
        console.log(`Job application received from ${applicantName} for ${jobTitle}`);
        res.json({ 
          success: true, 
          message: "Your application has been submitted successfully. We shall review it and get back to you shortly." 
        });
      } else if (result.skipped) {
        // Email service not configured but still acknowledge the application
        console.warn(`Job application from ${applicantName} for ${jobTitle} - email not sent (service not configured)`);
        res.json({ 
          success: true, 
          message: "Your application has been received. We shall review it and get back to you shortly." 
        });
      } else {
        throw new Error("Failed to send application");
      }
    } catch (error) {
      console.error("Job application error:", error);
      res.status(500).json({ error: "Unable to submit your application. Please try again or email us directly at careers@1strep.com" });
    }
  });

