  // Send referral invitation email
  app.post("/api/referrals/invite", requireAuth, async (req, res) => {
    try {
      const { recipientEmail, recipientName, message } = req.body;

      if (!recipientEmail) {
        return res.status(400).json({ error: "Recipient email is required" });
      }

      // Get or create referral code for this user
      let referralCode = await storage.getReferralCode(req.user!.id);
      if (!referralCode) {
        referralCode = await storage.createReferralCode(req.user!.id);
      }

      // Create invitation record
      const invitation = await storage.sendReferralInvitation({
        referralCodeId: referralCode.id,
        senderUserId: req.user!.id,
        recipientEmail,
        recipientName: recipientName || null,
        message: message || null,
        status: 'sent',
      });

      // Get referral program settings for discount info
      let discountValue = '10';
      let discountType = 'percentage';
      try {
        const settings = await storage.getReferralProgramSettings();
        if (settings?.refereeDiscountValue) {
          discountValue = String(settings.refereeDiscountValue);
        }
        if (settings?.refereeDiscountType) {
          discountType = String(settings.refereeDiscountType);
        }
      } catch (settingsErr) {
        console.log("Could not fetch referral settings, using defaults");
      }
      
      // Get sender's name for the email
      const senderName = req.user!.firstName && req.user!.lastName 
        ? `${req.user!.firstName} ${req.user!.lastName}`
        : req.user!.email?.split('@')[0] || 'A friend';

      // Send the referral invitation email
      let emailSent = false;
      try {
        const emailResult = await emailService.sendReferralInvitation({
          senderName,
          recipientEmail,
          recipientName: recipientName || undefined,
          referralCode: referralCode.customCode || referralCode.code,
          message: message || undefined,
          discountValue,
          discountType,
        });
        emailSent = emailResult.success;
      } catch (emailErr) {
        console.error("Failed to send referral email:", emailErr);
        // Continue - invitation was still recorded
      }

      res.json({ 
        success: true, 
        invitation,
        referralCode: referralCode.customCode || referralCode.code,
        emailSent
      });
    } catch (error) {
      console.error("Send referral invitation error:", error);
      res.status(500).json({ error: "Failed to send invitation" });
    }
  });

  // Apply referral code at registration/checkout
  app.post("/api/referrals/apply-code", async (req, res) => {
    try {
      const { code, refereeEmail } = req.body;

      if (!code || !refereeEmail) {
        return res.status(400).json({ error: "Code and email are required" });
      }

      // Check if program is active
      const settings = await storage.getReferralProgramSettings();
      if (!settings?.isActive) {
        return res.status(400).json({ error: "Referral program is not active" });
      }

      // Find the referral code
      const referralCode = await storage.getReferralCodeByCode(code);
      if (!referralCode || !referralCode.isActive) {
        return res.status(404).json({ error: "Invalid referral code" });
      }

      // Check if this email was already referred
      const existingReferral = await storage.getReferralByRefereeEmail(refereeEmail);
      if (existingReferral) {
        return res.status(400).json({ error: "This email has already been referred" });
      }

      // Check if user is trying to refer themselves
      const referrer = await storage.getUser(referralCode.userId);
      if (referrer && referrer.email.toLowerCase() === refereeEmail.toLowerCase()) {
        return res.status(400).json({ error: "You cannot refer yourself" });
      }

      // Create pending referral
      const referral = await storage.createReferral({
        referrerUserId: referralCode.userId,
        refereeEmail: refereeEmail.toLowerCase(),
        referralCodeId: referralCode.id,
        status: 'pending',
        expiresAt: new Date(Date.now() + (settings.rewardExpiryDays || 90) * 24 * 60 * 60 * 1000),
      });

      res.json({
        success: true,
        referralId: referral.id,
        discountType: settings.refereeDiscountType,
        discountValue: parseFloat(settings.refereeDiscountValue),
        minPurchaseAmount: parseFloat(settings.minPurchaseAmount),
      });
    } catch (error) {
      console.error("Apply referral code error:", error);
      res.status(500).json({ error: "Failed to apply referral code" });
    }
  });

