  // Public - Get storefront products (customer-facing)
  app.get("/api/storefronts/:slug/products", async (req, res) => {
    try {
      const { slug } = req.params;
      
      const storefront = await storage.getStorefrontBySlug(slug);
      
      if (!storefront || !storefront.isActive) {
        return res.status(404).json({ error: "Storefront not found" });
      }

      // Get 1stRep catalogue products added to storefront
      const catalogueProducts = await storage.getResellerProductsWithDetails(storefront.resellerId);
      
      // Check if reseller has vendor access (licensing enabled) to include their own products
      const reseller = await storage.getReseller(storefront.resellerId);
      let ownProducts: any[] = [];
      
      if (reseller?.userId) {
        const vendor = await storage.getVendorByUserId(reseller.userId);
        if (vendor && vendor.canAddOwnProducts) {
          // Get vendor's own products (reseller's own products via licensing)
          const vendorProducts = await storage.getVendorProducts(vendor.id);
          ownProducts = vendorProducts
            .filter(p => p.isActive && !p.isDeleted)
            .map(p => ({
              ...p,
              isOwnProduct: true,
              vendorId: vendor.id
            }));
        }
      }
      
      // Map catalogue products to customer-friendly format with custom pricing
      const catalogueProductsFormatted = await Promise.all(catalogueProducts.map(async (rp) => {
        const productId = rp.product?.id;
        
        // Get color-specific images
        const colorImages = productId ? await storage.getProductColorImages(productId) : [];
        const colorImagesMap: Record<string, string> = {};
        const colorHoverImagesMap: Record<string, string> = {};
        const colorAdditionalImagesMap: Record<string, string[]> = {};
        
        // Sort by sortOrder for proper primary/additional distinction
        const sortedColorImgs = [...colorImages].sort((a, b) => a.sortOrder - b.sortOrder);
        
        sortedColorImgs.forEach(img => {
          if (img.color) {
            if (img.isPrimary || img.sortOrder === 0) {
              colorImagesMap[img.color] = img.url;
              if (img.hoverUrl) {
                colorHoverImagesMap[img.color] = img.hoverUrl;
              }
            } else {
              if (!colorAdditionalImagesMap[img.color]) {
                colorAdditionalImagesMap[img.color] = [];
              }
              colorAdditionalImagesMap[img.color].push(img.url);
            }
          }
        });
        
        // Get additional product images (non-color specific)
        const productImages = productId ? await storage.getProductImages(productId) : [];
        const additionalImages = productImages
          .filter(img => !img.isPrimary && !img.color)
          .sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0))
          .map(img => img.url);
        
        return {
          ...rp.product,
          price: rp.product?.partnerStorefrontPrice || rp.product?.retailPrice,
          resellerProductId: rp.id,
          isOwnProduct: false,
          colorImages: colorImagesMap,
          colorHoverImages: colorHoverImagesMap,
          colorAdditionalImages: colorAdditionalImagesMap,
          additionalImages: additionalImages
        };
      }));
      
      // Map reseller's own products (via vendor licensing)
      const ownProductsFormatted = await Promise.all(ownProducts.map(async (p) => {
        // Get color-specific images
        const colorImages = await storage.getProductColorImages(p.id);
        const colorImagesMap: Record<string, string> = {};
        const colorHoverImagesMap: Record<string, string> = {};
        const colorAdditionalImagesMap: Record<string, string[]> = {};
        
        const sortedColorImgs = [...colorImages].sort((a, b) => a.sortOrder - b.sortOrder);
        
        sortedColorImgs.forEach(img => {
          if (img.color) {
            if (img.isPrimary || img.sortOrder === 0) {
              colorImagesMap[img.color] = img.url;
              if (img.hoverUrl) {
                colorHoverImagesMap[img.color] = img.hoverUrl;
              }
            } else {
              if (!colorAdditionalImagesMap[img.color]) {
                colorAdditionalImagesMap[img.color] = [];
              }
              colorAdditionalImagesMap[img.color].push(img.url);
            }
          }
        });
        
        // Get additional product images
        const productImages = await storage.getProductImages(p.id);
        const additionalImages = productImages
          .filter(img => !img.isPrimary && !img.color)
          .sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0))
          .map(img => img.url);
        
        return {
          ...p,
          price: p.retailPrice,
          isOwnProduct: true,
          colorImages: colorImagesMap,
          colorHoverImages: colorHoverImagesMap,
          colorAdditionalImages: colorAdditionalImagesMap,
          additionalImages: additionalImages
        };
      }));

      // Combine catalogue products with reseller's own products (own products first)
      const allProducts = [...ownProductsFormatted, ...catalogueProductsFormatted];
      
      res.json(allProducts);
    } catch (error) {
      console.error("Get storefront products error:", error);
      res.status(500).json({ error: "Failed to load products" });
    }
  });

