  // Reseller - Create storefront
  app.post("/api/reseller/storefront", requireAuth, requireReseller, async (req, res) => {
    try {
      // Check if storefront already exists
      const existing = await storage.getStorefrontByResellerId(req.reseller!.id);
      if (existing) {
        return res.status(400).json({ error: "Storefront already exists" });
      }

      // Validate required fields
      if (!req.body.slug || !req.body.storeName) {
        return res.status(400).json({ 
          error: "Store name and URL slug are required" 
        });
      }

      // Validate slug format (lowercase letters, numbers, hyphens only)
      const slugRegex = /^[a-z0-9-]+$/;
      if (!slugRegex.test(req.body.slug)) {
        return res.status(400).json({ 
          error: "URL slug must contain only lowercase letters, numbers, and hyphens" 
        });
      }

      // Check if slug is already taken
      const slugExists = await storage.getStorefrontBySlug(req.body.slug);
      if (slugExists) {
        return res.status(400).json({ 
          error: "This URL slug is already taken. Please choose a different one." 
        });
      }

      const storefront = await storage.createStorefront({
        ...req.body,
        resellerId: req.reseller!.id
      });

      res.status(201).json(storefront);
    } catch (error: any) {
      console.error("Create storefront error:", error);
      
      // Check for database constraint violations
      if (error.code === '23505') { // PostgreSQL unique violation
        if (error.constraint?.includes('slug')) {
          return res.status(400).json({ error: "This URL slug is already taken" });
        }
        return res.status(400).json({ error: "A storefront with these details already exists" });
      }
      
      res.status(500).json({ 
        error: error.message || "Failed to create storefront. Please check your inputs and try again." 
      });
    }
  });

