  // Reseller - Add product to storefront
  app.post("/api/reseller/storefront/products", requireAuth, requireReseller, async (req, res) => {
    try {
      const resellerId = req.reseller!.id;
      const { productId } = req.body;
      
      const product = await storage.addProductToStorefront({
        ...req.body,
        resellerId,
        isActive: true // Ensure products are active when added to storefront
      });

      // Auto-sync to EPOS: Create inventory entries for all product variants
      if (productId) {
        try {
          const productDetails = await storage.getProduct(productId);
          
          // Only sync active products to EPOS
          if (productDetails && productDetails.isActive !== false) {
            const productVariants = await storage.getProductVariants(productId);
            
            // Use Set to dedupe size/color combinations
            const seenCombinations = new Set<string>();
            const combinationsToCreate: Array<{size?: string, color?: string}> = [];
            
            const addCombination = (size?: string, color?: string) => {
              const key = `${size ?? ''}::${color ?? ''}`;
              if (!seenCombinations.has(key)) {
                seenCombinations.add(key);
                combinationsToCreate.push({ size, color });
              }
            };
            
            if (productVariants.length > 0) {
              // Use actual active variants from database (filter inactive)
              const activeVariants = productVariants.filter(v => v.isActive !== false);
              for (const variant of activeVariants) {
                addCombination(variant.size || undefined, variant.color || undefined);
              }
            } else {
              // No variants exist - create from product sizes/colors arrays
              const sizes = productDetails.sizes && productDetails.sizes.length > 0 
                ? productDetails.sizes 
                : [undefined]; // No size dimension
              const colors = productDetails.colors && productDetails.colors.length > 0 
                ? productDetails.colors 
                : [undefined]; // No color dimension
              
              // Generate cartesian product of sizes and colors
              for (const size of sizes) {
                for (const color of colors) {
                  addCombination(size, color);
                }
              }
            }
            
            // Create inventory entries sequentially to avoid race conditions
            if (combinationsToCreate.length > 0) {
              let created = 0;
              for (const { size, color } of combinationsToCreate) {
                const existingItem = await storage.getInventoryItem(resellerId, productId, size, color);
                if (!existingItem) {
                  await storage.createInventoryItem({
                    resellerId,
                    productId,
                    size,
                    color,
                    quantity: 0,
                    reorderLevel: 5
                  });
                  created++;
                }
              }
              if (created > 0) {
                console.log(`✅ Auto-synced ${created} inventory entries to EPOS for reseller ${resellerId}`);
              }
            }
          }
        } catch (syncError) {
          console.error("EPOS sync warning (non-blocking):", syncError);
          // Don't fail the whole request if sync fails
        }
      }

      res.status(201).json(product);
    } catch (error) {
      console.error("Add product to storefront error:", error);
      res.status(500).json({ error: "Failed to add product" });
    }
  });

