  // Send message to chatbot
  app.post("/api/chatbot/message", async (req, res) => {
    try {
      const { conversationId, message } = req.body;

      if (!conversationId || !message) {
        return res.status(400).json({ error: "Missing required fields" });
      }

      // Save user message
      await storage.saveChatbotMessage({
        conversationId,
        role: "user",
        content: message,
      });

      // Get all previous messages for context
      const messages = await storage.getConversationMessages(conversationId);
      
      // Get active knowledge base
      const knowledge = await storage.getActiveChatbotKnowledge();
      
      // Get recent products for context
      const products = await storage.getProducts();
      const activeProducts = products.filter(p => p.isActive).slice(0, 20);

      // Build context for AI
      const knowledgeContext = knowledge.map(k => 
        `Q: ${k.question}\nA: ${k.answer}`
      ).join('\n\n');

      const productContext = activeProducts.map(p => 
        `Product: ${p.name} (${p.category})\nPrice: £${p.retailPrice}\nDescription: ${p.description || 'N/A'}\nSKU: ${p.sku}`
      ).join('\n\n');

      const systemPrompt = `You are a helpful customer service assistant for 1stRep, a premium UK-based fitness apparel brand. 

Our product catalog includes:
${productContext}

Here is our knowledge base for common questions:
${knowledgeContext}

Guidelines:
- Be friendly, professional, and concise
- Use the knowledge base and product information to answer questions
- If you don't have enough information to answer a question accurately, politely say so and suggest the user fill out a contact form
- Always mention prices in GBP (£)
- For product recommendations, suggest items from our catalog
- For order tracking, shipping, or returns, refer to our policies in the knowledge base

If you cannot answer a question, respond with exactly: "I apologize, but I don't have enough information to answer that question accurately. Would you like to fill out a contact form so our team can assist you further?"`;

      // Check if OpenAI API key is available
      if (!process.env.OPENAI_API_KEY) {
        // Fallback: Enhanced keyword matching
        const userMessage = message.toLowerCase().trim();
        let response = "I apologize, but I don't have enough information to answer that question accurately. Would you like to fill out a contact form so our team can assist you further?";
        let bestMatch: any = null;
        let highestScore = 0;

        // Handle greetings first
        const greetings = ['hi', 'hello', 'hey', 'good morning', 'good afternoon', 'good evening', 'greetings'];
        if (greetings.some(g => userMessage.startsWith(g) || userMessage === g)) {
          response = "Hello! Welcome to 1stRep. I'm here to help you with any questions about our premium fitness apparel, shipping policies, returns, or anything else. What would you like to know?";
        } else {
          // Enhanced keyword matching with scoring
          for (const k of knowledge) {
            if (!k.isActive) continue;
            
            let score = 0;
            const questionLower = k.question.toLowerCase();
            const questionWords = questionLower.split(/\s+/);
            const messageWords = userMessage.split(/\s+/);

            // Exact question match
            if (questionLower === userMessage) {
              score = 1000;
            }
            // Question contains user message
            else if (questionLower.includes(userMessage) && userMessage.length > 5) {
              score = 900;
            }
            // User message contains question
            else if (userMessage.includes(questionLower) && questionLower.length > 5) {
              score = 800;
            }
            // Word-by-word matching
            else {
              for (const word of messageWords) {
                if (word.length < 3) continue; // Skip short words
                if (questionWords.includes(word)) {
                  score += 100;
                }
                if (questionLower.includes(word)) {
                  score += 50;
                }
              }
            }

            // Tag matching
            if (k.tags && k.tags.length > 0) {
              for (const tag of k.tags) {
                const tagLower = tag.toLowerCase();
                if (userMessage.includes(tagLower)) {
                  score += 150;
                }
                if (messageWords.includes(tagLower)) {
                  score += 200;
                }
              }
            }

            // Category boost for matching categories
            if (k.category && userMessage.includes(k.category.toLowerCase())) {
              score += 100;
            }

            // Priority boost
            score += k.priority || 0;

            if (score > highestScore && score >= 100) {
              highestScore = score;
              bestMatch = k;
            }
          }

          if (bestMatch) {
            response = bestMatch.answer;
          }
        }

        // Save bot response
        await storage.saveChatbotMessage({
          conversationId,
          role: "assistant",
          content: response,
        });

        return res.json({ message: response, needsContactForm: response.includes("contact form") });
      }

      // Use OpenAI API
      try {
        const openaiResponse = await fetch('https://api.openai.com/v1/chat/completions', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`,
          },
          body: JSON.stringify({
            model: 'gpt-4o-mini',
            messages: [
              { role: 'system', content: systemPrompt },
              ...messages.map(m => ({ role: m.role, content: m.content })),
            ],
            temperature: 0.7,
            max_tokens: 500,
          }),
        });

        if (!openaiResponse.ok) {
          throw new Error(`OpenAI API error: ${openaiResponse.statusText}`);
        }

        const data = await openaiResponse.json();
        const botMessage = data.choices[0].message.content;

        // Save bot response
        await storage.saveChatbotMessage({
          conversationId,
          role: "assistant",
          content: botMessage,
        });

        const needsContactForm = botMessage.includes("contact form") || botMessage.includes("I don't have enough information");

        res.json({ message: botMessage, needsContactForm });
      } catch (openaiError) {
        console.error("OpenAI API error:", openaiError);
        
        // Fallback response
        const fallbackResponse = "I'm having trouble processing your request right now. Would you like to fill out a contact form so our team can assist you?";
        
        await storage.saveChatbotMessage({
          conversationId,
          role: "assistant",
          content: fallbackResponse,
        });

        res.json({ message: fallbackResponse, needsContactForm: true });
      }
    } catch (error) {
      console.error("Send message error:", error);
      res.status(500).json({ error: "Failed to send message" });
    }
  });

  // Submit unanswered query with contact form - also creates a support ticket
