  // ==================== STRIPE WEBHOOK ====================
  
  // Stripe webhook for payment confirmation
  app.post("/api/stripe/webhook", async (req, res) => {
    if (!stripe) {
      return res.status(503).json({ error: "Stripe not configured" });
    }

    const sig = req.headers['stripe-signature'] as string;
    const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

    if (!webhookSecret) {
      console.warn("STRIPE_WEBHOOK_SECRET not set - webhook verification disabled");
    }

    let event;

    try {
      if (webhookSecret && sig) {
        event = stripe.webhooks.constructEvent(req.body, sig, webhookSecret);
      } else {
        // For development without webhook secret
        event = req.body;
      }
    } catch (err: any) {
      console.error(`Webhook signature verification failed: ${err.message}`);
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    // Handle the event
    switch (event.type) {
      case 'checkout.session.completed':
        const session = event.data.object;
        const orderId = session.metadata?.orderId;
        const orderType = session.metadata?.orderType;

        if (orderId) {
          try {
            // Update order to mark as paid
            await db
              .update(customerOrders)
              .set({
                isPaid: true,
                status: 'processing',
                paidAt: new Date(),
                updatedAt: new Date(),
              })
              .where(eq(customerOrders.id, orderId));

            console.log(`✅ Order ${orderId} marked as paid via Stripe webhook`);

            // Fetch order details for notification
            const [orderDetails] = await db
              .select()
              .from(customerOrders)
              .where(eq(customerOrders.id, orderId))
              .limit(1);

            // Create admin notification for new paid order
            if (orderDetails) {
              try {
                await storage.createAdminNotification({
                  type: 'order',
                  title: 'New Order Payment Received',
                  message: `Order ${orderDetails.orderNumber} has been paid. Amount: £${parseFloat(orderDetails.totalAmount || '0').toFixed(2)}. Customer: ${orderDetails.customerName || 'Guest'}`,
                  priority: 'high',
                  metadata: {
                    orderId: orderId,
                    orderNumber: orderDetails.orderNumber,
                    customerEmail: orderDetails.customerEmail,
                    totalAmount: orderDetails.totalAmount
                  }
                });
                console.log(`🔔 Admin notification created for paid order ${orderDetails.orderNumber}`);
                
                // Emit WebSocket event to notify admin dashboard in real-time
                // Fetch order items for the WebSocket event
                const orderItemsForEvent = await db
                  .select()
                  .from(customerOrderItems)
                  .where(eq(customerOrderItems.orderId, orderId));
                
                emitOrderEvent({
                  type: 'order_updated',
                  orderId: parseInt(orderId) || 0,
                  customerName: orderDetails.customerName || 'Guest',
                  totalAmount: parseFloat(orderDetails.totalAmount || '0'),
                  itemCount: orderItemsForEvent.length,
                  source: 'online',
                  timestamp: new Date().toISOString(),
                  items: orderItemsForEvent.map((item: any) => ({
                    productName: item.productName || 'Product',
                    quantity: item.quantity,
                    size: item.size || '',
                    color: item.color || ''
                  }))
                });
              } catch (notificationError) {
                console.error('Failed to create admin notification:', notificationError);
                // Don't fail the webhook if notification fails
              }
            }

            // Send receipt email to customer
            try {
              if (orderDetails && orderDetails.customerEmail) {
                // Fetch order items
                const orderItems = await db
                  .select()
                  .from(customerOrderItems)
                  .where(eq(customerOrderItems.orderId, orderId));

                // Format items for email
                const emailItems = orderItems.map((item: any) => ({
                  name: `${item.productName || 'Product'} (${item.size || 'N/A'}, ${item.color || 'N/A'})`,
                  quantity: item.quantity,
                  price: parseFloat(item.unitPrice) * item.quantity
                }));

                // Send order confirmation email
                await sendOrderConfirmation({
                  customerName: orderDetails.customerName || 'Customer',
                  customerEmail: orderDetails.customerEmail,
                  customerPhone: orderDetails.phoneNumber || undefined,
                  orderNumber: orderDetails.orderNumber,
                  orderItems: emailItems,
                  totalAmount: parseFloat(orderDetails.totalAmount || '0'),
                  shippingAddress: orderDetails.shippingAddress || ''
                });

                console.log(`📧 Receipt email sent to ${orderDetails.customerEmail} for order ${orderDetails.orderNumber}`);
              }
            } catch (emailError) {
              console.error('Failed to send receipt email:', emailError);
              // Don't fail the webhook if email fails
            }

            // Process vendor transfers for orders containing vendor products
            // This supports split payments to vendors with Stripe Connect
            const vendorTransfers = session.metadata?.vendorTransfers;
            if (vendorTransfers) {
              try {
                const transfers = JSON.parse(vendorTransfers);
                for (const transfer of transfers) {
                  if (transfer.vendorStripeAccountId && transfer.amount > 0) {
                    await stripe!.transfers.create({
                      amount: Math.round(transfer.amount * 100), // Convert to pence
                      currency: 'gbp',
                      destination: transfer.vendorStripeAccountId,
                      transfer_group: `order_${orderId}`,
                      metadata: {
                        orderId,
                        vendorId: transfer.vendorId,
                        vendorName: transfer.vendorName,
                      },
                    });
                    console.log(`✅ Transfer of £${transfer.amount} sent to vendor ${transfer.vendorName} (${transfer.vendorStripeAccountId})`);
                  }
                }
              } catch (transferError) {
                console.error('Failed to process vendor transfers:', transferError);
                // Note: Order is still marked as paid - vendor transfers can be retried manually
              }
            }
            
            // Process referral rewards after successful payment
            const referralId = session.metadata?.referralId;
            if (referralId && orderDetails && !orderDetails.referralProcessed) {
              try {
                // Get referral program settings to determine reward
                const referralSettings = await storage.getReferralProgramSettings();
                if (!referralSettings || !referralSettings.isActive) {
                  console.log(`⚠️ Referral program not active, skipping referral processing`);
                } else {
                  // Ensure order amount is a valid number
                  const orderAmount = Number(parseFloat(orderDetails.totalAmount || '0'));
                  if (isNaN(orderAmount) || orderAmount <= 0) {
                    console.error(`⚠️ Invalid order amount for referral: ${orderDetails.totalAmount}`);
                  } else {
                    // Convert the referral (mark as converted)
                    await storage.convertReferral(referralId, orderId, orderAmount);
                    console.log(`✅ Referral ${referralId} converted for order ${orderDetails.orderNumber}`);
                    
                    const rewardType = referralSettings.referrerRewardType || 'points';
                    const rewardValue = parseFloat(referralSettings.referrerRewardValue || '0');
                    let rewardAmount = 0;
                    
                    if (rewardValue > 0) {
                      if (rewardType === 'percentage') {
                        rewardAmount = orderAmount * (rewardValue / 100);
                      } else if (rewardType === 'fixed') {
                        rewardAmount = rewardValue;
                      } else {
                        // Points reward
                        rewardAmount = rewardValue;
                      }
                      
                      // Reward the referrer
                      await storage.rewardReferrer(referralId, rewardType, rewardAmount);
                      console.log(`✅ Referrer rewarded with ${rewardAmount} ${rewardType} for referral ${referralId}`);
                    } else {
                      console.log(`⚠️ No reward value configured, skipping referrer reward`);
                    }
                    
                    // Mark referral as processed to prevent duplicate rewards
                    await db.update(customerOrders)
                      .set({ referralProcessed: true })
                      .where(eq(customerOrders.id, orderId));
                      
                    console.log(`🎁 Referral program completed for order ${orderDetails.orderNumber}`);
                  }
                }
              } catch (referralError) {
                console.error('Failed to process referral in webhook:', referralError);
                // Don't fail the webhook for referral processing issues
              }
            }
          } catch (error) {
            console.error(`Failed to update order ${orderId}:`, error);
          }
        }
        break;

      case 'payment_intent.succeeded':
        const paymentIntent = event.data.object;
        console.log('PaymentIntent succeeded:', paymentIntent.id);
        break;

      case 'payment_intent.payment_failed':
        const failedPayment = event.data.object;
        console.log('PaymentIntent failed:', failedPayment.id);
        break;

      // Handle Stripe Connect account updates
      case 'account.updated':
        const account = event.data.object;
        const vendorId = account.metadata?.vendorId;
        const resellerId = account.metadata?.resellerId;
        const accountType = account.metadata?.accountType;
        
        if (vendorId && accountType !== 'reseller') {
          try {
            // Update vendor's Stripe Connect status
            await storage.updateVendor(vendorId, {
              stripeChargesEnabled: account.charges_enabled || false,
              stripePayoutsEnabled: account.payouts_enabled || false,
              stripeOnboardingStatus: account.charges_enabled && account.payouts_enabled 
                ? 'complete' 
                : account.details_submitted 
                  ? 'pending_verification' 
                  : 'pending',
            });
            console.log(`✅ Vendor ${vendorId} Stripe Connect status updated: charges=${account.charges_enabled}, payouts=${account.payouts_enabled}`);
          } catch (error) {
            console.error(`Failed to update vendor ${vendorId} Stripe status:`, error);
          }
        }
        
        if (resellerId || accountType === 'reseller') {
          const resellerIdToUpdate = resellerId || account.metadata?.resellerId;
          if (resellerIdToUpdate) {
            try {
              // Update reseller's Stripe Connect status
              await storage.updateReseller(resellerIdToUpdate, {
                stripeChargesEnabled: account.charges_enabled || false,
                stripePayoutsEnabled: account.payouts_enabled || false,
                stripeOnboardingStatus: account.charges_enabled && account.payouts_enabled 
                  ? 'complete' 
                  : account.details_submitted 
                    ? 'pending_verification' 
                    : 'pending',
              });
              console.log(`✅ Reseller ${resellerIdToUpdate} Stripe Connect status updated: charges=${account.charges_enabled}, payouts=${account.payouts_enabled}`);
            } catch (error) {
              console.error(`Failed to update reseller ${resellerIdToUpdate} Stripe status:`, error);
            }
          }
        }
        break;

      default:
        console.log(`Unhandled event type: ${event.type}`);
    }

    res.json({ received: true });
  });

  // ==================== SAVED PAYMENT METHODS ROUTES ====================
  
  // Get all saved payment methods for the current user
  app.get("/api/payment-methods", requireAuth, async (req, res) => {
    try {
      const methods = await storage.getSavedPaymentMethods(req.user!.id);
      res.json(methods);
    } catch (error) {
      console.error("Get payment methods error:", error);
      res.status(500).json({ error: "Failed to retrieve payment methods" });
    }
  });

  // Save a new payment method
  app.post("/api/payment-methods", requireAuth, async (req, res) => {
    try {
      // Guard against missing Stripe configuration
      if (!stripe) {
        return res.status(503).json({ error: "Payment processing is not configured" });
      }

      const { paymentMethodId } = req.body;
      
      if (!paymentMethodId) {
        return res.status(400).json({ error: "Payment method ID is required" });
      }

      // Fetch full user from database
      const user = await storage.getUser(req.user!.id);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      // Check for duplicate payment method
      const existingMethods = await storage.getSavedPaymentMethods(user.id);
      const isDuplicate = existingMethods.some(m => m.stripePaymentMethodId === paymentMethodId);
      if (isDuplicate) {
        return res.status(400).json({ error: "This payment method is already saved" });
      }

      // Retrieve payment method details from Stripe
      const paymentMethod = await stripe.paymentMethods.retrieve(paymentMethodId);
      
      if (paymentMethod.type !== 'card') {
        return res.status(400).json({ error: "Only card payment methods are supported" });
      }

      // Create or retrieve Stripe customer
      let customerId = user.stripeCustomerId;
      
      if (!customerId) {
        const customer = await stripe.customers.create({
          email: user.email,
          name: user.firstName && user.lastName ? `${user.firstName} ${user.lastName}` : undefined,
        });
        customerId = customer.id;
        
        // Update user with Stripe customer ID
        await db.update(users)
          .set({ stripeCustomerId: customerId })
          .where(eq(users.id, user.id));
      }

      // SECURITY: Verify payment method ownership
      if (paymentMethod.customer) {
        // Payment method is already attached to a customer
        if (paymentMethod.customer !== customerId) {
          return res.status(403).json({ error: "This payment method belongs to another customer" });
        }
        // Already attached to the correct customer, no action needed
      } else {
        // Attach payment method to customer
        await stripe.paymentMethods.attach(paymentMethodId, {
          customer: customerId,
        });
      }

      const isFirst = existingMethods.length === 0;

      // Save to database
      const savedMethod = await storage.createSavedPaymentMethod({
        userId: user.id,
        stripePaymentMethodId: paymentMethodId,
        stripeCustomerId: customerId,
        cardBrand: paymentMethod.card!.brand,
        cardLast4: paymentMethod.card!.last4,
        cardExpMonth: paymentMethod.card!.exp_month,
        cardExpYear: paymentMethod.card!.exp_year,
        isDefault: isFirst, // Set as default if it's the first one
      });

      res.json(savedMethod);
    } catch (error) {
      console.error("Save payment method error:", error);
      res.status(500).json({ error: "Failed to save payment method" });
    }
  });

  // Delete a saved payment method
  app.delete("/api/payment-methods/:id", requireAuth, async (req, res) => {
    try {
      const method = await storage.getSavedPaymentMethod(req.params.id);
      
      if (!method) {
        return res.status(404).json({ error: "Payment method not found" });
      }
      
      if (method.userId !== req.user!.id) {
        return res.status(403).json({ error: "Unauthorized" });
      }

      // Detach from Stripe
      try {
        await stripe!.paymentMethods.detach(method.stripePaymentMethodId);
      } catch (stripeError) {
        console.warn("Stripe detach failed (may already be detached):", stripeError);
      }

      // Delete from database
      await storage.deleteSavedPaymentMethod(req.params.id);

      res.json({ success: true });
    } catch (error) {
      console.error("Delete payment method error:", error);
      res.status(500).json({ error: "Failed to delete payment method" });
    }
  });

