  app.get("/public-objects/:filePath(*)", async (req, res) => {
    if (!ObjectStorageService.isConfigured()) {
      return res.status(503).json({ error: "Object storage not configured" });
    }
    const filePath = req.params.filePath;
    const width = req.query.w ? parseInt(req.query.w as string) : null;

    try {
      const objectStorageService = new ObjectStorageService();
      const cacheTtl = 604800; // 1 week

      // If resize requested, get raw buffer first then resize
      if (width && width > 0 && width <= 2000) {
        const obj = await objectStorageService.getPublicBuffer(filePath);
        if (!obj) return res.status(404).json({ error: "File not found" });

        if (obj.contentType.startsWith("image/") && !obj.contentType.includes("svg")) {
          try {
            const resized = await sharp(obj.buffer)
              .resize(width, null, { fit: "inside", withoutEnlargement: true })
              .jpeg({ quality: 80, progressive: true })
              .toBuffer();
            res.set({
              "Content-Type": "image/jpeg",
              "Content-Length": resized.length.toString(),
              "Cache-Control": `public, max-age=${cacheTtl}, immutable`,
            });
            return res.send(resized);
          } catch (resizeErr) {
            console.error("Image resize error, serving original:", resizeErr);
          }
        }

        // Serve original buffer (resize failed or non-resizable type)
        res.set({
          "Content-Type": obj.contentType,
          "Content-Length": String(obj.buffer.length),
          "Cache-Control": `public, max-age=${cacheTtl}, immutable`,
        });
        return res.send(obj.buffer);
      }

      // Stream directly (no resize)
      const served = await objectStorageService.servePublicObject(filePath, res, cacheTtl);
      if (!served) return res.status(404).json({ error: "File not found" });
    } catch (error: any) {
      console.error("Error serving public object:", error);
      if (error.message?.includes("not set")) {
        return res.status(503).json({ error: "Object storage not configured" });
      }
      return res.status(500).json({ error: "Internal server error" });
    }
  });

