  app.post("/api/admin/validate-image", requireAuth, requireAdmin, upload.single('image'), async (req, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ error: "No image file provided" });
      }

      const { imageType } = req.body;
      
      if (!imageType || !imageSpecs[imageType as ImageSpecType]) {
        return res.status(400).json({ error: "Invalid image type" });
      }

      const spec = imageSpecs[imageType as ImageSpecType];
      const result: ValidationResult = {
        valid: true,
        errors: [],
        warnings: [],
        metadata: {
          originalWidth: 0,
          originalHeight: 0,
          originalSize: req.file.size,
          format: '',
          aspectRatio: ''
        }
      };

      // For SVG files, skip dimension validation
      if (req.file.mimetype === 'image/svg+xml') {
        result.metadata.format = 'svg';
        result.metadata.aspectRatio = 'flexible';
        
        // Check file size
        if (req.file.size > spec.maxFileSize) {
          result.errors.push(`File size (${Math.round(req.file.size / 1024)}KB) exceeds maximum (${Math.round(spec.maxFileSize / 1024)}KB)`);
          result.valid = false;
        }

        return res.json(result);
      }

      // Get image metadata using Sharp
      const metadata = await sharp(req.file.buffer).metadata();
      
      result.metadata.originalWidth = metadata.width || 0;
      result.metadata.originalHeight = metadata.height || 0;
      result.metadata.format = metadata.format || '';
      result.metadata.aspectRatio = calculateAspectRatio(
        metadata.width || 0,
        metadata.height || 0
      );

      // Validate dimensions
      if (metadata.width && metadata.height) {
        const dimensionValidation = validateImageDimensions(
          metadata.width,
          metadata.height,
          spec
        );

        if (!dimensionValidation.valid) {
          result.errors.push(dimensionValidation.message || 'Invalid dimensions');
          result.valid = false;

          // Add suggestions for fixing dimension issues
          if (dimensionValidation.isOversized) {
            result.suggestions = {
              ...result.suggestions,
              shouldResize: true,
              targetWidth: spec.width,
              targetHeight: spec.height
            };
          } else if (dimensionValidation.isUndersized) {
            // For undersized images, suggest they need a higher quality source
            result.suggestions = {
              ...result.suggestions,
              shouldResize: false // Can't upscale quality
            };
          }
        } else {
          // Image is valid but check if it's moderately larger than spec (not error, but worth optimizing)
          if (metadata.width > spec.width * 1.5 || metadata.height > spec.height * 1.5) {
            result.warnings.push(
              `Image is larger than recommended (${metadata.width}×${metadata.height}px vs ${spec.width}×${spec.height}px). Consider optimizing for faster loading.`
            );
            result.suggestions = {
              ...result.suggestions,
              shouldResize: true,
              shouldCompress: true,
              targetWidth: spec.width,
              targetHeight: spec.height
            };
          }
        }
      }

      // Validate file size
      if (req.file.size > spec.maxFileSize) {
        result.errors.push(
          `File size (${Math.round(req.file.size / 1024)}KB) exceeds maximum (${Math.round(spec.maxFileSize / 1024)}KB)`
        );
        result.suggestions = {
          ...result.suggestions,
          shouldCompress: true,
          shouldResize: result.suggestions?.shouldResize || false
        };
        result.valid = false;
      } else if (req.file.size > spec.maxFileSize * 0.8) {
        result.warnings.push(
          `File size is near the maximum. Consider compressing for better performance.`
        );
        result.suggestions = {
          ...result.suggestions,
          shouldCompress: true,
          shouldResize: result.suggestions?.shouldResize || false
        };
      }

      // Validate format
      const fileExt = metadata.format || path.extname(req.file.originalname).slice(1).toLowerCase();
      if (!spec.formats.includes(fileExt)) {
        result.errors.push(
          `Invalid format. Allowed: ${spec.formats.join(', ')}, Got: ${fileExt}`
        );
        result.valid = false;
      }

      res.json(result);
    } catch (error) {
      console.error("Image validation error:", error);
      res.status(500).json({ error: "Failed to validate image" });
    }
  });

  // Compress and optimize image
  app.post("/api/admin/compress-image", requireAuth, requireAdmin, upload.single('image'), async (req, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ error: "No image file provided" });
      }

      const { imageType, quality = 85 } = req.body;
      
      if (!imageType || !imageSpecs[imageType as ImageSpecType]) {
        return res.status(400).json({ error: "Invalid image type" });
      }

      const spec = imageSpecs[imageType as ImageSpecType];

      // For SVG, return as-is
      if (req.file.mimetype === 'image/svg+xml') {
        res.set({
          'Content-Type': 'image/svg+xml',
          'Content-Disposition': `attachment; filename="optimized-${req.file.originalname}"`,
          'X-Original-Size': req.file.size.toString(),
          'X-Compressed-Size': req.file.size.toString(),
          'X-Compression-Ratio': '0'
        });
        return res.send(req.file.buffer);
      }

      // Get metadata
      const metadata = await sharp(req.file.buffer).metadata();
      
      // Determine target dimensions
      let targetWidth = spec.width;
      let targetHeight = spec.height;

      // If image is larger than spec, resize it
      if (metadata.width && metadata.height) {
        if (metadata.width > spec.width || metadata.height > spec.height) {
          // Maintain aspect ratio while fitting within spec
          const widthRatio = spec.width / metadata.width;
          const heightRatio = spec.height / metadata.height;
          const ratio = Math.min(widthRatio, heightRatio);
          
          targetWidth = Math.round(metadata.width * ratio);
          targetHeight = Math.round(metadata.height * ratio);
        } else {
          // Keep original size if smaller
          targetWidth = metadata.width;
          targetHeight = metadata.height;
        }
      }

      // Process image
      let processedImage = sharp(req.file.buffer)
        .resize(targetWidth, targetHeight, {
          fit: 'inside',
          withoutEnlargement: true
        });

      // Determine output format and apply compression
      let outputBuffer: Buffer;
      let outputMimeType: string;
      let outputExt: string;

      if (spec.formats.includes('webp')) {
        // Prefer WebP for best compression
        outputBuffer = await processedImage
          .webp({ quality: parseInt(quality as string) })
          .toBuffer();
        outputMimeType = 'image/webp';
        outputExt = 'webp';
      } else if (spec.formats.includes('jpg') || spec.formats.includes('jpeg')) {
        outputBuffer = await processedImage
          .jpeg({ quality: parseInt(quality as string), progressive: true })
          .toBuffer();
        outputMimeType = 'image/jpeg';
        outputExt = 'jpg';
      } else if (spec.formats.includes('png')) {
        outputBuffer = await processedImage
          .png({ compressionLevel: 9 })
          .toBuffer();
        outputMimeType = 'image/png';
        outputExt = 'png';
      } else {
        throw new Error('No supported output format');
      }

      // Calculate compression ratio
      const compressionRatio = ((req.file.size - outputBuffer.length) / req.file.size * 100).toFixed(1);

      // Generate filename
      const originalName = path.parse(req.file.originalname).name;
      const filename = `${originalName}-optimized.${outputExt}`;

      res.set({
        'Content-Type': outputMimeType,
        'Content-Disposition': `attachment; filename="${filename}"`,
        'X-Original-Size': req.file.size.toString(),
        'X-Compressed-Size': outputBuffer.length.toString(),
        'X-Compression-Ratio': compressionRatio,
        'X-Original-Dimensions': `${metadata.width}x${metadata.height}`,
        'X-Output-Dimensions': `${targetWidth}x${targetHeight}`
      });

      res.send(outputBuffer);
    } catch (error) {
      console.error("Image compression error:", error);
      res.status(500).json({ error: "Failed to compress image" });
    }
  });

