  // Stripe Terminal - Capture payment for card reader
  // This creates a PaymentIntent specifically configured for Terminal
  // SECURED: Requires authentication and admin/reseller authorization
  app.post("/api/stripe-terminal/create-payment-intent", requireAuth, async (req, res) => {
    try {
      if (!stripe) {
        return res.status(503).json({ error: "Stripe not configured" });
      }

      // Verify user is authorized for Terminal operations
      if (!(await isAuthorizedForTerminal(req.user!.id))) {
        return res.status(403).json({ error: "Not authorized for Terminal operations" });
      }

      const { items, currency = 'gbp' } = req.body;

      if (!items || items.length === 0) {
        return res.status(400).json({ error: "No items provided" });
      }

      // Calculate total from authoritative database prices
      let serverCalculatedAmount = 0;
      for (const item of items) {
        const product = await storage.getProduct(item.productId);
        if (!product) {
          return res.status(400).json({ error: `Product ${item.productId} not found` });
        }
        const price = parseFloat(product.retailPrice);
        serverCalculatedAmount += price * item.quantity;
      }

      // Round to 2 decimal places and convert to pence
      const amountInPence = Math.round(serverCalculatedAmount * 100);

      // Create PaymentIntent for Terminal (must use card_present)
      const paymentIntent = await stripe.paymentIntents.create({
        amount: amountInPence,
        currency,
        payment_method_types: ['card_present'],
        statement_descriptor_suffix: '1STREP EPOS',
        capture_method: 'automatic',
        metadata: {
          source: 'epos_terminal',
          items: JSON.stringify(items.map((i: any) => ({ id: i.productId, qty: i.quantity }))),
        },
      });

      res.json({
        clientSecret: paymentIntent.client_secret,
        paymentIntentId: paymentIntent.id,
        serverCalculatedAmount,
      });
    } catch (error: any) {
      console.error("Stripe Terminal create payment intent error:", error);
      res.status(500).json({ error: error.message || "Failed to create payment intent" });
    }
  });

  // Stripe Terminal - Capture a payment after card is read
  // SECURED: Requires authentication and admin/reseller authorization
  app.post("/api/stripe-terminal/capture-payment", requireAuth, async (req, res) => {
    try {
      if (!stripe) {
        return res.status(503).json({ error: "Stripe not configured" });
      }

      // Verify user is authorized for Terminal operations
      if (!(await isAuthorizedForTerminal(req.user!.id))) {
        return res.status(403).json({ error: "Not authorized for Terminal operations" });
      }

      const { paymentIntentId } = req.body;

      if (!effectivePaymentId) {
        return res.status(400).json({ error: "PaymentIntent ID required" });
      }

      // Capture the payment
      const paymentIntent = await stripe.paymentIntents.capture(paymentIntentId);

      res.json({
        status: paymentIntent.status,
        paymentIntentId: paymentIntent.id,
      });
    } catch (error: any) {
      console.error("Stripe Terminal capture payment error:", error);
      res.status(500).json({ error: error.message || "Failed to capture payment" });
    }
  });

