  // Create QR payment session - generates Stripe Checkout URL for QR code display
  app.post("/api/epos/qr-payment/create", requireAuth, async (req, res) => {
    try {
      if (!stripe) {
        return res.status(503).json({ error: "Stripe not configured" });
      }

      const { items, customerEmail, channel = 'epos', resellerId } = req.body;

      if (!items || !Array.isArray(items) || items.length === 0) {
        return res.status(400).json({ error: "Items array is required" });
      }

      // Calculate total from items with server-side price verification
      let totalAmount = 0;
      const lineItems: any[] = [];

      for (const item of items) {
        // Verify product exists and get current price
        const product = await storage.getProduct(item.productId);
        if (!product) {
          return res.status(400).json({ error: `Product not found: ${item.productId}` });
        }

        const unitPrice = parseFloat(product.retailPrice);
        const quantity = item.quantity || 1;
        totalAmount += unitPrice * quantity;

        lineItems.push({
          price_data: {
            currency: 'gbp',
            product_data: {
              name: product.name,
              description: item.size ? `Size: ${item.size}${item.color ? `, Colour: ${item.color}` : ''}` : undefined,
            },
            unit_amount: Math.round(unitPrice * 100), // Convert to pence
          },
          quantity: quantity,
        });
      }

      // Generate a unique session ID for tracking
      const qrSessionId = `qr_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;

      // Build the base URL
      const baseUrl = req.headers.origin || `https://${req.headers.host}`;

      // Create Stripe Checkout Session
      const session = await stripe.checkout.sessions.create({
        payment_method_types: ['card'],
        line_items: lineItems,
        mode: 'payment',
        success_url: `${baseUrl}/epos/qr-payment/success?session_id={CHECKOUT_SESSION_ID}&qr_session=${qrSessionId}`,
        cancel_url: `${baseUrl}/epos/qr-payment/cancel?qr_session=${qrSessionId}`,
        customer_email: customerEmail || undefined,
        metadata: {
          qrSessionId,
          channel,
          resellerId: resellerId || '',
          userId: req.user?.id?.toString() || '',
        },
        expires_at: Math.floor(Date.now() / 1000) + 1800, // 30 minutes
      });

      // Store QR session info for polling
      const qrSessionData = {
        qrSessionId,
        checkoutSessionId: session.id,
        status: 'pending',
        amount: totalAmount,
        createdAt: new Date().toISOString(),
        items,
      };

      // Store in memory for quick lookup (in production, use Redis or database)
      if (!(global as any).qrPaymentSessions) {
        (global as any).qrPaymentSessions = new Map();
      }
      (global as any).qrPaymentSessions.set(qrSessionId, qrSessionData);

      // Clean up old sessions after 1 hour
      setTimeout(() => {
        (global as any).qrPaymentSessions?.delete(qrSessionId);
      }, 3600000);

      res.json({
        qrSessionId,
        checkoutUrl: session.url,
        expiresAt: new Date(Date.now() + 1800000).toISOString(), // 30 minutes
        amount: totalAmount,
      });
    } catch (error: any) {
      console.error("QR payment session creation error:", error);
      res.status(500).json({ error: error.message || "Failed to create QR payment session" });
    }
  });

  // Check QR payment status - for polling from EPOS
  app.get("/api/epos/qr-payment/status/:qrSessionId", requireAuth, async (req, res) => {
    try {
      if (!stripe) {
        return res.status(503).json({ error: "Stripe not configured" });
      }

      const { qrSessionId } = req.params;

      if (!(global as any).qrPaymentSessions) {
        return res.status(404).json({ error: "Session not found", status: 'not_found' });
      }

      const qrSession = (global as any).qrPaymentSessions.get(qrSessionId);
      if (!qrSession) {
        return res.status(404).json({ error: "Session not found", status: 'not_found' });
      }

      // Check Stripe session status
      const checkoutSession = await stripe.checkout.sessions.retrieve(qrSession.checkoutSessionId);

      let status = 'pending';
      if (checkoutSession.payment_status === 'paid') {
        status = 'paid';
        qrSession.status = 'paid';
        qrSession.paymentIntentId = checkoutSession.payment_intent as string;
      } else if (checkoutSession.status === 'expired') {
        status = 'expired';
        qrSession.status = 'expired';
      }

      res.json({
        qrSessionId,
        status,
        paymentIntentId: qrSession.paymentIntentId || null,
        amount: qrSession.amount,
      });
    } catch (error: any) {
      console.error("QR payment status check error:", error);
      res.status(500).json({ error: error.message || "Failed to check payment status" });
    }
  });

