  // Member lookup for EPOS card scanning - lookup customer by email or user ID
  // Requires admin or reseller authentication to prevent unauthorized access
  app.get("/api/epos/member-lookup", requireAuth, async (req, res) => {
    try {
      // Verify user has admin or reseller role
      if (!req.user) {
        return res.status(401).json({ error: "Authentication required" });
      }
      
      // Check if user is admin or reseller (authorized for EPOS operations)
      const adminUser = await storage.getUser(req.user.id);
      const resellerRecord = await db.query.resellers.findFirst({
        where: eq(resellers.userId, req.user.id),
      });
      
      const isAdmin = adminUser?.isAdmin === true;
      const isReseller = !!resellerRecord && resellerRecord.approvalStatus === 'approved';
      
      if (!isAdmin && !isReseller) {
        return res.status(403).json({ error: "Not authorized for member lookup" });
      }
      
      const query = (req.query.query as string)?.trim();
      if (!query || query.length < 3) {
        return res.status(400).json({ error: "Query must be at least 3 characters" });
      }

      // Validate query format (email, UUID-like ID, or loyalty card barcode)
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      const loyaltyCardRegex = /^LOYAL-([A-Z0-9]{8})$/i;
      
      // Check if it's a loyalty card barcode
      const loyaltyMatch = query.match(loyaltyCardRegex);
      let searchQuery = query;
      
      if (loyaltyMatch) {
        // Extract the partial user ID from loyalty card barcode and search by prefix
        const partialId = loyaltyMatch[1].toLowerCase();
        // We need to search for users whose ID starts with this prefix
        const allUsers = await db.query.users.findMany();
        const matchingUser = allUsers.find(u => u.id.toLowerCase().startsWith(partialId));
        
        if (matchingUser) {
          searchQuery = matchingUser.id;
        } else {
          return res.json({ member: null });
        }
      } else if (!emailRegex.test(query) && !uuidRegex.test(query)) {
        return res.status(400).json({ error: "Invalid query format - use email, member ID, or scan loyalty card" });
      }

      // Search for user by email or user ID
      const user = await db.query.users.findFirst({
        where: or(
          eq(users.email, searchQuery.toLowerCase()),
          eq(users.id, searchQuery)
        ),
      });

      if (!user) {
        return res.json({ member: null });
      }

      // Get loyalty points for this user
      const loyaltyData = await db.query.loyaltyPoints.findFirst({
        where: eq(loyaltyPoints.userId, user.id),
      });

      // Return limited data - only what's needed for EPOS checkout
      const member = {
        id: user.id,
        email: user.email,
        firstName: user.firstName || "",
        lastName: user.lastName || "",
        tier: loyaltyData?.tier || "bronze",
        currentPoints: loyaltyData?.currentPoints || 0,
      };

      res.json({ member });
    } catch (error) {
      console.error("EPOS member lookup error:", error);
      res.status(500).json({ error: "Failed to lookup member" });
    }
  });

  // ==================== RESELLER STOREFRONT EPOS CHECKOUT ====================
  // Allows customers to purchase from reseller storefronts with proper attribution
  app.post("/api/reseller-storefront/checkout", async (req, res) => {
    try {
      const { 
        storefrontSlug, 
        resellerId, 
        items, 
        customerEmail, 
        paymentMethod,
        deliveryMethod,
        collectionStoreId,
        collectionStoreName,
        couponCode,
        couponId,
        discountAmount
      } = req.body;

      if (!items || items.length === 0) {
        return res.status(400).json({ error: "Cart cannot be empty" });
      }

      if (!storefrontSlug || !resellerId) {
        return res.status(400).json({ error: "Storefront information required" });
      }

      // Get storefront and reseller info
      const storefront = await db.query.storefronts.findFirst({
        where: eq(storefronts.slug, storefrontSlug),
        with: { reseller: true }
      });

      if (!storefront) {
        return res.status(404).json({ error: "Storefront not found" });
      }

      // Verify storefront belongs to reseller
      if (storefront.resellerId !== resellerId) {
        return res.status(403).json({ error: "Unauthorized storefront access" });
      }

      // SERVER-SIDE VALIDATION: Validate quantities and look up actual prices from database
      const validatedItems = [];
      let serverSubtotal = 0;

      for (const item of items) {
        // Validate quantity is a positive integer
        const quantity = parseInt(item.quantity, 10);
        if (!Number.isInteger(quantity) || quantity <= 0) {
          return res.status(400).json({ 
            error: `Invalid quantity for product. Quantity must be a positive number.` 
          });
        }

        // Get the reseller product to validate the price and ownership
        const resellerProduct = await db.query.resellerProducts.findFirst({
          where: and(
            eq(resellerProducts.id, item.resellerProductId),
            eq(resellerProducts.resellerId, resellerId)
          ),
          with: { product: true }
        });

        if (!resellerProduct) {
          return res.status(400).json({ 
            error: `Product not found or not available at this storefront` 
          });
        }

        // Use the server-side price (admin-set partner storefront price or original retail price)
        const serverPrice = resellerProduct.product?.partnerStorefrontPrice || resellerProduct.product?.retailPrice;
        if (!serverPrice) {
          return res.status(400).json({ 
            error: `Price not available for product` 
          });
        }

        // Use server-trusted product name from database
        const productName = resellerProduct.product?.name || "Product";
        const itemPrice = parseFloat(serverPrice);
        const itemTotal = itemPrice * quantity;
        serverSubtotal += itemTotal;

        validatedItems.push({
          resellerProductId: item.resellerProductId,
          productId: resellerProduct.productId,
          name: productName,
          size: item.size || null,
          color: item.color || null,
          quantity: quantity,
          unitPrice: serverPrice,
          totalPrice: itemTotal.toFixed(2),
        });
      }

      // Calculate VAT (20%) on server
      // Validate and apply coupon discount if provided
      let validatedDiscount = 0;
      let validatedCouponId = null;
      let validatedCouponCode = null;
      
      if (couponCode) {
        // Verify the coupon belongs to this reseller and is valid
        // Support both couponCode+couponId and couponCode alone
        const couponQuery = couponId 
          ? and(
              eq(b2bPartnerCoupons.id, couponId),
              eq(b2bPartnerCoupons.code, couponCode.toUpperCase()),
              eq(b2bPartnerCoupons.partnerId, resellerId),
              eq(b2bPartnerCoupons.isActive, true)
            )
          : and(
              eq(b2bPartnerCoupons.code, couponCode.toUpperCase()),
              eq(b2bPartnerCoupons.partnerId, resellerId),
              eq(b2bPartnerCoupons.isActive, true)
            );
        
        const [coupon] = await db.select().from(b2bPartnerCoupons).where(couponQuery);
        
        if (coupon) {
          // Check expiry
          const now = new Date();
          const isExpired = coupon.expiresAt && new Date(coupon.expiresAt) < now;
          const hasStarted = !coupon.startsAt || new Date(coupon.startsAt) <= now;
          const withinUsageLimit = !coupon.usageLimit || (coupon.usageCount || 0) < coupon.usageLimit;
          
          const meetsMinOrder = !coupon.minOrderValue || serverSubtotal >= parseFloat(coupon.minOrderValue);
          
          if (!isExpired && hasStarted && withinUsageLimit && meetsMinOrder) {
            // Calculate discount
            if (coupon.discountType === 'percentage') {
              validatedDiscount = serverSubtotal * (parseFloat(coupon.discountValue || '0') / 100);
            } else {
              validatedDiscount = parseFloat(coupon.discountValue || '0');
            }
            
            // Apply max discount cap if set
            if (coupon.maxDiscount && validatedDiscount > parseFloat(coupon.maxDiscount)) {
              validatedDiscount = parseFloat(coupon.maxDiscount);
            }
            
            validatedCouponId = coupon.id;
            validatedCouponCode = coupon.code;
            console.log('🎟️ Storefront coupon validated:', couponCode, 'discount:', validatedDiscount);
          }
        }
      }
      
      const serverTax = serverSubtotal * 0.2;
      const serverTotalBeforeDiscount = serverSubtotal + serverTax;
      const serverTotal = Math.max(0, serverTotalBeforeDiscount - validatedDiscount);

      // Create order number with reseller prefix
      const orderNumber = `RS-${Date.now()}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

      // Create customer order in database with reseller attribution
      const [createdOrder] = await db.insert(customerOrders).values({
        orderNumber,
        customerEmail: customerEmail || "walk-in@customer.com",
        customerFirstName: "Storefront",
        customerLastName: "Customer",
        shippingAddress: "In-Store Pickup",
        shippingCity: storefront.reseller?.businessName || "Store",
        shippingPostalCode: "N/A",
        shippingCountry: "UK",
        subtotal: serverSubtotal.toFixed(2),
        shippingCost: "0.00",
        taxAmount: serverTax.toFixed(2),
        totalAmount: serverTotal.toFixed(2),
        status: paymentMethod === "card" ? "pending" : "processing",
        paymentMethod: paymentMethod === "card" ? "card" : "cash",
        isPaid: paymentMethod === "cash",
        paidAt: paymentMethod === "cash" ? new Date() : null,
        notes: `Reseller Storefront Purchase - ${storefront.storeName} (Reseller ID: ${resellerId})`,
        channel: "reseller_epos",
        resellerId: resellerId,
      }).returning();

      // Add order items with validated prices
      for (const item of validatedItems) {
        await db.insert(customerOrderItems).values({
          orderId: createdOrder.id,
          productId: item.productId,
          productName: item.name || "Product",
          quantity: item.quantity,
          unitPrice: item.unitPrice.toString(),
          totalPrice: item.totalPrice,
          size: item.size || null,
          color: item.color || null,
        });
      }

      // Create Stripe checkout session if card payment
      // Use Square for card payments (primary payment processor)
      if (paymentMethod === "card") {
        const baseUrl = getProductionBaseUrl();
        
        try {
          // Import Square client (using the same SDK as squareRoutes.ts)
          const { SquareClient, SquareEnvironment } = await import('square');
          
          const accessToken = process.env.SQUARE_ACCESS_TOKEN;
          const locationId = process.env.SQUARE_LOCATION_ID;
          
          if (!accessToken || !locationId) {
            throw new Error('Square credentials not configured');
          }
          
          const squareClient = new SquareClient({
            token: accessToken,
            environment: SquareEnvironment.Production,
          });
          
          // Build Square line items from validated data
          const squareLineItems = validatedItems.map((item) => ({
            name: `${item.name}${item.size ? ` (${item.size})` : ""}${item.color ? ` - ${item.color}` : ""}`,
            quantity: String(item.quantity),
            basePriceMoney: {
              amount: BigInt(Math.round(parseFloat(item.unitPrice) * 100)),
              currency: "GBP",
            },
          }));

          // Add VAT as a line item only if non-zero
          if (serverTax > 0) {
            squareLineItems.push({
              name: "VAT (20%)",
              quantity: "1",
              basePriceMoney: {
                amount: BigInt(Math.round(serverTax * 100)),
                currency: "GBP",
              },
            });
          }
          
          // Apply coupon discount if validated
          if (validatedDiscount > 0 && validatedCouponCode) {
            // Apply discount proportionally across all product line items
            const totalProductValue = squareLineItems.reduce((sum, item) => {
              if (item.name !== "VAT (20%)") {
                return sum + Number(item.basePriceMoney.amount) * Number(item.quantity);
              }
              return sum;
            }, 0);
            
            const discountAmountPence = Math.round(validatedDiscount * 100);
            
            if (totalProductValue > 0 && discountAmountPence <= totalProductValue) {
              let remainingDiscount = discountAmountPence;
              const productItems = squareLineItems.filter(item => item.name !== "VAT (20%)");
              
              productItems.forEach((item, index) => {
                const itemTotal = Number(item.basePriceMoney.amount) * Number(item.quantity);
                const itemProportion = itemTotal / totalProductValue;
                
                const itemDiscount = index === productItems.length - 1
                  ? remainingDiscount
                  : Math.round(discountAmountPence * itemProportion);
                
                remainingDiscount -= itemDiscount;
                
                const discountPerUnit = Math.round(itemDiscount / Number(item.quantity));
                const newPrice = Math.max(0, Number(item.basePriceMoney.amount) - discountPerUnit);
                item.basePriceMoney.amount = BigInt(newPrice);
                item.name = `${item.name} (Coupon: ${validatedCouponCode})`;
              });
              
              console.log(`Applied discount to Square line items: ${validatedCouponCode} - £${validatedDiscount}`);
            }
          }
          
          // Create Square payment link
          const checkoutResponse = await squareClient.checkout.paymentLinks.create({
            idempotencyKey: `storefront-epos-${createdOrder.id}-${Date.now()}`,
            quickPay: undefined,
            order: {
              locationId,
              lineItems: squareLineItems,
              metadata: {
                orderId: createdOrder.id,
                orderNumber,
                orderType: "reseller_storefront_epos",
                resellerId,
                storefrontSlug,
                storefrontName: storefront.storeName,
              },
            },
            checkoutOptions: {
              redirectUrl: `${baseUrl}/store/${storefrontSlug}/epos?success=true&order=${orderNumber}`,
              acceptedPaymentMethods: {
                applePay: true,
                googlePay: true,
                afterpayClearpay: false,
              },
            },
            prePopulatedData: customerEmail ? { buyerEmail: customerEmail } : undefined,
          });

          const checkoutUrl = checkoutResponse.paymentLink?.url;
          const squareOrderId = checkoutResponse.paymentLink?.orderId;

          if (!checkoutUrl) {
            throw new Error('Failed to create Square checkout link');
          }

          // Store the Square order ID for verification
          await db.update(customerOrders)
            .set({ squareOrderId: squareOrderId || null })
            .where(eq(customerOrders.id, createdOrder.id));
          
          console.log("📱 Reseller Storefront EPOS Square checkout created:", {
            squareOrderId,
            checkoutUrl,
            orderNumber,
            resellerId,
            storefrontName: storefront.storeName,
            serverTotal,
          });

          return res.json({
            orderNumber,
            orderId: createdOrder.id,
            subtotal: serverSubtotal.toFixed(2),
            tax: serverTax.toFixed(2),
            total: serverTotal.toFixed(2),
            checkoutUrl,
          });
        } catch (squareError) {
          console.error("📱 Square error for reseller storefront:", squareError);
          return res.status(500).json({ error: "Payment processing failed" });
        }
      }

      // Send confirmation email for cash payments
      if (customerEmail) {
        try {
          await emailService.sendOrderConfirmationEmail(customerEmail, {
            orderNumber,
            items: validatedItems,
            totalAmount: serverTotal,
            paymentMethod,
        paypalOrderId, // PayPal order ID if payment was via PayPal
            storeName: storefront.storeName,
          });
        } catch (emailError) {
          console.warn("Email notification failed (non-critical):", emailError);
        }
      }

      console.log("Reseller Storefront EPOS cash order completed:", {
        orderNumber,
        resellerId,
        storefrontName: storefront.storeName,
        subtotal: serverSubtotal,
        tax: serverTax,
        total: serverTotal,
      });

      res.json({
        orderNumber,
        orderId: createdOrder.id,
        subtotal: serverSubtotal.toFixed(2),
        tax: serverTax.toFixed(2),
        total: serverTotal.toFixed(2),
        status: "confirmed",
        message: "Order completed successfully!",
      });
    } catch (error) {
      console.error("Reseller storefront checkout error:", error);
      res.status(500).json({ error: "Failed to complete purchase" });
    }
  });

  // ============================================
  // WAREHOUSE MANAGEMENT API ENDPOINTS
