  // Get warehouse inventory
  app.get("/api/admin/warehouses/:id/inventory", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const inventory = await db
        .select({
          id: warehouseInventory.id,
          warehouseId: warehouseInventory.warehouseId,
          productId: warehouseInventory.productId,
          variantId: warehouseInventory.variantId,
          // Use variant's size/colour when the inventory row's own columns are blank
          size: sql<string>`COALESCE(NULLIF(${warehouseInventory.size}, ''), ${productVariants.size})`,
          color: sql<string>`COALESCE(NULLIF(${warehouseInventory.color}, ''), ${productVariants.color})`,
          quantity: warehouseInventory.quantity,
          reservedQuantity: warehouseInventory.reservedQuantity,
          minStockLevel: warehouseInventory.minStockLevel,
          maxStockLevel: warehouseInventory.maxStockLevel,
          location: warehouseInventory.location,
          lastStockCheck: warehouseInventory.lastStockCheck,
          productName: products.name,
          productSku: products.sku,
          productImage: products.imageUrl,
        })
        .from(warehouseInventory)
        .innerJoin(products, eq(warehouseInventory.productId, products.id))
        .leftJoin(productVariants, eq(warehouseInventory.variantId, productVariants.id))
        .where(and(
          eq(warehouseInventory.warehouseId, id),
          or(eq(products.isDeleted, false), isNull(products.isDeleted)) // Filter out deleted products
        ))
        .orderBy(products.name, warehouseInventory.size, warehouseInventory.color);
      
      res.json(inventory);
    } catch (error) {
      console.error("Error fetching warehouse inventory:", error);
      res.status(500).json({ error: "Failed to fetch warehouse inventory" });
    }
  });

  // Add inventory to warehouse
  app.post("/api/admin/warehouses/:id/inventory", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const validation = insertWarehouseInventorySchema.safeParse({ ...req.body, warehouseId: id });
      if (!validation.success) {
        return res.status(400).json({ error: "Invalid inventory data", details: validation.error.format() });
      }
      
      // Check if inventory already exists for this product/size/color combination
      const [existing] = await db.select().from(warehouseInventory).where(
        and(
          eq(warehouseInventory.warehouseId, id),
          eq(warehouseInventory.productId, validation.data.productId),
          sql`coalesce(size, '') = coalesce(${validation.data.size || ''}, '')`,
          sql`coalesce(color, '') = coalesce(${validation.data.color || ''}, '')`
        )
      );
      
      if (existing) {
        // Update existing inventory
        const [updated] = await db.update(warehouseInventory)
          .set({ 
            quantity: sql`quantity + ${validation.data.quantity}`,
            updatedAt: new Date()
          })
          .where(eq(warehouseInventory.id, existing.id))
          .returning();
        return res.json(updated);
      }
      
      const [newInventory] = await db.insert(warehouseInventory).values(validation.data).returning();
      res.status(201).json(newInventory);
    } catch (error) {
      console.error("Error adding warehouse inventory:", error);
      res.status(500).json({ error: "Failed to add inventory" });
    }
  });

