  // Promote reseller to vendor
  app.post("/api/admin/b2b/partners/promote/:resellerId", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { resellerId } = req.params;
      
      const [reseller] = await db.select().from(resellers).where(eq(resellers.id, resellerId));
      if (!reseller) {
        return res.status(404).json({ error: "Reseller not found" });
      }
      
      if (reseller.approvalStatus === 'promoted') {
        return res.status(400).json({ error: "Reseller already promoted to vendor" });
      }
      
      const user = await storage.getUserById(reseller.userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }
      
      const [existingVendor] = await db.select().from(vendors).where(eq(vendors.userId, reseller.userId));
      if (existingVendor) {
        return res.status(400).json({ error: "Vendor account already exists for this user" });
      }
      
      const [newVendor] = await db.insert(vendors).values({
        userId: reseller.userId,
        businessName: reseller.businessName,
        businessAddress: reseller.businessAddress,
        phoneNumber: reseller.phoneNumber,
        approvalStatus: 'approved',
        isActive: true,
        approvedBy: req.session?.userId,
        approvedAt: new Date(),
      }).returning();
      
      await db.update(users)
        .set({ role: 'vendor' })
        .where(eq(users.id, reseller.userId));
      
      await db.update(resellers)
        .set({ approvalStatus: 'promoted' as any })
        .where(eq(resellers.id, resellerId));
      
      const defaultCapabilities = ['sell_1strep_products', 'add_own_products', 'manage_storefront', 'view_analytics', 'process_epos'];
      for (const cap of defaultCapabilities) {
        await db.insert(b2bPartnerCapabilities).values({
          partnerType: 'vendor',
          partnerId: newVendor.id,
          capability: cap as any,
          enabled: true,
          grantedBy: req.session?.userId,
        });
      }
      
      res.json({ 
        success: true, 
        message: `${reseller.businessName} promoted to vendor`,
        vendor: newVendor 
      });
    } catch (error) {
      console.error("Error promoting reseller:", error);
      res.status(500).json({ error: "Failed to promote reseller" });
    }
  });

