  // Validate and apply coupon (for partner storefronts)
  app.post("/api/b2b/validate-coupon", async (req, res) => {
    try {
      const { code, partnerId, orderTotal } = req.body;
      
      if (!code || !partnerId) {
        return res.status(400).json({ error: "Coupon code and partner ID are required" });
      }
      
      const [coupon] = await db.select()
        .from(b2bPartnerCoupons)
        .where(and(
          eq(b2bPartnerCoupons.code, code.toUpperCase()),
          eq(b2bPartnerCoupons.partnerId, partnerId)
        ));
      
      if (!coupon) {
        return res.status(404).json({ error: "Invalid coupon code" });
      }
      
      // Check if coupon is active
      if (!coupon.isActive) {
        return res.status(400).json({ error: "Coupon is not active" });
      }
      
      // Check if coupon has started
      if (coupon.startsAt && new Date(coupon.startsAt) > new Date()) {
        return res.status(400).json({ error: "Coupon is not yet valid" });
      }
      
      // Check if coupon has expired
      if (coupon.expiresAt && new Date(coupon.expiresAt) < new Date()) {
        return res.status(400).json({ error: "Coupon has expired" });
      }
      
      // Check usage limit
      if (coupon.usageLimit && coupon.usageCount >= coupon.usageLimit) {
        return res.status(400).json({ error: "Coupon usage limit reached" });
      }
      
      // Check minimum order value
      if (coupon.minOrderValue && orderTotal && parseFloat(orderTotal) < parseFloat(coupon.minOrderValue)) {
        return res.status(400).json({ 
          error: `Minimum order value of £${coupon.minOrderValue} required` 
        });
      }
      
      // Calculate discount
      let discount = 0;
      if (coupon.discountType === 'percentage') {
        discount = (parseFloat(orderTotal || '0') * parseFloat(coupon.discountValue)) / 100;
        if (coupon.maxDiscount && discount > parseFloat(coupon.maxDiscount)) {
          discount = parseFloat(coupon.maxDiscount);
        }
      } else {
        discount = parseFloat(coupon.discountValue);
      }
      
      res.json({
        valid: true,
        coupon: {
          id: coupon.id,
          code: coupon.code,
          discountType: coupon.discountType,
          discountValue: coupon.discountValue,
          maxDiscount: coupon.maxDiscount,
        },
        calculatedDiscount: discount.toFixed(2),
      });
    } catch (error) {
      console.error("Error validating coupon:", error);
      res.status(500).json({ error: "Failed to validate coupon" });
    }
  });

