  // Admin - Comprehensive Sales Report
  app.get("/api/admin/reports/sales", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { startDate, endDate, groupBy = 'day' } = req.query;
      
      const start = startDate ? new Date(startDate as string) : new Date(new Date().setMonth(new Date().getMonth() - 1));
      const end = endDate ? new Date(endDate as string) : new Date();
      
      // Get all customer orders within date range (primary B2C orders)
      const allOrders = await db.select()
        .from(customerOrders)
        .where(and(
          sql`${customerOrders.orderDate} >= ${start}`,
          sql`${customerOrders.orderDate} <= ${end}`
        ))
        .orderBy(desc(customerOrders.orderDate));
      
      
      // Get all order items with product cost prices
      const orderIds = allOrders.map(o => o.id);
      let allItems: any[] = [];
      if (orderIds.length > 0) {
        // Join with products table to get costPrice
        allItems = await db.select({
          id: customerOrderItems.id,
          orderId: customerOrderItems.orderId,
          productId: customerOrderItems.productId,
          productName: customerOrderItems.productName,
          quantity: customerOrderItems.quantity,
          unitPrice: customerOrderItems.unitPrice,
          totalPrice: customerOrderItems.totalPrice,
          costPrice: products.costPrice
        })
          .from(customerOrderItems)
          .leftJoin(products, eq(customerOrderItems.productId, products.id))
          .where(inArray(customerOrderItems.orderId, orderIds));
      }
      
      // Calculate summary metrics including profit
      const totalRevenue = allOrders.reduce((sum, o) => sum + parseFloat(o.totalAmount || '0'), 0);
      const totalCost = allItems.reduce((sum, item) => sum + (parseFloat(item.costPrice || '0') * item.quantity), 0);
      const grossProfit = totalRevenue - totalCost;
      const profitMargin = totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;
      const totalOrders = allOrders.length;
      const avgOrderValue = totalOrders > 0 ? totalRevenue / totalOrders : 0;
      
      // Group by status
      const byStatus = allOrders.reduce((acc, order) => {
        acc[order.status] = (acc[order.status] || 0) + 1;
        return acc;
      }, {} as Record<string, number>);
      
      // Group by channel
      const byChannel = allOrders.reduce((acc, order) => {
        const channel = order.channel || 'website';
        acc[channel] = acc[channel] || { count: 0, revenue: 0 };
        acc[channel].count++;
        acc[channel].revenue += parseFloat(order.totalAmount || '0');
        return acc;
      }, {} as Record<string, { count: number; revenue: number }>);
      
      // Create order to items mapping for profit calculations
      const orderItemsMap = new Map<string, any[]>();
      allItems.forEach(item => {
        if (!orderItemsMap.has(item.orderId)) {
          orderItemsMap.set(item.orderId, []);
        }
        orderItemsMap.get(item.orderId)!.push(item);
      });
      
      // Group by date (day/week/month) with profit data
      const salesByDate: Record<string, { date: string; orders: number; revenue: number; cost: number; profit: number }> = {};
      allOrders.forEach(order => {
        const date = new Date(order.orderDate!);
        let key: string;
        if (groupBy === 'month') {
          key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
        } else if (groupBy === 'week') {
          const weekStart = new Date(date);
          weekStart.setDate(date.getDate() - date.getDay());
          key = weekStart.toISOString().split('T')[0];
        } else {
          key = date.toISOString().split('T')[0];
        }
        
        // Calculate cost for this order
        const orderItems = orderItemsMap.get(order.id) || [];
        const orderCost = orderItems.reduce((sum: number, item: any) => sum + (parseFloat(item.costPrice || '0') * item.quantity), 0);
        const orderRevenue = parseFloat(order.totalAmount || '0');
        
        if (!salesByDate[key]) {
          salesByDate[key] = { date: key, orders: 0, revenue: 0, cost: 0, profit: 0 };
        }
        salesByDate[key].orders++;
        salesByDate[key].revenue += orderRevenue;
        salesByDate[key].cost += orderCost;
        salesByDate[key].profit += (orderRevenue - orderCost);
      });
      
      // Top selling products from order items (already fetched above)
      const productSales: Record<string, { productId: string; name: string; quantity: number; revenue: number; cost: number; profit: number; margin: number }> = {};
      allItems.forEach(item => {
        if (!productSales[item.productId]) {
          productSales[item.productId] = { productId: item.productId, name: item.productName, quantity: 0, revenue: 0, cost: 0, profit: 0, margin: 0 };
        }
        const itemCost = parseFloat(item.costPrice || '0') * item.quantity;
        const itemRevenue = parseFloat(item.totalPrice || '0');
        productSales[item.productId].quantity += item.quantity;
        productSales[item.productId].revenue += itemRevenue;
        productSales[item.productId].cost += itemCost;
        productSales[item.productId].profit += (itemRevenue - itemCost);
      });
      
      // Calculate margins for each product
      Object.values(productSales).forEach(product => {
        product.margin = product.revenue > 0 ? (product.profit / product.revenue) * 100 : 0;
      });
      
      const topProducts = Object.values(productSales).sort((a, b) => b.revenue - a.revenue).slice(0, 10);
      
      res.json({
        summary: {
          totalRevenue,
          totalCost,
          grossProfit,
          profitMargin,
          totalOrders,
          avgOrderValue,
          dateRange: { start, end }
        },
        byStatus,
        byChannel,
        salesByDate: Object.values(salesByDate).sort((a, b) => a.date.localeCompare(b.date)),
        topProducts
      });
    } catch (error) {
      console.error("Sales report error:", error);
      res.status(500).json({ error: "Failed to generate sales report" });
    }
  });

  // Admin - Orders Report
