  // Ensure outreach tables exist (lazy migration)
  (async () => {
    try {
      await db.execute(sql`
        CREATE TABLE IF NOT EXISTS outreach_templates (
          id VARCHAR PRIMARY KEY DEFAULT gen_random_uuid(),
          name TEXT NOT NULL,
          subject TEXT NOT NULL,
          body TEXT NOT NULL,
          created_by VARCHAR REFERENCES users(id),
          created_at TIMESTAMP NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMP NOT NULL DEFAULT NOW(),
          last_used_at TIMESTAMP
        )
      `);
      // Add last_used_at column if migrating from old schema
      await db.execute(sql`
        ALTER TABLE outreach_templates ADD COLUMN IF NOT EXISTS last_used_at TIMESTAMP
      `);
      await db.execute(sql`
        CREATE TABLE IF NOT EXISTS outreach_email_log (
          id VARCHAR PRIMARY KEY DEFAULT gen_random_uuid(),
          sent_by VARCHAR REFERENCES users(id),
          to_email TEXT NOT NULL,
          subject TEXT NOT NULL,
          body TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT 'sent',
          broadcast_id VARCHAR,
          sent_at TIMESTAMP NOT NULL DEFAULT NOW()
        )
      `);
    } catch (e) {
      console.error("[Outreach] Table migration error:", e);
    }
  })();

  // Helper: personalise body text with recipient-specific placeholders
  function personaliseOutreachBody(body: string, recipient: { email: string; firstName?: string; lastName?: string }): string {
    return body
      .replace(/\{\{firstName\}\}/g, recipient.firstName || "")
      .replace(/\{\{lastName\}\}/g, recipient.lastName || "")
      .replace(/\{\{email\}\}/g, recipient.email);
  }

  const OUTREACH_EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

  // Send direct email(s) to one or more recipients
  // Body: { recipients: string[], subject: string, body: string, templateId?: string }
  app.post("/api/admin/email/send-direct", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { recipients, subject, body, templateId } = req.body as {
        recipients: string[];
        subject: string;
        body: string;
        templateId?: string;
      };
      if (!recipients?.length || !subject || !body) {
        return res.status(400).json({ error: "recipients, subject and body are required" });
      }
      const { sendEmail, wrapEmailTemplate } = await import("./email");
      const results: { email: string; status: "sent" | "failed" }[] = [];
      for (const raw of recipients) {
        const email = raw.trim().toLowerCase();
        if (!email || !OUTREACH_EMAIL_REGEX.test(email)) {
          results.push({ email: raw.trim() || raw, status: "failed" });
          // Log invalid address so audit trail is complete
          await db.execute(sql`
            INSERT INTO outreach_email_log (sent_by, to_email, subject, body, status)
            VALUES (${req.user!.id}, ${raw.trim() || "(invalid)"}, ${subject}, ${body}, 'failed')
          `).catch(() => {});
          continue;
        }
        try {
          const personalised = personaliseOutreachBody(body, { email });
          const htmlBody = wrapEmailTemplate(`<tr><td style="padding:40px;color:#d1d5db;font-family:sans-serif;line-height:1.6;">${personalised.replace(/\n/g, "<br>")}</td></tr>`);
          const ok = await sendEmail(email, subject, htmlBody);
          await db.execute(sql`
            INSERT INTO outreach_email_log (sent_by, to_email, subject, body, status)
            VALUES (${req.user!.id}, ${email}, ${subject}, ${body}, ${ok ? "sent" : "failed"})
          `);
          results.push({ email, status: ok ? "sent" : "failed" });
        } catch {
          await db.execute(sql`
            INSERT INTO outreach_email_log (sent_by, to_email, subject, body, status)
            VALUES (${req.user!.id}, ${email}, ${subject}, ${body}, 'failed')
          `).catch(() => {});
          results.push({ email, status: "failed" });
        }
      }
      // Touch template last_used_at if a template was applied
      if (templateId) {
        await db.execute(sql`
          UPDATE outreach_templates SET last_used_at = NOW() WHERE id = ${templateId}
        `).catch(() => {});
      }
      const sent = results.filter(r => r.status === "sent").length;
      const failed = results.filter(r => r.status === "failed").length;
      res.json({ sent, failed, results });
    } catch (error) {
      console.error("Send direct email error:", error);
      res.status(500).json({ error: "Failed to send email" });
    }
  });

  // Broadcast to a list of named recipients (from CSV)
  // Body: { recipients: Array<{email, firstName?, lastName?}>, subject: string, body: string, templateId?: string }
  app.post("/api/admin/email/broadcast", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { recipients, subject, body, templateId, broadcastId: clientBroadcastId } = req.body as {
        recipients: Array<{ email: string; firstName?: string; lastName?: string }>;
        subject: string;
        body: string;
        templateId?: string;
        broadcastId?: string;
      };
      if (!recipients?.length || !subject || !body) {
        return res.status(400).json({ error: "recipients, subject and body are required" });
      }
      const { sendEmail, wrapEmailTemplate } = await import("./email");
      // Use client-supplied broadcastId if provided (keeps batched sends in one history group)
      const broadcastId = clientBroadcastId || crypto.randomUUID();
      const results: { email: string; status: "sent" | "failed" }[] = [];
      for (const recipient of recipients) {
        const email = (recipient.email || "").trim().toLowerCase();
        if (!email || !OUTREACH_EMAIL_REGEX.test(email)) {
          // Log invalid/skipped recipient so audit trail is complete
          const rawEmail = (recipient.email || "").trim() || "(invalid)";
          await db.execute(sql`
            INSERT INTO outreach_email_log (sent_by, to_email, subject, body, status, broadcast_id)
            VALUES (${req.user!.id}, ${rawEmail}, ${subject}, ${body}, 'failed', ${broadcastId})
          `).catch(() => {});
          results.push({ email: rawEmail, status: "failed" });
          continue;
        }
        try {
          const personalised = personaliseOutreachBody(body, {
            email,
            firstName: recipient.firstName,
            lastName: recipient.lastName,
          });
          const htmlBody = wrapEmailTemplate(`<tr><td style="padding:40px;color:#d1d5db;font-family:sans-serif;line-height:1.6;">${personalised.replace(/\n/g, "<br>")}</td></tr>`);
          const ok = await sendEmail(email, subject, htmlBody);
          await db.execute(sql`
            INSERT INTO outreach_email_log (sent_by, to_email, subject, body, status, broadcast_id)
            VALUES (${req.user!.id}, ${email}, ${subject}, ${body}, ${ok ? "sent" : "failed"}, ${broadcastId})
          `);
          results.push({ email, status: ok ? "sent" : "failed" });
        } catch {
          await db.execute(sql`
            INSERT INTO outreach_email_log (sent_by, to_email, subject, body, status, broadcast_id)
            VALUES (${req.user!.id}, ${email}, ${subject}, ${body}, 'failed', ${broadcastId})
          `).catch(() => {});
          results.push({ email, status: "failed" });
        }
      }
      // Touch template last_used_at
      if (templateId) {
        await db.execute(sql`
          UPDATE outreach_templates SET last_used_at = NOW() WHERE id = ${templateId}
        `).catch(() => {});
      }
      const sent = results.filter(r => r.status === "sent").length;
      const failed = results.filter(r => r.status === "failed").length;
      const failedAddresses = results.filter(r => r.status === "failed").map(r => r.email);
      res.json({ broadcastId, sent, failed, failedAddresses, results });
    } catch (error) {
      console.error("Broadcast email error:", error);
      res.status(500).json({ error: "Failed to send broadcast" });
    }
  });

