  // Submit athlete application (public endpoint)
  app.post("/api/athlete-applications", async (req, res) => {
    try {
      const { fullName, email, phone, sport, followerCount, instagram, tiktok, youtube, message } = req.body;
      
      if (!fullName || !email || !sport || !message) {
        return res.status(400).json({ error: "Please fill in all required fields" });
      }
      
      if (!email.includes('@')) {
        return res.status(400).json({ error: "Please provide a valid email address" });
      }

      // Check if email already has an active approved influencer profile
      const existingProfile = await db.execute(sql`
        SELECT ap.id FROM athlete_profiles ap
        JOIN users u ON u.id = ap.user_id
        WHERE LOWER(u.email) = LOWER(${email}) AND ap.is_active = true
        LIMIT 1
      `);
      if (existingProfile.rows.length > 0) {
        return res.status(409).json({ error: "This email is already registered as an approved influencer. Log in to access your dashboard." });
      }

      // Check if a pending or approved application already exists for this email
      const existingApplication = await db.execute(sql`
        SELECT id, status FROM athlete_applications
        WHERE LOWER(email) = LOWER(${email}) AND status IN ('pending', 'approved')
        ORDER BY created_at DESC
        LIMIT 1
      `);
      if (existingApplication.rows.length > 0) {
        const existing = existingApplication.rows[0] as any;
        if (existing.status === 'approved') {
          return res.status(409).json({ error: "This email already has an approved application. Log in to access your influencer dashboard." });
        }
        return res.status(409).json({ error: "You have already submitted an application with this email. We'll be in touch within 7 days — please check your inbox." });
      }
      
      // Insert application into database
      await db.execute(sql`
        INSERT INTO athlete_applications (full_name, email, phone, sport, follower_count, instagram, tiktok, youtube, message)
        VALUES (${fullName}, ${email}, ${phone || null}, ${sport}, ${followerCount || null}, ${instagram || null}, ${tiktok || null}, ${youtube || null}, ${message})
      `);
      
      // Create admin notification
      await db.insert(adminNotifications).values({
        type: 'athlete_application',
        title: 'New Athlete Application',
        message: `${fullName} has applied for the Athlete Programme - ${sport}`,
        link: '/admin/athletes',
        isRead: false
      });

      // Send application received confirmation to applicant (non-blocking)
      sendInfluencerApplicationReceivedEmail({ email, name: fullName, sport }).catch(err => {
        console.error('Failed to send influencer application confirmation email:', err);
      });

      // Send admin notification email (non-blocking)
      sendInfluencerApplicationAdminNotificationEmail({
        name: fullName,
        email,
        sport,
        instagramHandle: instagram || undefined,
        followerCount: followerCount || undefined,
      }).catch(err => {
        console.error('Failed to send influencer application admin notification email:', err);
      });

      smsInfluencerApplicationReceived(phone || null, fullName);
      
      res.json({ success: true, message: "Application submitted successfully" });
    } catch (error) {
      console.error("Athlete application error:", error);
      res.status(500).json({ error: "Failed to submit application" });
    }
  });
  
