  // Update athlete application status (admin only)
  app.patch("/api/admin/athlete-applications/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const { status, notes } = req.body;
      
      // Validate status
      const validStatuses = ['pending', 'approved', 'rejected'];
      if (status && !validStatuses.includes(status)) {
        return res.status(400).json({ error: "Invalid status. Must be: pending, approved, or rejected" });
      }
      
      // Get application details
      const existingApp = await db.execute(sql`SELECT * FROM athlete_applications WHERE id = ${id}`);
      if (existingApp.rows.length === 0) {
        return res.status(404).json({ error: "Application not found" });
      }
      
      const application = existingApp.rows[0] as any;
      
      // If approving, create user account and athlete profile
      if (status === 'approved' && application.status !== 'approved') {
        // Check if user already exists with this email
        let userId: string;
        const existingUser = await db.execute(sql`SELECT id FROM users WHERE email = ${application.email}`);
        
        if (existingUser.rows.length > 0) {
          // Use existing user
          userId = (existingUser.rows[0] as any).id;
          
          // Update user role to include athlete
          await db.execute(sql`
            UPDATE users SET role = 'athlete' WHERE id = ${userId} AND role = 'customer'
          `);
        } else {
          // Create new user account with temporary password
          const crypto = await import('crypto');
          const tempPassword = crypto.randomBytes(8).toString('hex');
          const bcrypt = await import('bcryptjs');
          const hashedPassword = await bcrypt.hash(tempPassword, 10);
          
          const nameParts = application.full_name.split(' ');
          const firstName = nameParts[0] || '';
          const lastName = nameParts.slice(1).join(' ') || '';
          
          const newUser = await db.execute(sql`
            INSERT INTO users (email, first_name, last_name, password, role, is_verified)
            VALUES (${application.email}, ${firstName}, ${lastName}, ${hashedPassword}, 'athlete', true)
            RETURNING id
          `);
          userId = (newUser.rows[0] as any).id;
          // Store tempPassword on the application object so we can email it after profile setup
          (application as any)._tempPassword = tempPassword;
          console.log(`New athlete user created: ${application.email}`);
        }
        
        // Generate tracking link slug from name (e.g. "Tink Jackson" -> "TINK")
        const firstName = application.full_name.split(' ')[0];
        const baseSlug = firstName.toUpperCase().replace(/[^A-Z0-9]/g, '');
        // Ensure uniqueness
        let trackingSlug = baseSlug;
        let slugSuffix = 1;
        while (true) {
          const existing = await db.execute(sql`SELECT id FROM athlete_profiles WHERE tracking_link = ${trackingSlug}`);
          if (existing.rows.length === 0) break;
          trackingSlug = `${baseSlug}${slugSuffix}`;
          slugSuffix++;
        }

        // Create athlete profile with tracking link
        // Use trackingSlug as the athlete's primary discount code (variants SLUG10/SLUG15 handle the actual discounts)
        await db.execute(sql`
          INSERT INTO athlete_profiles (user_id, application_id, discount_code, sport, instagram, tiktok, youtube, tracking_link, is_active, onboarding_completed)
          VALUES (${userId}, ${id}, ${trackingSlug}, ${application.sport}, ${application.instagram}, ${application.tiktok}, ${application.youtube}, ${trackingSlug}, true, false)
        `);

        // Get the new profile ID
        const newProfile = await db.execute(sql`SELECT id FROM athlete_profiles WHERE user_id = ${userId} ORDER BY joined_at DESC LIMIT 1`);
        if (newProfile.rows.length > 0) {
          const newProfileId = (newProfile.rows[0] as any).id;
          // Grant 100 welcome credits
          await db.execute(sql`
            INSERT INTO influencer_credit_transactions (athlete_profile_id, type, amount, description, created_by)
            VALUES (${newProfileId}, 'welcome', 100, 'Welcome credits for joining the 1stRep Influencer Programme', ${req.user!.id})
          `);
          await db.execute(sql`
            UPDATE athlete_profiles SET credit_balance = 100, welcome_credit_granted = true WHERE id = ${newProfileId}
          `);

          // Create default discount variants: NAME10 (active) and NAME15
          // fixed_credits_per_order=10 means influencer earns 10 flat credits per sale
          const base10 = `${trackingSlug}10`;
          const base15 = `${trackingSlug}15`;
          await db.execute(sql`
            INSERT INTO influencer_discount_variants (athlete_profile_id, code_suffix, full_code, customer_discount_pct, influencer_credit_pct, fixed_credits_per_order, is_active)
            VALUES 
              (${newProfileId}, '10', ${base10}, 10, 0, 10, true),
              (${newProfileId}, '15', ${base15}, 15, 0, 10, false)
          `);

          // Create coupons for both variants (10% off default active)
          const endDate = new Date();
          endDate.setFullYear(endDate.getFullYear() + 1);
          await db.execute(sql`
            INSERT INTO coupons (id, code, description, type, value, minimum_order_total, max_global_uses, start_date, end_date, is_active)
            VALUES (gen_random_uuid(), ${base10}, ${'Influencer code - 10% discount for ' + application.full_name}, 'percentage', '10', '0', NULL, NOW(), ${endDate.toISOString()}, true)
            ON CONFLICT (code) DO NOTHING
          `);
          await db.execute(sql`
            INSERT INTO coupons (id, code, description, type, value, minimum_order_total, max_global_uses, start_date, end_date, is_active)
            VALUES (gen_random_uuid(), ${base15}, ${'Influencer code - 15% discount for ' + application.full_name}, 'percentage', '15', '0', NULL, NOW(), ${endDate.toISOString()}, false)
            ON CONFLICT (code) DO NOTHING
          `);

          // Create personal 50% first-order coupon for the influencer themselves
          const personal50Code = `${trackingSlug}50`;
          await db.execute(sql`
            INSERT INTO coupons (id, code, description, type, value, minimum_order_total, max_global_uses, first_order_only, start_date, end_date, is_active)
            VALUES (gen_random_uuid(), ${personal50Code}, ${'Personal 50% first-order discount for influencer ' + application.full_name}, 'percentage', '50', '0', 1, true, NOW(), ${endDate.toISOString()}, true)
            ON CONFLICT (code) DO NOTHING
          `);
        }
        
        console.log(`Athlete profile created for ${application.full_name} with influencer tracking slug: ${trackingSlug}`);

        // Send approval email + SMS with login details (non-blocking)
        const isNewAccount = !!(application as any)._tempPassword;
        sendInfluencerApprovedEmail({
          email: application.email,
          name: application.full_name,
          discountCode: trackingSlug,
          tempPassword: (application as any)._tempPassword || null,
          isNewAccount,
        }).then(sent => {
          if (sent) console.log(`Influencer approval email sent to ${application.email}`);
          else console.warn(`Influencer approval email failed for ${application.email}`);
        }).catch(err => {
          console.error('Failed to send influencer approval email:', err);
        });
        smsInfluencerApproved(application.phone || null, application.full_name, trackingSlug);
      }

      // Rejection previously updated the record silently with no notification
      // to the applicant — they'd never find out unless they checked back.
      if (status === 'rejected' && application.status !== 'rejected') {
        sendInfluencerRejectedEmail({
          email: application.email,
          name: application.full_name,
        }).then(sent => {
          if (sent) console.log(`Influencer rejection email sent to ${application.email}`);
          else console.warn(`Influencer rejection email failed for ${application.email}`);
        }).catch(err => {
          console.error('Failed to send influencer rejection email:', err);
        });
      }

      // Update application status
      await db.execute(sql`
        UPDATE athlete_applications 
        SET status = ${status || 'pending'}, notes = ${notes || null}, reviewed_at = NOW(), reviewed_by = ${req.user!.id}
        WHERE id = ${id}
      `);
      
      res.json({ success: true, message: status === 'approved' ? "Athlete approved and profile created" : "Application updated" });
    } catch (error) {
      console.error("Update athlete application error:", error);
      res.status(500).json({ error: "Failed to update application" });
    }
  });
  
