  // Influencer - Upload profile avatar to object storage
  const influencerAvatarUpload = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 5 * 1024 * 1024 },
    fileFilter: (req, file, cb) => {
      const allowed = ['image/jpeg', 'image/png', 'image/webp'];
      if (allowed.includes(file.mimetype)) cb(null, true);
      else cb(new Error('Only JPEG, PNG, or WebP allowed'));
    }
  });

  app.post("/api/influencer/upload-avatar", requireAuth, influencerAvatarUpload.single('avatar'), async (req, res) => {
    try {
      const profile = await db.execute(sql`SELECT id FROM athlete_profiles WHERE user_id = ${req.user!.id}`);
      if (profile.rows.length === 0) return res.status(403).json({ error: "Not an influencer" });
      if (!req.file) return res.status(400).json({ error: "No file provided" });
      const profileId = (profile.rows[0] as any).id;
      const ext = req.file.originalname.split('.').pop() || 'jpg';
      const key = `influencer-avatars/${profileId}/${Date.now()}.${ext}`;
      const objectStorageService = new ObjectStorageService();
      const imageUrl = await objectStorageService.uploadBuffer(key, req.file.buffer, req.file.mimetype);
      await db.execute(sql`UPDATE athlete_profiles SET profile_image_url = ${imageUrl} WHERE id = ${profileId}`);
      res.json({ success: true, imageUrl });
    } catch (error: any) {
      console.error("Influencer avatar upload error:", error);
      res.status(500).json({ error: error.message || "Failed to upload avatar" });
    }
  });
  
  // Submit content
  app.post("/api/athlete/content", requireAuth, async (req, res) => {
    try {
      const { contentType, platform, contentUrl, description } = req.body;

      // Validate required fields
      const validPlatforms = ['instagram', 'tiktok', 'youtube'];
      const validContentTypes = ['photo', 'video', 'reel', 'story'];
      if (!platform || !validPlatforms.includes(platform)) {
        return res.status(400).json({ error: "Valid platform is required: instagram, tiktok, or youtube" });
      }
      if (!contentType || !validContentTypes.includes(contentType)) {
        return res.status(400).json({ error: "Valid content type is required: photo, video, reel, or story" });
      }
      if (!contentUrl || !contentUrl.startsWith('http')) {
        return res.status(400).json({ error: "A valid post URL starting with http is required" });
      }

      // Validate URL domain matches the selected platform
      let urlHost = '';
      try { urlHost = new URL(contentUrl).hostname.replace('www.', ''); } catch {}
      const domainMap: Record<string, string[]> = {
        instagram: ['instagram.com'],
        tiktok:    ['tiktok.com', 'vm.tiktok.com'],
        youtube:   ['youtube.com', 'youtu.be'],
      };
      const allowedDomains = domainMap[platform] || [];
      if (!allowedDomains.some(d => urlHost === d || urlHost.endsWith('.' + d))) {
        return res.status(400).json({ error: `URL must be from ${allowedDomains.join(' or ')} for ${platform}` });
      }

      // Check if user is an athlete
      const profile = await db.execute(sql`
        SELECT id, credit_balance FROM athlete_profiles WHERE user_id = ${req.user!.id}
      `);
      
      if (profile.rows.length === 0) {
        return res.status(403).json({ error: "Not an athlete" });
      }
      
      const profileId = (profile.rows[0] as any).id;

      // Check for duplicate URL submission
      const duplicate = await db.execute(sql`
        SELECT id FROM athlete_content_submissions
        WHERE athlete_profile_id = ${profileId} AND content_url = ${contentUrl}
        LIMIT 1
      `);
      if (duplicate.rows.length > 0) {
        return res.status(400).json({ error: "You have already submitted this post URL" });
      }

      // Insert as PENDING — credits only awarded after admin manually verifies and approves
      const result = await db.execute(sql`
        INSERT INTO athlete_content_submissions (athlete_profile_id, content_type, platform, content_url, description, status)
        VALUES (${profileId}, ${contentType}, ${platform}, ${contentUrl}, ${description || null}, 'pending')
        RETURNING *
      `);
      
      res.json({ ...result.rows[0], credit_awarded: 0 });
    } catch (error) {
      console.error("Submit content error:", error);
      res.status(500).json({ error: "Failed to submit content" });
    }
  });
  
