  // Admin: Review athlete content submission
  app.patch("/api/admin/athlete-content-submissions/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const { status, notes, creditAmount } = req.body;
      const user = req.user as any;
      
      const validStatuses = ['pending', 'approved', 'rejected', 'featured'];
      if (status && !validStatuses.includes(status)) {
        return res.status(400).json({ error: "Invalid status" });
      }

      // Get the submission to check if it was previously not approved
      const existingSubmission = await db.execute(sql`SELECT * FROM athlete_content_submissions WHERE id = ${id}`);
      if (existingSubmission.rows.length === 0) {
        return res.status(404).json({ error: "Content submission not found" });
      }
      const existing = existingSubmission.rows[0] as any;
      
      const result = await db.execute(sql`
        UPDATE athlete_content_submissions 
        SET status = ${status}, notes = ${notes || null}, reviewed_at = NOW(), reviewed_by = ${user.id}
        WHERE id = ${id}
        RETURNING *
      `);
      
      // Award credits when post is approved (if was previously pending/rejected)
      if ((status === 'approved' || status === 'featured') && existing.status !== 'approved' && existing.status !== 'featured') {
        const creditAmt = creditAmount ? parseFloat(creditAmount) : 1; // default 1 credit per approved post
        await db.execute(sql`
          INSERT INTO influencer_credit_transactions (athlete_profile_id, type, amount, description, created_by)
          VALUES (${existing.athlete_profile_id}, 'post_approved', ${creditAmt}, ${'Credit awarded for approved content submission (' + (existing.platform || 'social') + ')'}, ${user.id})
        `);
        await db.execute(sql`
          UPDATE athlete_profiles SET credit_balance = credit_balance + ${creditAmt} WHERE id = ${existing.athlete_profile_id}
        `);
      }
      
      res.json(result.rows[0]);
    } catch (error) {
      console.error("Review content submission error:", error);
      res.status(500).json({ error: "Failed to review content submission" });
    }
  });

