  // Admin: Get aggregate influencer performance analytics
  app.get("/api/admin/influencer-performance", requireAuth, requireAdmin, async (req, res) => {
    try {
      const rows = await db.execute(sql`
        SELECT
          ap.id as athlete_profile_id,
          u.first_name,
          u.last_name,
          ap.tracking_link,
          ap.tier,
          COUNT(acs.id) FILTER (WHERE acs.status IN ('approved','featured')) AS approved_posts,
          COALESCE(SUM(acs.views) FILTER (WHERE acs.status IN ('approved','featured')), 0) AS total_views,
          COALESCE(SUM(acs.likes) FILTER (WHERE acs.status IN ('approved','featured')), 0) AS total_likes,
          COALESCE(SUM(acs.comments) FILTER (WHERE acs.status IN ('approved','featured')), 0) AS total_comments,
          COALESCE(SUM(acs.shares) FILTER (WHERE acs.status IN ('approved','featured')), 0) AS total_shares,
          COALESCE(SUM(acs.clicks) FILTER (WHERE acs.status IN ('approved','featured')), 0) AS total_clicks,
          COALESCE(SUM(acs.reach) FILTER (WHERE acs.status IN ('approved','featured')), 0) AS total_reach,
          CASE
            WHEN COALESCE(SUM(acs.reach) FILTER (WHERE acs.status IN ('approved','featured')), 0) > 0
            THEN ROUND(
              (COALESCE(SUM(acs.likes + acs.comments + acs.shares) FILTER (WHERE acs.status IN ('approved','featured')), 0)::numeric
              / NULLIF(SUM(acs.reach) FILTER (WHERE acs.status IN ('approved','featured')), 0)) * 100, 2
            )
            ELSE 0
          END AS avg_engagement_rate
        FROM athlete_profiles ap
        JOIN users u ON u.id = ap.user_id
        LEFT JOIN athlete_content_submissions acs ON acs.athlete_profile_id = ap.id
        WHERE ap.is_active = true
        GROUP BY ap.id, u.first_name, u.last_name, ap.tracking_link, ap.tier
        ORDER BY total_views DESC
      `);
      res.json(rows.rows);
    } catch (error) {
      console.error("Get influencer performance error:", error);
      res.status(500).json({ error: "Failed to load performance data" });
    }
  });

  // Admin: Create new athlete programme/profile manually
  app.post("/api/admin/athlete-profiles", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { email, first_name, last_name, sport, tier, discount_percentage, instagram, tiktok, youtube, bio } = req.body;
      
      if (!email || !first_name || !last_name || !sport) {
        return res.status(400).json({ error: "Email, first name, last name, and sport are required" });
      }
      
      // Check if user exists or create new
      let userId: string;
      const existingUser = await db.execute(sql`SELECT id FROM users WHERE email = ${email}`);
      
      if (existingUser.rows.length > 0) {
        userId = (existingUser.rows[0] as any).id;
        // Update role to include athlete
        await db.execute(sql`UPDATE users SET role = 'athlete' WHERE id = ${userId} AND role = 'customer'`);
      } else {
        // Create new user
        const tempPassword = `Athlete${Date.now()}!`;
        const bcrypt = await import('bcryptjs');
        const hashedPassword = await bcrypt.hash(tempPassword, 10);
        
        const newUser = await db.execute(sql`
          INSERT INTO users (id, email, first_name, last_name, password, role)
          VALUES (gen_random_uuid(), ${email}, ${first_name}, ${last_name}, ${hashedPassword}, 'athlete')
          RETURNING id
        `);
        userId = (newUser.rows[0] as any).id;
      }
      
      // Check if athlete profile already exists
      const existingProfile = await db.execute(sql`SELECT id FROM athlete_profiles WHERE user_id = ${userId}`);
      if (existingProfile.rows.length > 0) {
        return res.status(400).json({ error: "An athlete profile already exists for this user" });
      }
      
      // Generate unique discount code
      const discountCode = `ATHLETE-${first_name.toUpperCase().replace(/\s+/g, '')}-${Date.now().toString(36).toUpperCase()}`;
      
      const result = await db.execute(sql`
        INSERT INTO athlete_profiles (
          id, user_id, tier, discount_code, discount_percentage, sport, 
          instagram, tiktok, youtube, bio, is_active, onboarding_completed
        )
        VALUES (
          gen_random_uuid(), ${userId}, ${tier || 'bronze'}, ${discountCode}, 
          ${discount_percentage || 50}, ${sport}, ${instagram || null}, 
          ${tiktok || null}, ${youtube || null}, ${bio || null}, true, true
        )
        RETURNING *
      `);
      
      res.json(result.rows[0]);
    } catch (error) {
      console.error("Create athlete profile error:", error);
      res.status(500).json({ error: "Failed to create athlete profile" });
    }
  });

  // Admin: Reset an influencer's password and email them a new temporary one
  app.patch("/api/admin/athlete-profiles/:id/reset-password", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;

      // Fetch athlete profile with user info, falling back to application name when first_name is null
      const profileResult = await db.execute(sql`
        SELECT ap.id, ap.user_id,
               u.email,
               COALESCE(u.first_name, split_part(aa.full_name, ' ', 1), 'Influencer') as first_name
        FROM athlete_profiles ap
        JOIN users u ON u.id = ap.user_id
        LEFT JOIN athlete_applications aa ON aa.id = ap.application_id
        WHERE ap.id = ${id}
      `);
      if (profileResult.rows.length === 0) {
        return res.status(404).json({ error: "Influencer profile not found" });
      }
      const profile = profileResult.rows[0] as any;

      // Generate a new secure 12-char temporary password using already-imported bcrypt
      const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#';
      let tempPassword = '';
      for (let i = 0; i < 12; i++) tempPassword += chars[Math.floor(Math.random() * chars.length)];

      const hashedPassword = await bcrypt.hash(tempPassword, 10);
      await db.execute(sql`UPDATE users SET password = ${hashedPassword} WHERE id = ${profile.user_id}`);

      // Email the new temporary password
      try {
        const transporter = nodemailer.createTransport({
          service: 'gmail',
          auth: {
            user: process.env.GMAIL_USER || 'noreply@1strep.com',
            pass: process.env.GMAIL_APP_PASSWORD || process.env.GMAIL_PASSWORD
          }
        });
        await transporter.sendMail({
          from: `"1stRep" <${process.env.GMAIL_USER || 'noreply@1strep.com'}>`,
          to: profile.email,
          subject: "Your 1stRep Influencer Password Has Been Reset",
          html: `
            <div style="font-family: Arial, sans-serif; background-color: #0D0D0D; color: #F5F5F0; padding: 32px;">
              <div style="max-width: 560px; margin: 0 auto;">
                <h2 style="color: #C9A84C; margin-bottom: 8px;">Password Reset</h2>
                <p>Hi ${profile.first_name},</p>
                <p>Your 1stRep influencer account password has been reset by an admin. Your new temporary password is below.</p>
                <div style="background:#1a1a1a; border:1px solid #C9A84C40; border-radius:8px; padding:20px; text-align:center; margin: 24px 0;">
                  <span style="font-size:22px; font-weight:bold; letter-spacing:3px; color:#C9A84C;">${tempPassword}</span>
                </div>
                <p>Please <a href="https://1strep.com/influencer-login" style="color:#C9A84C;">log in here</a> and use the "Forgot / Set password" link to create your own password as soon as possible.</p>
                <p style="color:#808080; font-size:13px;">If you did not expect this email, please contact us immediately.</p>
              </div>
            </div>
          `
        });
        console.log(`Password reset email sent to influencer ${profile.email}`);
      } catch (emailErr) {
        console.error("Failed to send influencer password reset email:", emailErr);
      }

      res.json({ message: "Password reset and email sent.", tempPassword });
    } catch (error) {
      console.error("Admin reset influencer password error:", error);
      res.status(500).json({ error: "Failed to reset password" });
    }
  });

  // Admin: Delete an influencer profile (reverts user role back to 'customer', keeps order history)
  app.delete("/api/admin/athlete-profiles/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;

      // Fetch profile to get user_id
      const profileResult = await db.execute(sql`SELECT user_id FROM athlete_profiles WHERE id = ${id}`);
      if (profileResult.rows.length === 0) {
        return res.status(404).json({ error: "Influencer profile not found" });
      }
      const userId = (profileResult.rows[0] as any).user_id;

      // Delete the athlete profile
      await db.execute(sql`DELETE FROM athlete_profiles WHERE id = ${id}`);

      // Revert user role back to 'customer' so they keep their account but lose influencer access
      await db.execute(sql`UPDATE users SET role = 'customer' WHERE id = ${userId}`);

      res.json({ message: "Influencer profile deleted. User account retained as customer." });
    } catch (error) {
      console.error("Admin delete influencer profile error:", error);
      res.status(500).json({ error: "Failed to delete influencer profile" });
    }
  });

  // ==================== INFLUENCER CREDIT PROGRAMME ROUTES ====================

  // Tracking link redirect (public) - /api/track/:slug -> increments clicks -> redirects to homepage
  app.get("/api/track/:slug", async (req, res) => {
    try {
      const { slug } = req.params;
      const profile = await db.execute(sql`SELECT id FROM athlete_profiles WHERE tracking_link = ${slug.toUpperCase()}`);
      if (profile.rows.length > 0) {
        await db.execute(sql`UPDATE athlete_profiles SET tracking_link_clicks = tracking_link_clicks + 1 WHERE id = ${(profile.rows[0] as any).id}`);
      }
      // tracked=1 tells the frontend RefTracker to skip double-counting this visit
      res.redirect(`/?ref=${slug.toUpperCase()}&tracked=1`);
    } catch (error) {
      res.redirect("/");
    }
  });

  // Tracking ref ping (public) - called by frontend when /?ref=SLUG is detected on page load
  // This handles the case where users visit the shared link format directly
  app.post("/api/track-ref", async (req, res) => {
    try {
      const { slug } = req.body;
      if (!slug || typeof slug !== "string") {
        return res.json({ success: false });
      }
      const profile = await db.execute(sql`SELECT id FROM athlete_profiles WHERE tracking_link = ${slug.toUpperCase()}`);
      if (profile.rows.length > 0) {
        await db.execute(sql`UPDATE athlete_profiles SET tracking_link_clicks = tracking_link_clicks + 1 WHERE id = ${(profile.rows[0] as any).id}`);
        return res.json({ success: true });
      }
      res.json({ success: false, reason: "slug not found" });
    } catch (error) {
      console.error("track-ref error:", error);
      res.json({ success: false });
    }
  });

  // GET /api/influencer/profile - own profile with credit info
  app.get("/api/influencer/profile", requireAuth, async (req, res) => {
    try {
      const profile = await db.execute(sql`
        SELECT ap.*, u.email, u.first_name, u.last_name
        FROM athlete_profiles ap
        JOIN users u ON u.id = ap.user_id
        WHERE ap.user_id = ${req.user!.id} AND ap.is_active = true
      `);
      if (profile.rows.length === 0) {
        return res.status(404).json({ error: "Profile not found" });
      }
      const profileData = profile.rows[0] as any;

      // Get variants
      const variants = await db.execute(sql`
        SELECT * FROM influencer_discount_variants WHERE athlete_profile_id = ${profileData.id} ORDER BY created_at ASC
      `);

      // Get transactions
      const transactions = await db.execute(sql`
        SELECT * FROM influencer_credit_transactions WHERE athlete_profile_id = ${profileData.id} ORDER BY created_at DESC
      `);

      // Get redemptions
      const redemptions = await db.execute(sql`
        SELECT * FROM influencer_redemptions WHERE athlete_profile_id = ${profileData.id} ORDER BY created_at DESC
      `);

      // Get personal 50% first-order discount code info
      const slug = profileData.tracking_link || '';
      const personal50Code = slug ? `${slug}50` : null;
      let personalDiscountUsed = false;
      if (personal50Code) {
        const couponRow = await db.execute(sql`
          SELECT current_uses FROM coupons WHERE UPPER(code) = UPPER(${personal50Code}) LIMIT 1
        `);
        personalDiscountUsed = couponRow.rows.length > 0 && (couponRow.rows[0] as any).current_uses >= 1;
      }

      res.json({
        profile: profileData,
        variants: variants.rows,
        transactions: transactions.rows,
        redemptions: redemptions.rows,
        personalDiscountCode: personal50Code,
        personalDiscountUsed,
      });
    } catch (error) {
      console.error("Get influencer profile error:", error);
      res.status(500).json({ error: "Failed to load influencer profile" });
    }
  });

  // POST /api/influencer/discount-variants - create new code variant
  app.post("/api/influencer/discount-variants", requireAuth, async (req, res) => {
    try {
      const { codeSuffix, customerDiscountPct, fixedCreditsPerOrder } = req.body;

      // Validate
      if (!codeSuffix || customerDiscountPct === undefined || fixedCreditsPerOrder === undefined) {
        return res.status(400).json({ error: "codeSuffix, customerDiscountPct, and fixedCreditsPerOrder are required" });
      }
      const discPct = parseInt(customerDiscountPct);
      const fixedCredits = parseInt(fixedCreditsPerOrder);
      if (isNaN(discPct) || discPct < 1 || discPct > 50) {
        return res.status(400).json({ error: "Customer discount must be between 1% and 50%" });
      }
      if (isNaN(fixedCredits) || fixedCredits < 0) {
        return res.status(400).json({ error: "Fixed credits per order must be 0 or more" });
      }
      // Cap credits per sale at 1x the discount % offered, so a code can never
      // pay out more in credits than the discount itself is costing.
      if (fixedCredits > discPct) {
        return res.status(400).json({ error: `Credits per sale can't exceed your discount % — max ${discPct} for a ${discPct}% discount` });
      }

      const profile = await db.execute(sql`SELECT id, discount_code FROM athlete_profiles WHERE user_id = ${req.user!.id}`);
      if (profile.rows.length === 0) {
        return res.status(403).json({ error: "Not an influencer" });
      }
      const profileData = profile.rows[0] as any;

      // Build full code from tracking link slug + suffix
      const profileWithSlug = await db.execute(sql`SELECT tracking_link FROM athlete_profiles WHERE id = ${profileData.id}`);
      const slug = (profileWithSlug.rows[0] as any)?.tracking_link || profileData.id.slice(0, 4).toUpperCase();
      const fullCode = `${slug}${codeSuffix.toUpperCase().replace(/[^A-Z0-9]/g, '')}`;

      // Check uniqueness
      const existing = await db.execute(sql`SELECT id FROM influencer_discount_variants WHERE full_code = ${fullCode}`);
      if (existing.rows.length > 0) {
        return res.status(400).json({ error: "This code suffix is already in use" });
      }

      // Insert variant
      const result = await db.execute(sql`
        INSERT INTO influencer_discount_variants (athlete_profile_id, code_suffix, full_code, customer_discount_pct, influencer_credit_pct, fixed_credits_per_order, is_active)
        VALUES (${profileData.id}, ${codeSuffix}, ${fullCode}, ${discPct}, 0, ${fixedCredits}, false)
        RETURNING *
      `);

      // Create coupon in coupons table
      const endDate = new Date();
      endDate.setFullYear(endDate.getFullYear() + 1);
      await db.execute(sql`
        INSERT INTO coupons (id, code, description, type, value, minimum_order_total, max_global_uses, start_date, end_date, is_active)
        VALUES (gen_random_uuid(), ${fullCode}, ${'Influencer code - ' + discPct + '% discount'}, 'percentage', ${discPct.toString()}, '0', NULL, NOW(), ${endDate.toISOString()}, false)
        ON CONFLICT (code) DO NOTHING
      `);

      res.json(result.rows[0]);
    } catch (error) {
      console.error("Create discount variant error:", error);
      res.status(500).json({ error: "Failed to create discount variant" });
    }
  });

  // PATCH /api/influencer/discount-variants/:id/activate - switch active variant
  app.patch("/api/influencer/discount-variants/:id/activate", requireAuth, async (req, res) => {
    try {
      const { id } = req.params;
      const profile = await db.execute(sql`SELECT id FROM athlete_profiles WHERE user_id = ${req.user!.id}`);
      if (profile.rows.length === 0) {
        return res.status(403).json({ error: "Not an influencer" });
      }
      const profileId = (profile.rows[0] as any).id;

      // Check variant belongs to this influencer
      const variant = await db.execute(sql`SELECT * FROM influencer_discount_variants WHERE id = ${id} AND athlete_profile_id = ${profileId}`);
      if (variant.rows.length === 0) {
        return res.status(404).json({ error: "Variant not found" });
      }
      const variantData = variant.rows[0] as any;

      // Deactivate all others, activate this one
      await db.execute(sql`UPDATE influencer_discount_variants SET is_active = false WHERE athlete_profile_id = ${profileId}`);
      await db.execute(sql`UPDATE influencer_discount_variants SET is_active = true WHERE id = ${id}`);

      // Update coupons: disable all influencer coupons for this athlete, enable this one.
      // Upsert rather than plain UPDATE — a plain UPDATE silently does nothing
      // if the coupons row doesn't exist yet (e.g. legacy variants created
      // before coupon-sync existed), leaving the code "active" in the
      // influencer's dashboard while permanently rejected at checkout.
      const allVariants = await db.execute(sql`SELECT full_code, customer_discount_pct FROM influencer_discount_variants WHERE athlete_profile_id = ${profileId}`);
      const oneYearFromNow = new Date();
      oneYearFromNow.setFullYear(oneYearFromNow.getFullYear() + 1);
      for (const v of allVariants.rows) {
        const code = (v as any).full_code;
        const discPct = (v as any).customer_discount_pct;
        const isActive = code === variantData.full_code;
        await db.execute(sql`
          INSERT INTO coupons (id, code, description, type, value, minimum_order_total, max_global_uses, start_date, end_date, is_active)
          VALUES (gen_random_uuid(), ${code}, ${'Influencer code - ' + discPct + '% discount'}, 'percentage', ${discPct.toString()}, '0', NULL, NOW(), ${oneYearFromNow.toISOString()}, ${isActive})
          ON CONFLICT (code) DO UPDATE SET is_active = ${isActive}
        `);
      }

      res.json({ success: true, activatedCode: variantData.full_code });
    } catch (error) {
      console.error("Activate variant error:", error);
      res.status(500).json({ error: "Failed to activate variant" });
    }
  });

  // POST /api/influencer/redemptions - submit redemption request
  app.post("/api/influencer/redemptions", requireAuth, async (req, res) => {
    try {
      const { type, creditAmount, notes } = req.body;
      const validTypes = ['cash_drawdown', 'store_credit', 'clothing_credit', 'gift_voucher', 'giveaway_code'];
      if (!type || !validTypes.includes(type)) {
        return res.status(400).json({ error: "Valid type is required: cash_drawdown, store_credit, clothing_credit, gift_voucher, or giveaway_code" });
      }
      const amount = parseFloat(creditAmount);
      if (isNaN(amount) || amount <= 0) {
        return res.status(400).json({ error: "Valid credit amount is required" });
      }
      if (amount < 50 || amount % 50 !== 0) {
        return res.status(400).json({ error: "Credits must be redeemed in multiples of 50 (minimum 50)" });
      }

      const profile = await db.execute(sql`SELECT id, credit_balance FROM athlete_profiles WHERE user_id = ${req.user!.id}`);
      if (profile.rows.length === 0) {
        return res.status(403).json({ error: "Not an influencer" });
      }
      const profileData = profile.rows[0] as any;

      if (parseFloat(profileData.credit_balance) < amount) {
        return res.status(400).json({ error: "Insufficient credit balance" });
      }

      // Calculate cash/store value for display in the redemption record
      const cashValue = type === 'cash_drawdown' ? (amount * 0.5).toFixed(2) : null;
      const storeValue = type === 'store_credit' ? amount.toFixed(2) : null;
      const valueNote = type === 'cash_drawdown'
        ? `Cash drawdown: ${amount} credits = £${cashValue}`
        : type === 'store_credit'
        ? `Store credit: ${amount} credits = £${storeValue} store credit`
        : `Redemption request: ${type.replace(/_/g, ' ')}`;

      // Deduct balance and insert redemption request + transaction
      await db.execute(sql`UPDATE athlete_profiles SET credit_balance = credit_balance - ${amount} WHERE id = ${profileData.id}`);
      await db.execute(sql`
        INSERT INTO influencer_credit_transactions (athlete_profile_id, type, amount, description)
        VALUES (${profileData.id}, 'redemption', ${-amount}, ${valueNote})
      `);
      const result = await db.execute(sql`
        INSERT INTO influencer_redemptions (athlete_profile_id, type, credit_amount, notes)
        VALUES (${profileData.id}, ${type}, ${amount}, ${notes || valueNote})
        RETURNING *
      `);

      res.json({ ...result.rows[0], cashValue, storeValue });
    } catch (error) {
      console.error("Submit redemption error:", error);
      res.status(500).json({ error: "Failed to submit redemption" });
    }
  });

