  // Create a new commission tier
  app.post("/api/admin/commission-tiers", requireAuth, requireAdmin, async (req, res) => {
    try {
      const tierData = insertCommissionTierSchema.extend({
        commissionRate: z.string().refine(val => {
          const rate = parseFloat(val);
          return !isNaN(rate) && rate >= 0 && rate <= 100;
        }, { message: "Commission rate must be between 0 and 100" }),
        minSalesAmount: z.string().refine(val => {
          const amount = parseFloat(val);
          return !isNaN(amount) && amount >= 0;
        }, { message: "Minimum sales amount must be 0 or greater" }),
        maxSalesAmount: z.string().optional().nullable().refine(val => {
          if (!val) return true;
          const amount = parseFloat(val);
          return !isNaN(amount) && amount >= 0;
        }, { message: "Maximum sales amount must be 0 or greater" }),
      }).refine(data => {
        if (!data.maxSalesAmount) return true;
        return parseFloat(data.maxSalesAmount) >= parseFloat(data.minSalesAmount);
      }, { message: "Maximum sales amount must be greater than or equal to minimum" }).parse(req.body);

      const tier = await storage.createCommissionTier(tierData);
      res.status(201).json(tier);
    } catch (error) {
      console.error("Create commission tier error:", error);
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: error.errors[0].message });
      }
      res.status(500).json({ error: "Failed to create commission tier" });
    }
  });

  // Update a commission tier
  app.patch("/api/admin/commission-tiers/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const updateSchema = z.object({
        name: z.string().min(1).optional(),
        partnerType: z.enum(['reseller', 'vendor']).optional(),
        commissionRate: z.string().refine(val => {
          const rate = parseFloat(val);
          return !isNaN(rate) && rate >= 0 && rate <= 100;
        }, { message: "Commission rate must be between 0 and 100" }).optional(),
        minSalesAmount: z.string().refine(val => {
          const amount = parseFloat(val);
          return !isNaN(amount) && amount >= 0;
        }, { message: "Minimum sales amount must be 0 or greater" }).optional(),
        maxSalesAmount: z.string().optional().nullable().refine(val => {
          if (val === null || val === undefined) return true;
          const amount = parseFloat(val);
          return !isNaN(amount) && amount >= 0;
        }, { message: "Maximum sales amount must be 0 or greater" }),
        isActive: z.boolean().optional(),
      });

      const updates = updateSchema.parse(req.body);
      const tier = await storage.updateCommissionTier(req.params.id, updates);
      if (!tier) {
        return res.status(404).json({ error: "Commission tier not found" });
      }
      res.json(tier);
    } catch (error) {
      console.error("Update commission tier error:", error);
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: error.errors[0].message });
      }
      res.status(500).json({ error: "Failed to update commission tier" });
    }
  });

  // Delete a commission tier
  app.delete("/api/admin/commission-tiers/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const deleted = await storage.deleteCommissionTier(req.params.id);
      if (!deleted) {
        return res.status(404).json({ error: "Commission tier not found" });
      }
      res.json({ message: "Commission tier deleted" });
    } catch (error) {
      console.error("Delete commission tier error:", error);
      res.status(500).json({ error: "Failed to delete commission tier" });
    }
  });

  // Get partner sales summary
  app.get("/api/admin/partner-sales/:partnerType/:partnerId", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { partnerType, partnerId } = req.params;
      if (!['reseller', 'vendor'].includes(partnerType)) {
        return res.status(400).json({ error: "Invalid partner type" });
      }
      const summary = await storage.getPartnerSalesSummary(partnerType as 'reseller' | 'vendor', partnerId);
      res.json(summary || { totalSalesAmount: "0.00", currentTierId: null });
    } catch (error) {
      console.error("Get partner sales summary error:", error);
      res.status(500).json({ error: "Failed to load partner sales summary" });
    }
  });

  // Get commission tier history for a partner
  app.get("/api/admin/commission-history/:partnerType/:partnerId", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { partnerType, partnerId } = req.params;
      if (!['reseller', 'vendor'].includes(partnerType)) {
        return res.status(400).json({ error: "Invalid partner type" });
      }
      const history = await storage.getCommissionTierHistory(partnerType as 'reseller' | 'vendor', partnerId);
      res.json(history);
    } catch (error) {
      console.error("Get commission tier history error:", error);
      res.status(500).json({ error: "Failed to load commission tier history" });
    }
  });

  // Manual tier adjustment (admin can manually upgrade/downgrade a partner's tier)
  app.post("/api/admin/commission-tiers/adjust", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { partnerType, partnerId, newTierId, reason } = req.body;
      if (!['reseller', 'vendor'].includes(partnerType)) {
        return res.status(400).json({ error: "Invalid partner type" });
      }

      const newTier = await storage.getCommissionTier(newTierId);
      if (!newTier) {
        return res.status(404).json({ error: "Commission tier not found" });
      }

      const summary = await storage.getPartnerSalesSummary(partnerType, partnerId);
      const currentTierId = summary?.currentTierId || null;

      // Create history record
      await storage.createCommissionTierHistory({
        partnerType,
        previousTierId: currentTierId,
        newTierId,
        salesAmountAtChange: summary?.totalSalesAmount || "0.00",
        reason: reason || 'manual_adjustment',
        ...(partnerType === 'reseller' ? { resellerId: partnerId } : { vendorId: partnerId })
      });

      // Update partner's commission rate
      if (partnerType === 'reseller') {
        await db.update(resellers).set({ commissionRate: newTier.commissionRate }).where(eq(resellers.id, partnerId));
      } else {
        await db.update(vendors).set({ commissionRate: newTier.commissionRate }).where(eq(vendors.id, partnerId));
      }

      // Update sales summary with new tier
      await storage.createOrUpdatePartnerSalesSummary({
        partnerType,
        totalSalesAmount: summary?.totalSalesAmount || "0.00",
        currentTierId: newTierId,
        ...(partnerType === 'reseller' ? { resellerId: partnerId } : { vendorId: partnerId })
      });

      res.json({ message: "Commission tier adjusted successfully", newTier });
    } catch (error) {
      console.error("Adjust commission tier error:", error);
      res.status(500).json({ error: "Failed to adjust commission tier" });
    }
  });

  // ===== COMMISSION ANALYTICS ENDPOINTS =====

  // Commission Analytics Overview - summary statistics
  app.get("/api/admin/commission-analytics/overview", requireAuth, requireAdmin, async (req, res) => {
    try {
      // Total storefront commissions from reseller_customer_orders
      const storefrontCommResult = await db.select({
        total: sql<string>`COALESCE(SUM(reseller_earnings::numeric), 0)::text`,
        count: sql<number>`COUNT(*)`
      }).from(resellerCustomerOrders).where(ne(resellerCustomerOrders.status, 'cancelled'));

      const storefrontTotal = parseFloat(storefrontCommResult[0]?.total || '0');
      const storefrontCount = Number(storefrontCommResult[0]?.count) || 0;

      // EPOS commissions: get all resellers' EPOS orders and calculate per commission rate
      const allResellersList = await db.select({ id: resellers.id, commissionRate: resellers.commissionRate, discountPercentage: resellers.discountPercentage }).from(resellers);
      const eposCancelledStatuses = ['cancelled', 'refunded', 'failed'];
      let eposTotal = 0;
      let eposCount = 0;

      const eposOrdersList = await db.select().from(customerOrders).where(isNotNull(customerOrders.resellerId));
      for (const order of eposOrdersList) {
        if (eposCancelledStatuses.includes(order.status || '')) continue;
        const resellerInfo = allResellersList.find(r => r.id === order.resellerId);
        const rate = parseFloat(resellerInfo?.commissionRate || resellerInfo?.discountPercentage || '10') / 100;
        const items = await db.select().from(customerOrderItems).where(eq(customerOrderItems.orderId, order.id));
        let orderEarnings = 0;
        for (const item of items) {
          const rev = parseFloat(item.unitPrice) * item.quantity;
          orderEarnings += item.vendorProductId ? rev : rev * rate;
        }
        if (items.length === 0) orderEarnings = parseFloat(order.totalAmount) * rate;
        eposTotal += orderEarnings;
        eposCount++;
      }

      const totalCommissions = storefrontTotal + eposTotal;
      const totalCount = storefrontCount + eposCount;

      // This month
      const startOfMonth = new Date();
      startOfMonth.setDate(1);
      startOfMonth.setHours(0, 0, 0, 0);

      const thisMonthStorefront = await db.select({
        total: sql<string>`COALESCE(SUM(reseller_earnings::numeric), 0)::text`,
        count: sql<number>`COUNT(*)`
      }).from(resellerCustomerOrders).where(
        and(ne(resellerCustomerOrders.status, 'cancelled'), gte(resellerCustomerOrders.orderDate, startOfMonth))
      );
      const thisMonthEposOrders = eposOrdersList.filter(o => new Date(o.orderDate) >= startOfMonth && !eposCancelledStatuses.includes(o.status || ''));
      let thisMonthEposTotal = 0;
      for (const order of thisMonthEposOrders) {
        const resellerInfo = allResellersList.find(r => r.id === order.resellerId);
        const rate = parseFloat(resellerInfo?.commissionRate || resellerInfo?.discountPercentage || '10') / 100;
        thisMonthEposTotal += parseFloat(order.totalAmount) * rate;
      }
      const thisMonthTotal = parseFloat(thisMonthStorefront[0]?.total || '0') + thisMonthEposTotal;
      const thisMonthCount = Number(thisMonthStorefront[0]?.count) + thisMonthEposOrders.length;

      // Active resellers (those with any orders)
      const activeResellerIds = new Set([
        ...eposOrdersList.filter(o => o.resellerId).map(o => o.resellerId!),
        ...(await db.select({ id: resellerCustomerOrders.resellerId }).from(resellerCustomerOrders)).map(o => o.id),
      ]);

      // Payout data from payout_requests
      const allPayoutRequests = await db.select().from(payoutRequests);
      const totalPaid = allPayoutRequests.filter(p => p.status === 'paid').reduce((s, p) => s + parseFloat(p.amount || '0'), 0);
      const pendingPayoutsAmount = allPayoutRequests.filter(p => ['pending','approved','processing'].includes(p.status || '')).reduce((s, p) => s + parseFloat(p.amount || '0'), 0);
      const pendingPayoutsCount = allPayoutRequests.filter(p => ['pending','approved','processing'].includes(p.status || '')).length;

      res.json({
        totalCommissions: totalCommissions.toFixed(2),
        totalCommissionCount: totalCount,
        totalPaid: totalPaid.toFixed(2),
        pendingPayouts: pendingPayoutsAmount.toFixed(2),
        thisMonthCommissions: thisMonthTotal.toFixed(2),
        thisMonthCount,
        activeResellers: activeResellerIds.size,
        activeVendors: 0,
        pendingPayoutRequests: pendingPayoutsCount
      });
    } catch (error) {
      console.error("Commission analytics overview error:", error);
      res.status(500).json({ error: "Failed to load analytics overview" });
    }
  });

  // Commission Trends - monthly/weekly data for charts
  app.get("/api/admin/commission-analytics/trends", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { period = "6months" } = req.query;
      let monthsBack = 6;
      if (period === "12months") monthsBack = 12;
      if (period === "3months") monthsBack = 3;
      const startDate = new Date();
      startDate.setMonth(startDate.getMonth() - monthsBack);
      startDate.setDate(1);
      startDate.setHours(0, 0, 0, 0);

      // Monthly EPOS earnings from commissions table
      const eposTrends = await db.select({
        month: sql<string>`TO_CHAR(${commissions.createdAt}, 'YYYY-MM')`,
        total: sql<string>`COALESCE(SUM(${commissions.commissionAmount}::numeric), 0)::text`,
        cnt: sql<number>`COUNT(*)`
      }).from(commissions)
        .where(and(gte(commissions.createdAt, startDate), ne(commissions.status, 'cancelled'), isNotNull(commissions.resellerId)))
        .groupBy(sql`TO_CHAR(${commissions.createdAt}, 'YYYY-MM')`)
        .orderBy(sql`TO_CHAR(${commissions.createdAt}, 'YYYY-MM')`);

      // Monthly storefront earnings from reseller_customer_orders
      const storefrontTrends = await db.select({
        month: sql<string>`TO_CHAR(${resellerCustomerOrders.orderDate}, 'YYYY-MM')`,
        total: sql<string>`COALESCE(SUM(reseller_earnings::numeric), 0)::text`,
        cnt: sql<number>`COUNT(*)`
      }).from(resellerCustomerOrders)
        .where(and(gte(resellerCustomerOrders.orderDate, startDate), ne(resellerCustomerOrders.status, 'cancelled')))
        .groupBy(sql`TO_CHAR(${resellerCustomerOrders.orderDate}, 'YYYY-MM')`)
        .orderBy(sql`TO_CHAR(${resellerCustomerOrders.orderDate}, 'YYYY-MM')`);

      // Merge monthly data
      const monthMap: Record<string, { totalAmount: number; count: number; resellerAmount: number; vendorAmount: number }> = {};
      for (const r of eposTrends) {
        if (!monthMap[r.month]) monthMap[r.month] = { totalAmount: 0, count: 0, resellerAmount: 0, vendorAmount: 0 };
        monthMap[r.month].totalAmount += parseFloat(r.total);
        monthMap[r.month].count += Number(r.cnt);
        monthMap[r.month].resellerAmount += parseFloat(r.total);
      }
      for (const r of storefrontTrends) {
        if (!monthMap[r.month]) monthMap[r.month] = { totalAmount: 0, count: 0, resellerAmount: 0, vendorAmount: 0 };
        monthMap[r.month].totalAmount += parseFloat(r.total);
        monthMap[r.month].count += Number(r.cnt);
        monthMap[r.month].resellerAmount += parseFloat(r.total);
      }
      const monthlyCommissions = Object.entries(monthMap)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([month, v]) => ({
          month,
          totalAmount: v.totalAmount.toFixed(2),
          count: v.count,
          resellerAmount: v.resellerAmount.toFixed(2),
          vendorAmount: v.vendorAmount.toFixed(2)
        }));

      // Monthly payout trends from payout_requests (paid ones)
      const payoutTrendsRaw = await db.select({
        month: sql<string>`TO_CHAR(${payoutRequests.updatedAt}, 'YYYY-MM')`,
        totalPaid: sql<string>`COALESCE(SUM(${payoutRequests.amount}::numeric), 0)::text`,
        count: sql<number>`COUNT(*)`
      }).from(payoutRequests)
        .where(and(eq(payoutRequests.status, 'paid'), gte(payoutRequests.updatedAt, startDate)))
        .groupBy(sql`TO_CHAR(${payoutRequests.updatedAt}, 'YYYY-MM')`)
        .orderBy(sql`TO_CHAR(${payoutRequests.updatedAt}, 'YYYY-MM')`);

      // Status breakdown from payout_requests
      const statusBreakdown = await db.select({
        status: payoutRequests.status,
        total: sql<string>`COALESCE(SUM(${payoutRequests.amount}::numeric), 0)::text`,
        count: sql<number>`COUNT(*)`
      }).from(payoutRequests).groupBy(payoutRequests.status);

      res.json({
        monthlyCommissions,
        monthlyPayouts: payoutTrendsRaw,
        statusBreakdown
      });
    } catch (error) {
      console.error("Commission analytics trends error:", error);
      res.status(500).json({ error: "Failed to load analytics trends" });
    }
  });

  // Top Earners - partners ranked by combined storefront + EPOS commission
  app.get("/api/admin/commission-analytics/top-earners", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { limit = "10", type = "all" } = req.query;
      const limitNum = Math.min(parseInt(limit as string) || 10, 50);

      // Map to accumulate per-reseller totals
      const resellerMap: Record<string, { epos: number; storefront: number; orders: number; paid: number }> = {};

      // --- EPOS earnings: from commissions table (catalogue products only) ---
      const eposRows = await db.select({
        resellerId: commissions.resellerId,
        earned: sql<string>`COALESCE(SUM(${commissions.commissionAmount}::numeric), 0)::text`,
        cnt: sql<number>`COUNT(*)`,
        paid: sql<string>`COALESCE(SUM(CASE WHEN ${commissions.status} = 'paid' THEN ${commissions.commissionAmount}::numeric ELSE 0 END), 0)::text`
      }).from(commissions)
        .where(and(isNotNull(commissions.resellerId), ne(commissions.status, 'cancelled')))
        .groupBy(commissions.resellerId);
      for (const r of eposRows) {
        if (!r.resellerId) continue;
        if (!resellerMap[r.resellerId]) resellerMap[r.resellerId] = { epos: 0, storefront: 0, orders: 0, paid: 0 };
        resellerMap[r.resellerId].epos += parseFloat(r.earned);
        resellerMap[r.resellerId].orders += Number(r.cnt);
        resellerMap[r.resellerId].paid += parseFloat(r.paid);
      }

      // Also add own-product EPOS revenue (vendor products: 100% to reseller)
      const eposOwnProductRows = await db.select({
        resellerId: customerOrders.resellerId,
        earned: sql<string>`COALESCE(SUM(coi.unit_price::numeric * coi.quantity), 0)::text`,
        cnt: sql<number>`COUNT(DISTINCT ${customerOrders.id})`
      }).from(customerOrders)
        .innerJoin(customerOrderItems, eq(customerOrderItems.orderId, customerOrders.id))
        .where(and(isNotNull(customerOrders.resellerId), isNotNull(customerOrderItems.vendorProductId), ne(customerOrders.status, 'cancelled')))
        .groupBy(customerOrders.resellerId);
      for (const r of eposOwnProductRows) {
        if (!r.resellerId) continue;
        if (!resellerMap[r.resellerId]) resellerMap[r.resellerId] = { epos: 0, storefront: 0, orders: 0, paid: 0 };
        resellerMap[r.resellerId].epos += parseFloat(r.earned);
      }

      // --- Storefront earnings: from reseller_customer_orders ---
      const storefrontRows = await db.select({
        resellerId: resellerCustomerOrders.resellerId,
        earned: sql<string>`COALESCE(SUM(reseller_earnings::numeric), 0)::text`,
        cnt: sql<number>`COUNT(*)`
      }).from(resellerCustomerOrders)
        .where(ne(resellerCustomerOrders.status, 'cancelled'))
        .groupBy(resellerCustomerOrders.resellerId);
      for (const r of storefrontRows) {
        if (!r.resellerId) continue;
        if (!resellerMap[r.resellerId]) resellerMap[r.resellerId] = { epos: 0, storefront: 0, orders: 0, paid: 0 };
        resellerMap[r.resellerId].storefront += parseFloat(r.earned);
        resellerMap[r.resellerId].orders += Number(r.cnt);
      }

      // Payout data per reseller
      const paidRows = await db.select({
        resellerId: payoutRequests.resellerId,
        paid: sql<string>`COALESCE(SUM(${payoutRequests.amount}::numeric), 0)::text`
      }).from(payoutRequests).where(eq(payoutRequests.status, 'paid')).groupBy(payoutRequests.resellerId);
      for (const r of paidRows) {
        if (r.resellerId && resellerMap[r.resellerId]) {
          resellerMap[r.resellerId].paid = parseFloat(r.paid);
        }
      }

      let topResellers: any[] = [];
      if (type === "all" || type === "reseller") {
        const sorted = Object.entries(resellerMap)
          .map(([id, v]) => ({ resellerId: id, totalEarned: (v.epos + v.storefront).toFixed(2), totalOrders: v.orders, paidAmount: v.paid.toFixed(2), pendingAmount: '0.00', storefrontEarned: v.storefront.toFixed(2), eposEarned: v.epos.toFixed(2) }))
          .sort((a, b) => parseFloat(b.totalEarned) - parseFloat(a.totalEarned))
          .slice(0, limitNum);
        for (const r of sorted) {
          const reseller = await storage.getReseller(r.resellerId);
          if (reseller) {
            topResellers.push({ ...r, partnerType: 'reseller', businessName: reseller.businessName, tier: reseller.tier, commissionRate: reseller.commissionRate });
          }
        }
      }

      const topVendors: any[] = [];

      const allPartners = [...topResellers, ...topVendors]
        .sort((a, b) => parseFloat(b.totalEarned) - parseFloat(a.totalEarned))
        .slice(0, limitNum);

      res.json({ topResellers, topVendors, topPartners: allPartners });
    } catch (error) {
      console.error("Commission analytics top earners error:", error);
      res.status(500).json({ error: "Failed to load top earners" });
    }
  });

  // Partner Performance - detailed performance for a specific partner with date filtering
  app.get("/api/admin/commission-analytics/partner/:type/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { type, id } = req.params;
      const { startDate, endDate } = req.query;
      if (!['reseller', 'vendor'].includes(type)) return res.status(400).json({ error: "Invalid partner type" });

      const start = startDate ? new Date(startDate as string) : null;
      const end = endDate ? (() => { const d = new Date(endDate as string); d.setHours(23,59,59,999); return d; })() : null;

      let partnerDetails: any = null;
      if (type === 'reseller') {
        partnerDetails = await storage.getReseller(id);
      }

      if (type === 'reseller') {
        // EPOS earnings from commissions table
        let eposWhere: any = and(eq(commissions.resellerId, id), ne(commissions.status, 'cancelled'));
        if (start) eposWhere = and(eposWhere, gte(commissions.createdAt, start));
        if (end) eposWhere = and(eposWhere, lte(commissions.createdAt, end));
        const [eposSummary] = await db.select({
          totalEarned: sql<string>`COALESCE(SUM(${commissions.commissionAmount}::numeric), 0)::text`,
          totalOrders: sql<number>`COUNT(*)`,
          paidAmount: sql<string>`COALESCE(SUM(CASE WHEN ${commissions.status} = 'paid' THEN ${commissions.commissionAmount}::numeric ELSE 0 END), 0)::text`
        }).from(commissions).where(eposWhere);

        // Storefront earnings from reseller_customer_orders
        let sfWhere: any = and(eq(resellerCustomerOrders.resellerId, id), ne(resellerCustomerOrders.status, 'cancelled'));
        if (start) sfWhere = and(sfWhere, gte(resellerCustomerOrders.orderDate, start));
        if (end) sfWhere = and(sfWhere, lte(resellerCustomerOrders.orderDate, end));
        const [sfSummary] = await db.select({
          totalEarned: sql<string>`COALESCE(SUM(reseller_earnings::numeric), 0)::text`,
          totalOrders: sql<number>`COUNT(*)`
        }).from(resellerCustomerOrders).where(sfWhere);

        // Monthly breakdown combining both
        const eposMonthly = await db.select({
          month: sql<string>`TO_CHAR(${commissions.createdAt}, 'YYYY-MM')`,
          total: sql<string>`COALESCE(SUM(${commissions.commissionAmount}::numeric), 0)::text`,
          cnt: sql<number>`COUNT(*)`
        }).from(commissions).where(eposWhere).groupBy(sql`TO_CHAR(${commissions.createdAt}, 'YYYY-MM')`).orderBy(sql`TO_CHAR(${commissions.createdAt}, 'YYYY-MM') DESC`).limit(24);

        const sfMonthly = await db.select({
          month: sql<string>`TO_CHAR(${resellerCustomerOrders.orderDate}, 'YYYY-MM')`,
          total: sql<string>`COALESCE(SUM(reseller_earnings::numeric), 0)::text`,
          cnt: sql<number>`COUNT(*)`
        }).from(resellerCustomerOrders).where(sfWhere).groupBy(sql`TO_CHAR(${resellerCustomerOrders.orderDate}, 'YYYY-MM')`).orderBy(sql`TO_CHAR(${resellerCustomerOrders.orderDate}, 'YYYY-MM') DESC`).limit(24);

        const mMap: Record<string, { total: number; count: number }> = {};
        for (const r of [...eposMonthly, ...sfMonthly]) {
          if (!mMap[r.month]) mMap[r.month] = { total: 0, count: 0 };
          mMap[r.month].total += parseFloat(r.total);
          mMap[r.month].count += Number(r.cnt);
        }
        const monthlyBreakdown = Object.entries(mMap).sort(([a],[b]) => b.localeCompare(a)).slice(0,24).map(([month, v]) => ({ month, totalAmount: v.total.toFixed(2), count: v.count, total: v.total.toFixed(2) }));

        // Payout data for this reseller
        const [paidRow] = await db.select({ paid: sql<string>`COALESCE(SUM(${payoutRequests.amount}::numeric), 0)::text` }).from(payoutRequests).where(and(eq(payoutRequests.resellerId, id), eq(payoutRequests.status, 'paid')));
        const [pendingRow] = await db.select({ pending: sql<string>`COALESCE(SUM(${payoutRequests.amount}::numeric), 0)::text` }).from(payoutRequests).where(and(eq(payoutRequests.resellerId, id), or(eq(payoutRequests.status, 'pending'), eq(payoutRequests.status, 'approved'), eq(payoutRequests.status, 'processing'))));

        const eposEarned = parseFloat(eposSummary?.totalEarned || '0');
        const sfEarned = parseFloat(sfSummary?.totalEarned || '0');
        const totalEarned = (eposEarned + sfEarned).toFixed(2);
        const totalOrders = Number(eposSummary?.totalOrders || 0) + Number(sfSummary?.totalOrders || 0);

        // Recent transactions
        const recentEpos = await db.select().from(commissions).where(and(eq(commissions.resellerId, id), ne(commissions.status, 'cancelled'))).orderBy(desc(commissions.createdAt)).limit(25);
        const recentSf = await db.select().from(resellerCustomerOrders).where(and(eq(resellerCustomerOrders.resellerId, id), ne(resellerCustomerOrders.status, 'cancelled'))).orderBy(desc(resellerCustomerOrders.orderDate)).limit(25);
        const recentCommissions = [
          ...recentEpos.map(r => ({ id: r.id, orderId: r.orderId, amount: r.commissionAmount, status: r.status, createdAt: r.createdAt, source: 'EPOS' })),
          ...recentSf.map(r => ({ id: r.id, orderId: r.id, amount: r.resellerEarnings, status: r.status, createdAt: r.orderDate, source: 'Storefront' }))
        ].sort((a,b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime()).slice(0,50);

        res.json({
          partner: partnerDetails,
          summary: { totalEarned, totalOrders, paidAmount: paidRow?.paid || '0.00', pendingAmount: pendingRow?.pending || '0.00' },
          allTimeSummary: { totalEarned, totalOrders, paidAmount: paidRow?.paid || '0.00' },
          filteredSummary: { totalEarned, totalOrders, paidAmount: paidRow?.paid || '0.00', pendingAmount: pendingRow?.pending || '0.00' },
          monthlyBreakdown,
          recentCommissions,
          breakdown: { eposEarned: eposEarned.toFixed(2), storefrontEarned: sfEarned.toFixed(2) },
          dateRange: { startDate: startDate || null, endDate: endDate || null }
        });
      } else {
        // Vendor - use commissions table as before
        const [summary] = await db.select({
          totalEarned: sql<string>`COALESCE(SUM(${commissions.commissionAmount}::numeric), 0)::text`,
          totalOrders: sql<number>`COUNT(*)`,
          paidAmount: sql<string>`COALESCE(SUM(CASE WHEN ${commissions.status} = 'paid' THEN ${commissions.commissionAmount}::numeric ELSE 0 END), 0)::text`,
          pendingAmount: sql<string>`COALESCE(SUM(CASE WHEN ${commissions.status} IN ('confirmed','requested','approved') THEN ${commissions.commissionAmount}::numeric ELSE 0 END), 0)::text`
        }).from(commissions).where(and(eq(commissions.vendorId, id), ne(commissions.status, 'cancelled')));
        res.json({ partner: partnerDetails, summary: summary || { totalEarned: '0', totalOrders: 0, paidAmount: '0', pendingAmount: '0' }, allTimeSummary: summary, filteredSummary: summary, monthlyBreakdown: [], recentCommissions: [], dateRange: { startDate: startDate || null, endDate: endDate || null } });
      }
    } catch (error) {
      console.error("Commission analytics partner performance error:", error);
      res.status(500).json({ error: "Failed to load partner performance" });
    }
  });

