  // Create or update payout schedule for a partner
  app.post("/api/admin/payout-schedules", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { partnerType, resellerId, vendorId, frequency, dayOfWeek, dayOfMonth, minimumAmount, isActive } = req.body;
      
      // Calculate next payout date
      const now = new Date();
      let nextPayoutAt = new Date();
      
      if (frequency === 'weekly') {
        const daysUntilNext = (dayOfWeek - now.getDay() + 7) % 7 || 7;
        nextPayoutAt.setDate(now.getDate() + daysUntilNext);
      } else if (frequency === 'biweekly') {
        const daysUntilNext = (dayOfWeek - now.getDay() + 14) % 14 || 14;
        nextPayoutAt.setDate(now.getDate() + daysUntilNext);
      } else if (frequency === 'monthly') {
        nextPayoutAt.setMonth(now.getMonth() + 1);
        nextPayoutAt.setDate(dayOfMonth || 1);
      }
      
      // Check if schedule already exists for this partner
      const existingSchedule = await db.select()
        .from(payoutSchedules)
        .where(
          partnerType === 'reseller' 
            ? eq(payoutSchedules.resellerId, resellerId)
            : eq(payoutSchedules.vendorId, vendorId)
        )
        .limit(1);
      
      let schedule;
      if (existingSchedule.length > 0) {
        // Update existing
        [schedule] = await db.update(payoutSchedules)
          .set({
            frequency,
            dayOfWeek: frequency === 'weekly' || frequency === 'biweekly' ? dayOfWeek : null,
            dayOfMonth: frequency === 'monthly' ? dayOfMonth : null,
            minimumAmount: minimumAmount?.toString() || '50.00',
            isActive: isActive !== undefined ? isActive : true,
            nextPayoutAt,
            updatedAt: new Date()
          })
          .where(eq(payoutSchedules.id, existingSchedule[0].id))
          .returning();
      } else {
        // Create new
        [schedule] = await db.insert(payoutSchedules).values({
          partnerType,
          resellerId: partnerType === 'reseller' ? resellerId : null,
          vendorId: partnerType === 'vendor' ? vendorId : null,
          frequency,
          dayOfWeek: frequency === 'weekly' || frequency === 'biweekly' ? dayOfWeek : null,
          dayOfMonth: frequency === 'monthly' ? dayOfMonth : null,
          minimumAmount: minimumAmount?.toString() || '50.00',
          isActive: isActive !== undefined ? isActive : true,
          nextPayoutAt
        }).returning();
      }
      
      res.json(schedule);
    } catch (error) {
      console.error("Create/update payout schedule error:", error);
      res.status(500).json({ error: "Failed to save payout schedule" });
    }
  });

