  // Process scheduled payouts (called by scheduler or manually by admin)
  app.post("/api/admin/payout-schedules/process", requireAuth, requireAdmin, async (req, res) => {
    try {
      const now = new Date();
      
      // Find all due schedules
      const dueSchedules = await db.select()
        .from(payoutSchedules)
        .where(
          and(
            eq(payoutSchedules.isActive, true),
            lte(payoutSchedules.nextPayoutAt, now)
          )
        );
      
      const results = [];
      
      for (const schedule of dueSchedules) {
        // Calculate pending commission for this partner
        const baseCondition = schedule.partnerType === 'reseller'
          ? eq(commissions.resellerId, schedule.resellerId!)
          : eq(commissions.vendorId, schedule.vendorId!);
        
        const pendingCommissions = await db.select({
          total: sql<string>`COALESCE(SUM(${commissions.commissionAmount}::numeric), 0)::text`
        })
        .from(commissions)
        .where(and(baseCondition, eq(commissions.status, 'confirmed')));
        
        const pendingAmount = parseFloat(pendingCommissions[0]?.total || '0');
        const minimumAmount = parseFloat(schedule.minimumAmount || '50');
        
        if (pendingAmount >= minimumAmount) {
          // Create payout request
          const [payout] = await db.insert(commissionPayouts).values({
            commissionType: schedule.partnerType,
            resellerId: schedule.resellerId,
            vendorId: schedule.vendorId,
            amount: pendingAmount.toString(),
            status: 'approved', // Auto-approved for scheduled payouts
            periodStart: schedule.lastPayoutAt || schedule.createdAt,
            periodEnd: now,
            notes: 'Auto-generated from scheduled payout'
          }).returning();
          
          // Update commissions to reference this payout
          await db.update(commissions)
            .set({ 
              status: 'approved',
              payoutId: payout.id 
            })
            .where(and(baseCondition, eq(commissions.status, 'confirmed')));
          
          results.push({ scheduleId: schedule.id, payoutId: payout.id, amount: pendingAmount });
          
          // Create notification
          await db.insert(adminNotifications).values({
            type: 'system',
            title: 'Scheduled Payout Created',
            message: `Auto-payout of £${pendingAmount.toFixed(2)} created for ${schedule.partnerType}`,
            link: '/admin/commission-analytics'
          });
        }
        
        // Update next payout date
        let nextPayoutAt = new Date(now);
        if (schedule.frequency === 'weekly') {
          nextPayoutAt.setDate(now.getDate() + 7);
        } else if (schedule.frequency === 'biweekly') {
          nextPayoutAt.setDate(now.getDate() + 14);
        } else if (schedule.frequency === 'monthly') {
          nextPayoutAt.setMonth(now.getMonth() + 1);
        }
        
        await db.update(payoutSchedules)
          .set({ lastPayoutAt: now, nextPayoutAt, updatedAt: now })
          .where(eq(payoutSchedules.id, schedule.id));
      }
      
      res.json({ processed: results.length, results });
    } catch (error) {
      console.error("Process scheduled payouts error:", error);
      res.status(500).json({ error: "Failed to process scheduled payouts" });
    }
  });

