  // Get commission trends over time (monthly breakdown with growth)
  app.get("/api/admin/commission-analytics/trends", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { months = "12", partnerType } = req.query;
      
      let whereConditions: any[] = [ne(commissions.status, 'cancelled')];
      if (partnerType && partnerType !== 'all') {
        whereConditions.push(eq(commissions.commissionType, partnerType as string));
      }
      
      // Get monthly trends
      const trends = await db.select({
        year: sql<number>`EXTRACT(YEAR FROM ${commissions.createdAt})`,
        month: sql<number>`EXTRACT(MONTH FROM ${commissions.createdAt})`,
        monthName: sql<string>`TO_CHAR(${commissions.createdAt}, 'Mon YYYY')`,
        totalOrders: sql<number>`COUNT(*)`,
        totalOrderValue: sql<string>`COALESCE(SUM(${commissions.orderTotal}::numeric), 0)::text`,
        totalCommission: sql<string>`COALESCE(SUM(${commissions.commissionAmount}::numeric), 0)::text`,
        avgCommissionRate: sql<string>`COALESCE(AVG(${commissions.commissionRate}::numeric), 0)::text`,
        resellerCommission: sql<string>`COALESCE(SUM(CASE WHEN ${commissions.commissionType} = 'reseller' THEN ${commissions.commissionAmount}::numeric ELSE 0 END), 0)::text`,
        vendorCommission: sql<string>`COALESCE(SUM(CASE WHEN ${commissions.commissionType} = 'vendor' THEN ${commissions.commissionAmount}::numeric ELSE 0 END), 0)::text`
      })
      .from(commissions)
      .where(and(...whereConditions))
      .groupBy(
        sql`EXTRACT(YEAR FROM ${commissions.createdAt})`,
        sql`EXTRACT(MONTH FROM ${commissions.createdAt})`,
        sql`TO_CHAR(${commissions.createdAt}, 'Mon YYYY')`
      )
      .orderBy(
        sql`EXTRACT(YEAR FROM ${commissions.createdAt}) DESC`,
        sql`EXTRACT(MONTH FROM ${commissions.createdAt}) DESC`
      )
      .limit(parseInt(months as string));
      
      // Calculate growth percentages
      const trendsWithGrowth = trends.map((current, index) => {
        const previous = trends[index + 1];
        let orderGrowth = null;
        let revenueGrowth = null;
        let commissionGrowth = null;
        
        if (previous) {
          const prevOrders = previous.totalOrders || 0;
          const prevRevenue = parseFloat(previous.totalOrderValue) || 0;
          const prevCommission = parseFloat(previous.totalCommission) || 0;
          
          if (prevOrders > 0) orderGrowth = ((current.totalOrders - prevOrders) / prevOrders * 100).toFixed(1);
          if (prevRevenue > 0) revenueGrowth = ((parseFloat(current.totalOrderValue) - prevRevenue) / prevRevenue * 100).toFixed(1);
          if (prevCommission > 0) commissionGrowth = ((parseFloat(current.totalCommission) - prevCommission) / prevCommission * 100).toFixed(1);
        }
        
        return {
          ...current,
          orderGrowth,
          revenueGrowth,
          commissionGrowth
        };
      });
      
      res.json(trendsWithGrowth.reverse()); // Return in chronological order
    } catch (error) {
      console.error("Commission trends error:", error);
      res.status(500).json({ error: "Failed to fetch commission trends" });
    }
  });

