  // Get revenue forecasting (simple exponential smoothing)
  app.get("/api/admin/commission-analytics/forecast", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { forecastMonths = "3" } = req.query;
      
      // Get last 12 months of data for forecasting
      const historicalData = await db.select({
        year: sql<number>`EXTRACT(YEAR FROM ${commissions.createdAt})`,
        month: sql<number>`EXTRACT(MONTH FROM ${commissions.createdAt})`,
        totalRevenue: sql<string>`COALESCE(SUM(${commissions.orderTotal}::numeric), 0)::text`,
        totalCommission: sql<string>`COALESCE(SUM(${commissions.commissionAmount}::numeric), 0)::text`,
        totalOrders: sql<number>`COUNT(*)`
      })
      .from(commissions)
      .where(ne(commissions.status, 'cancelled'))
      .groupBy(
        sql`EXTRACT(YEAR FROM ${commissions.createdAt})`,
        sql`EXTRACT(MONTH FROM ${commissions.createdAt})`
      )
      .orderBy(
        sql`EXTRACT(YEAR FROM ${commissions.createdAt}) DESC`,
        sql`EXTRACT(MONTH FROM ${commissions.createdAt}) DESC`
      )
      .limit(12);
      
      // Simple exponential smoothing for forecasting
      const alpha = 0.3; // Smoothing factor
      const revenueValues = historicalData.map(d => parseFloat(d.totalRevenue)).reverse();
      const commissionValues = historicalData.map(d => parseFloat(d.totalCommission)).reverse();
      const orderValues = historicalData.map(d => d.totalOrders).reverse();
      
      // Calculate smoothed values and forecast
      const smooth = (values: number[]) => {
        if (values.length === 0) return { last: 0, trend: 0 };
        let smoothed = values[0];
        for (let i = 1; i < values.length; i++) {
          smoothed = alpha * values[i] + (1 - alpha) * smoothed;
        }
        // Simple trend calculation
        const recentAvg = values.slice(-3).reduce((a, b) => a + b, 0) / Math.min(3, values.length);
        const olderAvg = values.slice(0, 3).reduce((a, b) => a + b, 0) / Math.min(3, values.length);
        const trend = values.length > 3 ? (recentAvg - olderAvg) / 3 : 0;
        return { last: smoothed, trend };
      };
      
      const revenueForecast = smooth(revenueValues);
      const commissionForecast = smooth(commissionValues);
      const orderForecast = smooth(orderValues);
      
      // Generate forecast months
      const forecasts = [];
      const now = new Date();
      
      for (let i = 1; i <= parseInt(forecastMonths as string); i++) {
        const forecastDate = new Date(now.getFullYear(), now.getMonth() + i, 1);
        forecasts.push({
          year: forecastDate.getFullYear(),
          month: forecastDate.getMonth() + 1,
          monthName: forecastDate.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' }),
          predictedRevenue: Math.max(0, revenueForecast.last + revenueForecast.trend * i).toFixed(2),
          predictedCommission: Math.max(0, commissionForecast.last + commissionForecast.trend * i).toFixed(2),
          predictedOrders: Math.max(0, Math.round(orderForecast.last + orderForecast.trend * i)),
          confidence: Math.max(50, 90 - i * 10) // Confidence decreases with distance
        });
      }
      
      res.json({
        historical: historicalData.reverse(),
        forecasts,
        summary: {
          averageMonthlyRevenue: revenueValues.length > 0 
            ? (revenueValues.reduce((a, b) => a + b, 0) / revenueValues.length).toFixed(2) 
            : '0.00',
          averageMonthlyCommission: commissionValues.length > 0 
            ? (commissionValues.reduce((a, b) => a + b, 0) / commissionValues.length).toFixed(2) 
            : '0.00',
          growthTrend: revenueForecast.trend > 0 ? 'positive' : revenueForecast.trend < 0 ? 'negative' : 'stable',
          projectedQuarterRevenue: forecasts.reduce((sum, f) => sum + parseFloat(f.predictedRevenue), 0).toFixed(2),
          projectedQuarterCommission: forecasts.reduce((sum, f) => sum + parseFloat(f.predictedCommission), 0).toFixed(2)
        }
      });
    } catch (error) {
      console.error("Commission forecast error:", error);
      res.status(500).json({ error: "Failed to generate forecast" });
    }
  });

