  // Evaluate and trigger smart notifications (can be called periodically or after specific events)
  app.post("/api/admin/smart-notifications/evaluate", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { context } = req.body; // Context like { orderId, orderTotal, partnerId, partnerType }
      
      const activeRules = await db.select()
        .from(smartNotificationRules)
        .where(eq(smartNotificationRules.isActive, true));
      
      const triggeredNotifications = [];
      
      for (const rule of activeRules) {
        const conditions = JSON.parse(rule.conditions);
        let shouldTrigger = false;
        
        // Evaluate based on rule type
        switch (rule.ruleType) {
          case 'high_value_order':
            if (context?.orderTotal && parseFloat(context.orderTotal) >= (conditions.threshold || 500)) {
              shouldTrigger = true;
            }
            break;
          case 'commission_milestone':
            if (context?.totalCommission && parseFloat(context.totalCommission) >= (conditions.milestoneAmount || 1000)) {
              shouldTrigger = true;
            }
            break;
          case 'new_partner_order':
            if (context?.isFirstOrder) {
              shouldTrigger = true;
            }
            break;
          // Add more rule type evaluations as needed
        }
        
        if (shouldTrigger) {
          const notification = await db.insert(smartNotificationLog).values({
            ruleId: rule.id,
            ruleType: rule.ruleType,
            partnerType: context?.partnerType,
            resellerId: context?.partnerType === 'reseller' ? context?.partnerId : null,
            vendorId: context?.partnerType === 'vendor' ? context?.partnerId : null,
            orderId: context?.orderId,
            title: rule.name,
            message: `${rule.description || rule.name} triggered`,
            channel: rule.channel,
            inAppCreatedAt: new Date(),
            metadata: JSON.stringify(context)
          }).returning();
          
          // Create admin notification if notifyAdmins is true
          if (rule.notifyAdmins) {
            await db.insert(adminNotifications).values({
              type: 'system',
              title: rule.name,
              message: `${rule.description || rule.name} triggered`,
              link: '/admin/smart-notifications'
            });
          }
          
          triggeredNotifications.push(notification[0]);
        }
      }
      
      res.json({ evaluated: activeRules.length, triggered: triggeredNotifications.length, notifications: triggeredNotifications });
    } catch (error) {
      console.error("Evaluate smart notifications error:", error);
      res.status(500).json({ error: "Failed to evaluate notifications" });
    }
  });

