  // Get inventory alerts (active and historical)
  app.get("/api/admin/smart-inventory/alerts", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { status, severity, type } = req.query;
      
      let query = db.select({
        alert: inventoryAlertEvents,
        product: {
          id: products.id,
          name: products.name,
          sku: products.sku,
          imageUrl: products.imageUrl
        },
        warehouse: {
          id: warehouses.id,
          name: warehouses.name,
          code: warehouses.code
        }
      })
      .from(inventoryAlertEvents)
      .leftJoin(products, eq(inventoryAlertEvents.productId, products.id))
      .leftJoin(warehouses, eq(inventoryAlertEvents.warehouseId, warehouses.id))
      .orderBy(desc(inventoryAlertEvents.createdAt));
      
      const alerts = await query;
      
      // Filter in JavaScript for flexibility
      let filtered = alerts;
      if (status === 'active') {
        filtered = filtered.filter(a => !a.alert.isResolved);
      } else if (status === 'resolved') {
        filtered = filtered.filter(a => a.alert.isResolved);
      }
      if (severity) {
        filtered = filtered.filter(a => a.alert.severity === severity);
      }
      if (type) {
        filtered = filtered.filter(a => a.alert.alertType === type);
      }
      
      // Calculate summary stats
      const summary = {
        total: alerts.length,
        active: alerts.filter(a => !a.alert.isResolved).length,
        critical: alerts.filter(a => !a.alert.isResolved && a.alert.severity === 'critical').length,
        warning: alerts.filter(a => !a.alert.isResolved && a.alert.severity === 'warning').length,
        info: alerts.filter(a => !a.alert.isResolved && a.alert.severity === 'info').length
      };
      
      res.json({ alerts: filtered, summary });
    } catch (error) {
      console.error("Get inventory alerts error:", error);
      res.status(500).json({ error: "Failed to fetch inventory alerts" });
    }
  });

