  // Calculate and update velocity metrics (can be triggered manually or by cron)
  app.post("/api/admin/smart-inventory/velocity/calculate", requireAuth, requireAdmin, async (req, res) => {
    try {
      // Get all products with their sales data
      const now = new Date();
      const last7Days = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      const last30Days = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      const last90Days = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
      
      // Get sales data from customer orders
      const productSales = await db.select({
        productId: customerOrderItems.productId,
        totalQuantity: sql<number>`SUM(${customerOrderItems.quantity})::int`,
        orderDate: customerOrders.orderDate
      })
      .from(customerOrderItems)
      .innerJoin(customerOrders, eq(customerOrderItems.orderId, customerOrders.id))
      .where(
        and(
          gte(customerOrders.orderDate, last90Days),
          eq(customerOrders.status, 'delivered')
        )
      )
      .groupBy(customerOrderItems.productId, customerOrders.orderDate);
      
      // Aggregate sales by product
      const salesByProduct = new Map<string, { last7: number; last30: number; last90: number; lastSale: Date | null }>();
      
      for (const sale of productSales) {
        const existing = salesByProduct.get(sale.productId) || { last7: 0, last30: 0, last90: 0, lastSale: null };
        const saleDate = new Date(sale.orderDate!);
        
        if (saleDate >= last7Days) existing.last7 += sale.totalQuantity;
        if (saleDate >= last30Days) existing.last30 += sale.totalQuantity;
        existing.last90 += sale.totalQuantity;
        
        if (!existing.lastSale || saleDate > existing.lastSale) {
          existing.lastSale = saleDate;
        }
        
        salesByProduct.set(sale.productId, existing);
      }
      
      // Get current stock levels
      const stockLevels = await db.select({
        productId: warehouseInventory.productId,
        totalStock: sql<number>`SUM(${warehouseInventory.quantity})::int`
      })
      .from(warehouseInventory)
      .groupBy(warehouseInventory.productId);
      
      const stockMap = new Map(stockLevels.map(s => [s.productId, s.totalStock]));
      
      // Update or insert velocity metrics
      let updated = 0;
      for (const [productId, sales] of salesByProduct.entries()) {
        const avgDailySales = sales.last30 / 30;
        const currentStock = stockMap.get(productId) || 0;
        const daysOfStock = avgDailySales > 0 ? currentStock / avgDailySales : null;
        
        // Determine demand class
        let demandClass: 'fast_mover' | 'steady' | 'slow_mover' | 'dead_stock' | 'new' = 'new';
        if (sales.last90 === 0 && sales.lastSale && (now.getTime() - sales.lastSale.getTime() > 90 * 24 * 60 * 60 * 1000)) {
          demandClass = 'dead_stock';
        } else if (avgDailySales >= 5) {
          demandClass = 'fast_mover';
        } else if (avgDailySales >= 1) {
          demandClass = 'steady';
        } else if (avgDailySales > 0) {
          demandClass = 'slow_mover';
        }
        
        // Determine velocity trend
        const trend7 = sales.last7 / 7;
        const trend30 = sales.last30 / 30;
        let velocityTrend = 'stable';
        if (trend7 > trend30 * 1.2) velocityTrend = 'increasing';
        else if (trend7 < trend30 * 0.8) velocityTrend = 'decreasing';
        
        // Update existing or insert new velocity metric
        const metricValues = {
          salesLast7Days: sales.last7,
          salesLast30Days: sales.last30,
          salesLast90Days: sales.last90,
          avgDailySales: avgDailySales.toFixed(4),
          daysOfStock: daysOfStock?.toFixed(2) || null,
          demandClass,
          velocityTrend,
          lastSaleDate: sales.lastSale,
          calculatedAt: now,
          updatedAt: now,
        };
        const existingMetric = await db
          .select({ id: salesVelocityMetrics.id })
          .from(salesVelocityMetrics)
          .where(eq(salesVelocityMetrics.productId, productId))
          .limit(1);
        if (existingMetric.length > 0) {
          await db.update(salesVelocityMetrics)
            .set(metricValues)
            .where(eq(salesVelocityMetrics.productId, productId));
        } else {
          await db.insert(salesVelocityMetrics).values({ productId, ...metricValues });
        }
        
        updated++;
      }
      
      res.json({ success: true, productsUpdated: updated });
    } catch (error) {
      console.error("Calculate velocity error:", error);
      res.status(500).json({ error: "Failed to calculate velocity metrics" });
    }
  });

  // Get reorder suggestions
