  // Get product performance analytics (best sellers, slow movers)
  app.get("/api/admin/smart-inventory/product-performance", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { period = '30' } = req.query;
      const days = parseInt(period as string);
      const startDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
      
      // Get sales by product in the period
      const salesData = await db.select({
        productId: customerOrderItems.productId,
        totalQuantity: sql<number>`SUM(${customerOrderItems.quantity})::int`,
        totalRevenue: sql<string>`SUM(${customerOrderItems.totalPrice})`,
        orderCount: sql<number>`COUNT(DISTINCT ${customerOrderItems.orderId})::int`
      })
      .from(customerOrderItems)
      .innerJoin(customerOrders, eq(customerOrderItems.orderId, customerOrders.id))
      .where(
        and(
          gte(customerOrders.orderDate, startDate),
          ne(customerOrders.status, 'cancelled')
        )
      )
      .groupBy(customerOrderItems.productId)
      .orderBy(desc(sql`SUM(${customerOrderItems.quantity})`));
      
      // Get product details
      const productDetails = await db.select({
        id: products.id,
        name: products.name,
        sku: products.sku,
        imageUrl: products.imageUrl,
        category: products.category,
        retailPrice: products.retailPrice
      }).from(products);
      
      const productMap = new Map(productDetails.map(p => [p.id, p]));
      
      // Get current stock levels
      const stockLevels = await db.select({
        productId: warehouseInventory.productId,
        totalStock: sql<number>`SUM(${warehouseInventory.quantity})::int`
      })
      .from(warehouseInventory)
      .groupBy(warehouseInventory.productId);
      
      const stockMap = new Map(stockLevels.map(s => [s.productId, s.totalStock]));
      
      // Combine data
      const performance = salesData.map(sale => ({
        ...sale,
        product: productMap.get(sale.productId),
        currentStock: stockMap.get(sale.productId) || 0,
        avgDailySales: (sale.totalQuantity / days).toFixed(2),
        revenue: parseFloat(sale.totalRevenue)
      }));
      
      // Identify best sellers (top 10) and slow movers (bottom 10 with stock)
      const bestSellers = performance.slice(0, 10);
      const withStock = performance.filter(p => (stockMap.get(p.productId) || 0) > 0);
      const slowMovers = withStock.slice(-10).reverse();
      
      // Category breakdown
      const categoryPerformance = new Map<string, { quantity: number; revenue: number; products: number }>();
      for (const p of performance) {
        const category = p.product?.category || 'Uncategorised';
        const existing = categoryPerformance.get(category) || { quantity: 0, revenue: 0, products: 0 };
        existing.quantity += p.totalQuantity;
        existing.revenue += p.revenue;
        existing.products += 1;
        categoryPerformance.set(category, existing);
      }
      
      res.json({
        period: days,
        totalProducts: performance.length,
        totalQuantitySold: performance.reduce((sum, p) => sum + p.totalQuantity, 0),
        totalRevenue: performance.reduce((sum, p) => sum + p.revenue, 0).toFixed(2),
        bestSellers,
        slowMovers,
        categoryPerformance: Object.fromEntries(categoryPerformance)
      });
    } catch (error) {
      console.error("Get product performance error:", error);
      res.status(500).json({ error: "Failed to fetch product performance" });
    }
  });

  // Inventory overview - per-product stock, value, health, velocity
  app.get("/api/admin/smart-inventory/inventory-overview", requireAuth, requireAdmin, async (req, res) => {
    try {
      const allProducts = await db.select({
        id: products.id, name: products.name, sku: products.sku,
        imageUrl: products.imageUrl, category: products.category,
        retailPrice: products.retailPrice, costPrice: products.costPrice,
      }).from(products).orderBy(products.name);

      const allVariants = await db.select({
        id: productVariants.id, productId: productVariants.productId,
        size: productVariants.size, color: productVariants.color,
        sku: productVariants.sku,
        retailPrice: productVariants.retailPrice, costPrice: productVariants.costPrice,
      }).from(productVariants);

      // Use warehouseInventory as the authoritative stock source (same as dashboard)
      const allWarehouseStock = await db.select({
        productId: warehouseInventory.productId,
        variantId: warehouseInventory.variantId,
        size: warehouseInventory.size,
        color: warehouseInventory.color,
        quantity: warehouseInventory.quantity,
      }).from(warehouseInventory);

      // Build stock lookup maps
      const stockByProduct = new Map<string, number>();
      const stockByVariant = new Map<string, number>();
      for (const ws of allWarehouseStock) {
        stockByProduct.set(ws.productId, (stockByProduct.get(ws.productId) || 0) + ws.quantity);
        if (ws.variantId) {
          stockByVariant.set(ws.variantId, (stockByVariant.get(ws.variantId) || 0) + ws.quantity);
        }
      }

      const velocityMetrics = await db.select().from(salesVelocityMetrics);
      const velocityMap = new Map(velocityMetrics.map(v => [v.productId, v]));

      // Group variants by product
      const variantsByProduct = new Map<string, typeof allVariants>();
      for (const v of allVariants) {
        const list = variantsByProduct.get(v.productId) || [];
        list.push(v);
        variantsByProduct.set(v.productId, list);
      }

      const overview = allProducts.map(product => {
        const variants = variantsByProduct.get(product.id) || [];
        // Use warehouseInventory stock (authoritative source)
        const totalStock = stockByProduct.get(product.id) || 0;
        const costPrice = parseFloat(product.costPrice || '0');
        const retailPrice = parseFloat(product.retailPrice || '0');
        const stockCostValue = costPrice * totalStock;
        const stockRetailValue = retailPrice * totalStock;
        const potentialProfit = stockRetailValue - stockCostValue;
        const margin = retailPrice > 0 ? ((retailPrice - costPrice) / retailPrice) * 100 : 0;

        const velocity = velocityMap.get(product.id);
        const daysOfStock = velocity?.daysOfStock ? parseFloat(velocity.daysOfStock) : null;

        let stockHealth: 'healthy' | 'warning' | 'critical' | 'out_of_stock' = 'healthy';
        if (totalStock === 0) stockHealth = 'out_of_stock';
        else if (totalStock <= 5) stockHealth = 'critical';
        else if (totalStock <= 20) stockHealth = 'warning';

        const variantBreakdown = variants.map(v => ({
          id: v.id, size: v.size, color: v.color, sku: v.sku,
          stock: stockByVariant.get(v.id) || 0,
          costPrice: parseFloat(v.costPrice || product.costPrice || '0'),
          retailPrice: parseFloat(v.retailPrice || product.retailPrice || '0'),
        }));

        return {
          product: { id: product.id, name: product.name, sku: product.sku, imageUrl: product.imageUrl, category: product.category },
          totalStock, stockCostValue, stockRetailValue, potentialProfit, margin,
          costPrice, retailPrice, stockHealth,
          demandClass: velocity?.demandClass || 'new',
          velocityTrend: velocity?.velocityTrend || 'stable',
          avgDailySales: velocity?.avgDailySales ? parseFloat(velocity.avgDailySales) : 0,
          daysOfStock, lastSaleDate: velocity?.lastSaleDate || null,
          variantCount: variants.length, variantBreakdown,
        };
      });

      const summary = {
        totalProducts: overview.length,
        healthy: overview.filter(p => p.stockHealth === 'healthy').length,
        warning: overview.filter(p => p.stockHealth === 'warning').length,
        critical: overview.filter(p => p.stockHealth === 'critical').length,
        outOfStock: overview.filter(p => p.stockHealth === 'out_of_stock').length,
        totalCostValue: overview.reduce((s, p) => s + p.stockCostValue, 0),
        totalRetailValue: overview.reduce((s, p) => s + p.stockRetailValue, 0),
        totalPotentialProfit: overview.reduce((s, p) => s + p.potentialProfit, 0),
        totalUnits: overview.reduce((s, p) => s + p.totalStock, 0),
      };

      res.json({ products: overview, summary });
    } catch (error) {
      console.error("Inventory overview error:", error);
      res.status(500).json({ error: "Failed to fetch inventory overview" });
    }
  });

  // Get dead stock (products with no sales in X days)
  app.get("/api/admin/smart-inventory/dead-stock", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { days = 90 } = req.query;
      const cutoffDate = new Date(Date.now() - parseInt(days as string) * 24 * 60 * 60 * 1000);
      
      // Get products with stock that haven't sold recently
      const allProducts = await db.select({
        id: products.id,
        name: products.name,
        sku: products.sku,
        imageUrl: products.imageUrl,
        category: products.category,
        wholesalePrice: products.wholesalePrice
      }).from(products).where(eq(products.isActive, true));
      
      // Get last sale date per product
      const lastSales = await db.select({
        productId: customerOrderItems.productId,
        lastSaleDate: sql<string>`MAX(${customerOrders.orderDate})`
      })
      .from(customerOrderItems)
      .innerJoin(customerOrders, eq(customerOrderItems.orderId, customerOrders.id))
      .groupBy(customerOrderItems.productId);
      
      const lastSaleMap = new Map(lastSales.map(s => [s.productId, new Date(s.lastSaleDate)]));
      
      // Get current stock
      const stockLevels = await db.select({
        productId: warehouseInventory.productId,
        totalStock: sql<number>`SUM(${warehouseInventory.quantity})::int`
      })
      .from(warehouseInventory)
      .groupBy(warehouseInventory.productId);
      
      const stockMap = new Map(stockLevels.map(s => [s.productId, s.totalStock]));
      
      // Find dead stock
      const deadStock = allProducts
        .filter(p => {
          const stock = stockMap.get(p.id) || 0;
          if (stock <= 0) return false; // No stock = not dead stock, just out of stock
          
          const lastSale = lastSaleMap.get(p.id);
          if (!lastSale) return true; // Never sold = dead stock
          return lastSale < cutoffDate;
        })
        .map(p => ({
          ...p,
          currentStock: stockMap.get(p.id) || 0,
          lastSaleDate: lastSaleMap.get(p.id) || null,
          daysSinceLastSale: lastSaleMap.get(p.id) 
            ? Math.floor((Date.now() - lastSaleMap.get(p.id)!.getTime()) / (24 * 60 * 60 * 1000))
            : null,
          stockValue: ((stockMap.get(p.id) || 0) * parseFloat(p.wholesalePrice || '0')).toFixed(2)
        }))
        .sort((a, b) => parseFloat(b.stockValue) - parseFloat(a.stockValue));
      
      const totalDeadStockValue = deadStock.reduce((sum, p) => sum + parseFloat(p.stockValue), 0);
      
      res.json({
        cutoffDays: parseInt(days as string),
        totalDeadStockProducts: deadStock.length,
        totalDeadStockUnits: deadStock.reduce((sum, p) => sum + p.currentStock, 0),
        totalDeadStockValue: totalDeadStockValue.toFixed(2),
        products: deadStock
      });
    } catch (error) {
      console.error("Get dead stock error:", error);
      res.status(500).json({ error: "Failed to fetch dead stock" });
    }
  });

  // Get warehouse utilisation
  app.get("/api/admin/smart-inventory/warehouse-utilisation", requireAuth, requireAdmin, async (req, res) => {
    try {
      const warehouseList = await db.select().from(warehouses).where(eq(warehouses.isActive, true));
      
      const utilisation = await Promise.all(warehouseList.map(async (wh) => {
        const inventory = await db.select({
          totalUnits: sql<number>`COALESCE(SUM(${warehouseInventory.quantity}), 0)::int`,
          uniqueProducts: sql<number>`COUNT(DISTINCT ${warehouseInventory.productId})::int`,
          uniqueVariants: sql<number>`COUNT(*)::int`
        })
        .from(warehouseInventory)
        .where(eq(warehouseInventory.warehouseId, wh.id));
        
        const stats = inventory[0];
        const utilisationPercentage = wh.capacity 
          ? ((stats.totalUnits / wh.capacity) * 100).toFixed(1)
          : null;
        
        // Get value of stock in this warehouse
        const stockValue = await db.select({
          totalValue: sql<string>`COALESCE(SUM(${warehouseInventory.quantity} * COALESCE(${products.wholesalePrice}::numeric, 0)), 0)`
        })
        .from(warehouseInventory)
        .innerJoin(products, eq(warehouseInventory.productId, products.id))
        .where(eq(warehouseInventory.warehouseId, wh.id));
        
        return {
          warehouse: wh,
          totalUnits: stats.totalUnits,
          uniqueProducts: stats.uniqueProducts,
          uniqueVariants: stats.uniqueVariants,
          capacity: wh.capacity,
          utilisationPercentage,
          isOverCapacity: wh.capacity ? stats.totalUnits > wh.capacity : false,
          availableCapacity: wh.capacity ? wh.capacity - stats.totalUnits : null,
          totalStockValue: stockValue[0]?.totalValue || '0'
        };
      }));
      
      const totalUnits = utilisation.reduce((sum, u) => sum + u.totalUnits, 0);
      const totalCapacity = utilisation.reduce((sum, u) => sum + (u.capacity || 0), 0);
      const totalValue = utilisation.reduce((sum, u) => sum + parseFloat(u.totalStockValue), 0);
      
      res.json({
        warehouses: utilisation,
        summary: {
          totalWarehouses: warehouseList.length,
          totalUnits,
          totalCapacity,
          overallUtilisation: totalCapacity > 0 ? ((totalUnits / totalCapacity) * 100).toFixed(1) : null,
          totalStockValue: totalValue.toFixed(2)
        }
      });
    } catch (error) {
      console.error("Get warehouse utilisation error:", error);
      res.status(500).json({ error: "Failed to fetch warehouse utilisation" });
    }
  });

