  app.patch("/api/admin/subscription-tiers/:id", requireAuth, requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      
      // Validate input with Zod
      const updateSchema = z.object({
        pricePerMonth: z.string().regex(/^\d+(\.\d{1,2})?$/, "Invalid price format").optional(),
        productLimit: z.number().int().min(1).nullable().optional(),
        displayName: z.string().min(1).max(100).optional(),
        description: z.string().max(500).optional(),
        isActive: z.boolean().optional(),
      });
      
      const validated = updateSchema.safeParse(req.body);
      if (!validated.success) {
        return res.status(400).json({ error: "Invalid input", details: validated.error.errors });
      }
      
      const { pricePerMonth, productLimit, displayName, description, isActive } = validated.data;
      
      const updates: any = {};
      if (pricePerMonth !== undefined) updates.pricePerMonth = pricePerMonth;
      if (productLimit !== undefined) updates.productLimit = productLimit;
      if (displayName !== undefined) updates.displayName = displayName;
      if (description !== undefined) updates.description = description;
      if (isActive !== undefined) updates.isActive = isActive;
      
      const updated = await storage.updateSubscriptionTier(id, updates);
      if (!updated) {
        return res.status(404).json({ error: "Subscription tier not found" });
      }
      
      res.json(updated);
    } catch (error) {
      console.error("Update subscription tier error:", error);
      res.status(500).json({ error: "Failed to update subscription tier" });
    }
  });
