  // Reseller: Create payment intent for license
  app.post("/api/reseller/license-requests/:id/create-payment", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const reseller = await storage.getResellerByUserId(user.id);
      
      if (!reseller) {
        return res.status(403).json({ error: "Reseller account not found" });
      }

      const { id } = req.params;
      const request = await storage.getResellerLicenseRequest(id);
      
      if (!request) {
        return res.status(404).json({ error: "License request not found" });
      }
      
      if (request.resellerId !== reseller.id) {
        return res.status(403).json({ error: "Not authorised to pay for this license" });
      }
      
      if (request.paymentStatus === 'paid') {
        return res.status(400).json({ error: "License has already been paid for" });
      }

      // Create Stripe payment intent
      const amount = Math.round(parseFloat(request.requestedFee) * 100); // Convert to pence
      
      const paymentIntent = await stripe.paymentIntents.create({
        amount,
        currency: 'gbp',
        statement_descriptor_suffix: '1STREP LICENSE',
        metadata: {
          type: 'reseller_license',
          requestId: request.id,
          resellerId: reseller.id
        }
      });

      // Update request with payment intent ID
      await storage.updateResellerLicenseRequest(id, {
        stripePaymentIntentId: paymentIntent.id,
        paymentStatus: 'pending'
      });

      res.json({ clientSecret: paymentIntent.client_secret });
    } catch (error) {
      console.error("Create license payment intent error:", error);
      res.status(500).json({ error: "Failed to create payment" });
    }
  });

