  // Upload document
  app.post("/api/admin/documents/upload", requireAuth, requireAdmin, documentUpload.single("file"), async (req, res) => {
    try {
      if (!req.file) return res.status(400).json({ error: "No file provided" });
      const user = req.user as User;
      const { title, description, category } = req.body;

      if (!title?.trim()) return res.status(400).json({ error: "Title is required" });

      // Upload to object storage
      const safeFileName = req.file.originalname.replace(/[^a-zA-Z0-9._-]/g, '_');
      const objectPath = `team-documents/${Date.now()}-${safeFileName}`;
      const objectStorageSvc = new ObjectStorageService();
      await objectStorageSvc.uploadPrivateBuffer(objectPath, req.file.buffer, req.file.mimetype);

      const doc = await storage.createTeamDocument({
        title: title.trim(),
        description: description?.trim() || null,
        category: category || 'general',
        fileName: req.file.originalname,
        fileType: req.file.mimetype,
        fileSize: req.file.size,
        objectPath,
        uploadedBy: user.id,
        uploadedByName: user.email || 'Unknown',
      });
      res.json(doc);
    } catch (error) {
      console.error("Upload document error:", error);
      res.status(500).json({ error: "Failed to upload document" });
    }
  });

